/* Textes des sites traduits automatiquement (à faire relire). Généré par outils/generer_audio.py */
window.BI_TEXTS = {"porte": {"fon": {"n": "Hɔn e è ma nɔ lɛkɔ wá ǎ é", "d": "Flǐn ɖaxó ɖé bo kpankɔ́n nú xù ɔ, ɖò Kannumɔ lɛ sín Ali ɔ sín vivɔnu.", "h": "È hun Hɔntogbo e jí è ma nɔ lɛkɔ wá ǎ é ɖò 1995 ɖò azɔ̌ “Kannumɔ lɛ sín Ali” e UNESCO nɔ gudo nú é mɛ, bɔ é nyí fí e è sɛ́ kannumɔ afatɔ́n kanweko mɔkpan dó Amérique ɖò xwè kanweko 17gɔ́ ɔ kpo 19gɔ́ ɔ kpo vlamɛ é sín wuntun. Nǔ e è sɔ́ ganvɔ dó bló na é xlɛ́ gantɔ́ e è wlí lɛ é sín hɔ̌nkan wè bɔ ye ɖò zɔnlin ɖi wɛ bo xwè tɔjihun ɖé kɔn. Xwewu xwewu ɔ, nǔwiwa e è nɔ bló ɖò azǎn 10gɔ́ ɔ Kɔnyásun tɔn gbè lɛ é (xwè Vodoun tɔn) nɔ dɔn jonɔ lɛ sín gbɛ̀ ɔ bǐ mɛ, bɔ kúnkan Aflikanu e è nya lɛ é tɔn gègě lɔ nɔ wá."}, "yo": {"n": "Ilekun ti Ko si pada", "d": "Iranti iranti ti o dojukọ okun, ni opin ipa-ọna Ẹrú.", "h": "Ti ṣe ifilọlẹ ni ọdun 1995 gẹgẹ bi apakan ti iṣẹ akanṣe “Ọna Ẹrú” ti UNESCO ṣe atilẹyin, Ẹnubode ti Ko si Ipadabọ ṣe samisi aaye aami nibiti awọn ọgọọgọrun egbegberun awọn igbekun ti gbe lọ si Amẹrika laarin awọn ọrundun 17th ati 19th. Idẹ idẹ rẹ ṣe afihan awọn ọwọn meji ti awọn igbekun ẹwọn ti wọn nrin si ọna ọkọ oju omi kan. Ni gbogbo ọdun, awọn ayẹyẹ ni Oṣu Kini Ọjọ 10 (Vodoun Festival) ṣe ifamọra awọn alejo lati gbogbo agbala aye, pẹlu ọpọlọpọ awọn arọmọdọmọ ti awọn ọmọ ile Afirika ti a fi silẹ."}, "ha": {"n": "Kofar Babu Komawa", "d": "Babban abin tunawa da ke fuskantar teku, a ƙarshen Hanyar Bawan.", "h": "An ƙaddamar da shi a cikin 1995 a matsayin wani ɓangare na aikin \"Hanyar Bayi\" da UNESCO ke tallafawa, Ƙofar Ba Komawa alama ce ta alama inda aka kwashe ɗaruruwan dubban fursunoni zuwa ƙasashen Amirka tsakanin ƙarni na 17 zuwa 19. Tagullar tagulla tana nuna ginshiƙai biyu na waɗanda aka ɗaure da sarƙa suna tafiya zuwa jirgi. Kowace shekara, bukukuwan da aka yi a ranar 10 ga Janairu (bikin Vodoun) na jan hankalin baƙi daga ko'ina cikin duniya, ciki har da yawancin 'ya'yan Afirka da aka kora."}, "sw": {"n": "Mlango wa Kutorudi", "d": "Ukumbusho wa ukumbusho unaoelekea baharini, mwishoni mwa Njia ya Watumwa.", "h": "Ilizinduliwa mwaka wa 1995 kama sehemu ya mradi wa \"Njia ya Watumwa\" inayoungwa mkono na UNESCO, Gate of No Return ni mahali pa mfano ambapo mamia ya maelfu ya mateka walisafirishwa hadi Amerika kati ya karne ya 17 na 19. Ukaushaji wake wa shaba unaonyesha safu mbili za mateka waliofungwa minyororo wakielekea kwenye meli. Kila mwaka, sherehe za Januari 10 (Sikukuu ya Vodoun) huvutia wageni kutoka duniani kote, ikiwa ni pamoja na wazao wengi wa Waafrika waliofukuzwa."}, "es": {"n": "Puerta sin retorno", "d": "Monumento monumental frente al océano, al final de la Ruta del Esclavo.", "h": "Inaugurada en 1995 como parte del proyecto “La Ruta del Esclavo” apoyado por la UNESCO, la Puerta sin Retorno marca el lugar simbólico donde cientos de miles de cautivos fueron enviados a las Américas entre los siglos XVII y XIX. Su friso de bronce muestra dos columnas de cautivos encadenados marchando hacia un barco. Cada año, las ceremonias del 10 de enero (fiesta vudú) atraen a visitantes de todo el mundo, incluidos muchos descendientes de africanos deportados."}, "pt": {"n": "Porta sem retorno", "d": "Memorial monumental de frente para o mar, no final da Rota dos Escravos.", "h": "Inaugurada em 1995 como parte do projeto “Rota dos Escravos” apoiado pela UNESCO, a Porta Sem Retorno marca o local simbólico onde centenas de milhares de cativos foram enviados para as Américas entre os séculos XVII e XIX. Seu friso de bronze mostra duas colunas de cativos acorrentados marchando em direção a um navio. Todos os anos, as cerimónias de 10 de janeiro (festival Vodoun) atraem visitantes de todo o mundo, incluindo muitos descendentes de africanos deportados."}, "de": {"n": "Tür ohne Wiederkehr", "d": "Monumentales Denkmal mit Blick auf den Ozean, am Ende der Sklavenroute.", "h": "Das Tor ohne Wiederkehr wurde 1995 im Rahmen des von der UNESCO unterstützten Projekts „Sklavenroute“ eingeweiht und markiert den symbolischen Ort, an dem zwischen dem 17. und 19. Jahrhundert Hunderttausende Gefangene nach Amerika verschifft wurden. Sein Bronzefries zeigt zwei Säulen angeketteter Gefangener, die auf ein Schiff zumarschieren. Jedes Jahr ziehen die Zeremonien am 10. Januar (Vodoun-Fest) Besucher aus aller Welt an, darunter viele Nachkommen deportierter Afrikaner."}, "it": {"n": "Porta del non ritorno", "d": "Memoriale monumentale di fronte all'oceano, alla fine della Via degli Schiavi.", "h": "Inaugurata nel 1995 come parte del progetto “La via degli schiavi” sostenuto dall’UNESCO, la Porta del Non Ritorno segna il luogo simbolico dove centinaia di migliaia di prigionieri furono spediti nelle Americhe tra il XVII e il XIX secolo. Il suo fregio in bronzo mostra due colonne di prigionieri incatenati che marciano verso una nave. Ogni anno, le cerimonie del 10 gennaio (festival Vodoun) attirano visitatori da tutto il mondo, tra cui molti discendenti degli africani deportati."}, "nl": {"n": "Deur van geen terugkeer", "d": "Monumentaal monument met uitzicht op de oceaan, aan het einde van de Slavenroute.", "h": "De Gate of No Return, ingehuldigd in 1995 als onderdeel van het door UNESCO gesteunde project ‘Slave Route’, markeert de symbolische plaats waar tussen de 17e en 19e eeuw honderdduizenden gevangenen naar Amerika werden verscheept. De bronzen fries toont twee colonnes geketende gevangenen die naar een schip marcheren. Elk jaar trekken de ceremonies op 10 januari (Vodoun-festival) bezoekers van over de hele wereld, waaronder veel nakomelingen van gedeporteerde Afrikanen."}, "ru": {"n": "Дверь невозврата", "d": "Монументальный мемориал с видом на океан в конце Невольничьего пути.", "h": "Ворота невозврата, открытые в 1995 году в рамках проекта «Невольничий путь», поддерживаемого ЮНЕСКО, отмечают символическое место, откуда в период с 17 по 19 века сотни тысяч пленников были отправлены в Америку. На его бронзовом фризе изображены две колонны закованных в цепи пленников, идущих к кораблю. Ежегодно церемонии 10 января (фестиваль Вуду) привлекают посетителей со всего мира, в том числе многих потомков депортированных африканцев."}, "ar": {"n": "باب اللاعودة", "d": "نصب تذكاري ضخم يواجه المحيط، في نهاية طريق العبيد.", "h": "تم افتتاح بوابة اللاعودة في عام 1995 كجزء من مشروع \"طريق العبيد\" الذي تدعمه اليونسكو، وهي تمثل المكان الرمزي الذي تم فيه شحن مئات الآلاف من الأسرى إلى الأمريكتين بين القرنين السابع عشر والتاسع عشر. يُظهر إفريزها البرونزي عمودين من الأسرى المقيدين بالسلاسل يسيرون نحو السفينة. وفي كل عام، تجتذب احتفالات يوم 10 يناير (مهرجان فودون) الزوار من جميع أنحاء العالم، ومن بينهم العديد من أحفاد الأفارقة المرحلين."}, "zh": {"n": "不归之门", "d": "面向大海的纪念馆，位于奴隶之路的尽头。", "h": "作为联合国教科文组织支持的“奴隶之路”项目的一部分，不归之门于 1995 年落成，标志着 17 世纪至 19 世纪期间数十万俘虏被运往美洲的象征性地点。它的青铜饰带展示了两列被锁链锁着的俘虏正向一艘船行进。每年 1 月 10 日（伏都教节）的仪式都会吸引来自世界各地的游客，其中包括许多被驱逐的非洲人的后裔。"}, "ja": {"n": "帰らざる扉", "d": "奴隷街道の終点、海に面した記念碑。", "h": "ユネスコが支援する「奴隷ルート」プロジェクトの一環として 1995 年に完成した帰らざる門は、17 世紀から 19 世紀にかけて数十万人の捕虜がアメリカ大陸に移送された象徴的な場所です。その青銅の装飾には、鎖につながれた捕虜の 2 つの縦列が船に向かって行進している様子が描かれています。毎年、1 月 10 日の式典（ヴォドゥン祭）には、強制送還されたアフリカ人の子孫を多く含む世界中からの観光客が集まります。"}}, "route": {"fon": {"n": "Kannumɔ sín Ali", "d": "4 km ali flínflín tɔn e ɖò Chacha Square kpo tɔ̀ tó kpo tɛntin é, bɔ è sɔ́ ɖiɖe lɛ kpo stele lɛ kpo dó bló na.", "h": "Mɛ e è wlí bɔ è sà ɖò Chacha sín kɔ́xota lɛ é ɖi zɔnlin nú kilomɛtlu 4 mɔ̌ bo yì tɔ̀ tó. Ali ɔ jí égbé ɔ, è nɔ sɔ́ nǔjlɛdonǔwu lɛ dó bló na: Atín e è nɔ wɔn é, ee è nɔ bló bɔ kannumɔ lɛ nɔ “wǎn” fí e ye gosin é lɛlɛ̌ dó é, Zomaï sín xɔ kpɛví kpɛví e mɛ è sú ye dó ɖò ablu mɛ lɛ é, flǐn Zoungbodji tɔn kpo Atín e nɔ lɛkɔ wá é kpo, ee è lin ɖɔ é na zɔ́n bɔ lindɔ̌n yetɔn lɛ na lɛkɔ wá tò yetɔn mɛ é. Nǔmɛsɛn hwe mǐtɔn nu tɔn ɖěɖee nɔ flín nǔmɛsɛn Vodun tɔn lɛ é ɖò ali ɔ jí."}, "yo": {"n": "Ẹrú Route", "d": "Ọna iranti 4 km laarin Chacha Square ati eti okun, ti o ni aami pẹlu awọn ere ati awọn steles.", "h": "Awọn igbekun ti wọn ta ni Chacha Square rin nipa 4 km si eti okun. Awọn ọna ti wa ni oni pẹlu awọn ipele aami: Igi Igbagbe, ni ayika eyiti a ṣe awọn igbekun lati \"gbagbe\" awọn orisun wọn, awọn ile Zomaï nibiti wọn ti wa ni titiipa ninu okunkun, iranti Zoungbodji ati Igi Ipadabọ, ti o yẹ ki o gba ẹmi wọn laaye lati pada si ilẹ awọn baba wọn. Awọn ere imusin ti n yọ awọn oriṣa Vodun laini opopona naa."}, "ha": {"n": "Hanyar Bayi", "d": "Hanyar tunawa da kilomita 4 tsakanin dandalin Chacha da bakin teku, wanda ke da mutum-mutumi da steles.", "h": "Mutanen da aka yi garkuwa da su a dandalin Chacha sun yi tafiyar kilomita 4 zuwa bakin teku. Hanyar a yau tana cike da matakai na alama: Bishiyar Mantuwa, wanda aka yi wa fursunoni don \"manta\" asalinsu, wuraren Zomaï inda aka kulle su a cikin duhu, tunawa da Zoungbodji da Itacen Komawa, wanda ya kamata ya bar ransu su koma ƙasar kakanninsu. Mutum-mutumi na zamani da ke korar gumakan Vodun a kan hanya."}, "sw": {"n": "Njia ya Watumwa", "d": "Njia ya ukumbusho ya kilomita 4 kati ya Chacha Square na ufuo, iliyoangaziwa na sanamu na minara.", "h": "Mateka waliouzwa katika Chacha Square walitembea takriban kilomita 4 hadi ufukweni. Njia hiyo leo ina alama za hatua za mfano: Mti wa Kusahau, ambao wafungwa walifanywa \"kusahau\" asili yao, vibanda vya Zomaï ambako walikuwa wamefungiwa gizani, ukumbusho wa Zoungbodji na Mti wa Kurudi, unaopaswa kuruhusu nafsi zao zirudi kwenye nchi ya mababu zao. Sanamu za kisasa zinazoibua miungu ya Vodun ziko barabarani."}, "es": {"n": "Ruta del esclavo", "d": "Ruta conmemorativa de 4 km entre la plaza Chacha y la playa, salpicada de estatuas y estelas.", "h": "Los cautivos vendidos en la plaza Chacha caminaron unos 4 km hasta la playa. El camino está hoy salpicado de etapas simbólicas: el Árbol del Olvido, alrededor del cual los cautivos eran obligados a “olvidar” sus orígenes, las cabañas Zomaï donde eran encerrados en la oscuridad, el monumento a Zoungbodji y el Árbol del Retorno, que supuestamente permitiría a sus almas regresar a la tierra de sus antepasados. Estatuas contemporáneas que evocan deidades vudún se alinean a lo largo de la calle."}, "pt": {"n": "Rota dos Escravos", "d": "Percurso memorial de 4 km entre a Praça Chacha e a praia, pontuado por estátuas e estelas.", "h": "Os cativos vendidos na Praça da Chacha caminharam cerca de 4 km até a praia. O caminho é hoje pontuado por etapas simbólicas: a Árvore do Esquecimento, em torno da qual os cativos foram obrigados a “esquecer” as suas origens, as cabanas Zomaï onde foram trancados na escuridão, o memorial Zoungbodji e a Árvore do Retorno, supostamente para permitir que as suas almas regressassem à terra dos seus antepassados. Estátuas contemporâneas evocando divindades Vodun alinham-se na estrada."}, "de": {"n": "Sklavenroute", "d": "4 km lange Gedenkroute zwischen dem Chacha-Platz und dem Strand, unterbrochen von Statuen und Stelen.", "h": "Gefangene, die auf dem Chacha-Platz verkauft wurden, gingen etwa 4 km zum Strand. Der Weg ist heute von symbolischen Etappen unterbrochen: dem Baum des Vergessens, um den herum die Gefangenen ihre Herkunft „vergessen“ mussten, den Zomaï-Hütten, in denen sie im Dunkeln eingesperrt wurden, dem Zoungbodji-Denkmal und dem Baum der Rückkehr, der ihren Seelen die Rückkehr in das Land ihrer Vorfahren ermöglichen soll. Zeitgenössische Statuen, die an Vodun-Gottheiten erinnern, säumen die Straße."}, "it": {"n": "Via degli schiavi", "d": "Percorso commemorativo di 4 km tra piazza Chacha e la spiaggia, punteggiato di statue e stele.", "h": "I prigionieri venduti in piazza Chacha hanno camminato per circa 4 km fino alla spiaggia. Il percorso è oggi costellato di tappe simboliche: l'Albero dell'Oblio, attorno al quale i prigionieri venivano fatti “dimenticare” le loro origini, le capanne Zomaï dove venivano rinchiusi nell'oscurità, il memoriale di Zoungbodji e l'Albero del Ritorno, che si supponeva permettesse alle loro anime di ritornare nella terra dei loro antenati. Statue contemporanee che evocano divinità Vodun fiancheggiano la strada."}, "nl": {"n": "Slavenroute", "d": "4 km herdenkingsroute tussen het Chacha-plein en het strand, onderbroken door beelden en steles.", "h": "Gevangenen die op het Chacha-plein werden verkocht, liepen ongeveer 4 km naar het strand. Het pad wordt vandaag de dag doorspekt met symbolische stadia: de Boom van Vergetelheid, waarrond de gevangenen hun oorsprong moesten ‘vergeten’, de Zomaï-hutten waar ze in het donker werden opgesloten, het Zoungbodji-monument en de Boom van Terugkeer, die hun zielen moest toestaan ​​terug te keren naar het land van hun voorouders. Hedendaagse beelden die Vodun-goden oproepen, staan ​​langs de weg."}, "ru": {"n": "Рабский путь", "d": "Мемориальный маршрут протяженностью 4 км между площадью Чача и пляжем, украшенный статуями и стелами.", "h": "Пленники, проданные на площади Чача, прошли до пляжа около 4 км. Сегодня путь отмечен символическими этапами: Древом забвения, вокруг которого пленников заставляли «забыть» свое происхождение, хижинами Зомаи, где их запирали в темноте, мемориалом Зунгбоджи и Древом возвращения, которое должно было позволить их душам вернуться на землю своих предков. Вдоль дороги стоят современные статуи, напоминающие божеств водын."}, "ar": {"n": "طريق العبيد", "d": "طريق تذكاري بطول 4 كيلومتر يقع بين ميدان تشاتشا والشاطئ ويتخلله تماثيل ونصب تذكارية.", "h": "سار الأسرى الذين تم بيعهم في ساحة تشاتشا لمسافة حوالي 4 كيلومترات إلى الشاطئ. يتخلل المسار اليوم مراحل رمزية: شجرة النسيان، التي أُجبر الأسرى حولها على \"نسيان\" أصولهم، وأكواخ زوماي حيث كانوا محبوسين في الظلام، ونصب زونغبودجي التذكاري وشجرة العودة، التي من المفترض أن تسمح لأرواحهم بالعودة إلى أرض أسلافهم. وتصطف التماثيل المعاصرة التي تستحضر آلهة الفودون على جانبي الطريق."}, "zh": {"n": "奴隶路线", "d": "洽洽广场和海滩之间 4 公里的纪念路线，路边布满了雕像和石碑。", "h": "恰恰广场出售的俘虏步行约4公里到达海滩。今天，这条道路上点缀着一些具有象征意义的阶段：遗忘之树，俘虏们被要求“忘记”他们的出身，Zomaï小屋，他们被锁在黑暗中，Zoungbodji纪念碑和回归之树，据说可以让他们的灵魂回到祖先的土地。道路两旁矗立着让人想起伏顿神祇的当代雕像。"}, "ja": {"n": "スレーブルート", "d": "銅像や石碑が点在するチャチャ広場とビーチの間の 4 km の記念ルート。", "h": "チャチャ広場で売られた捕虜は海岸まで約４キロを歩いた。現在、この道は象徴的な段階で区切られています。捕虜が自らの起源を「忘れさせる」場所となった「忘却の木」、暗闇に閉じ込められたゾーマイ小屋、ゾウンボジ記念碑、そして彼らの魂が祖先の土地に戻ることを可能にするという「帰還の木」です。ヴォドゥンの神々を思わせる現代的な彫像が道路に並んでいます。"}}, "pythons": {"fon": {"n": "Tɛnmɛ Pitɔn lɛ tɔn", "d": "Vodun sín tɛn mímɛ́ e mɛ xɛ mímɛ́ axɔsu tɔn lɛ nɔ nɔ é, bo kpankɔ́n nú basilica ɔ.", "h": "È nɔ sɛ̀n axɔsu xɛví ɔ ɖò Ouidah ɖɔ é nyí Dangbé sín agbaza, nǔmɛsɛn e nɔ cyɔn alɔ mɛ jí bo cá kàn xá axɔsuɖuto Xwéda tɔn é, ee kp’acɛ dó xá ɔ mɛ cobɔ Danxomè wá ɖu ɖò tò ɔ jí ɖò 1727 é. Dan e ma nɔ wà nǔ dó mɛ wu ǎ lɛ é mɔkpan wɛ ɖò tɛmpli ɔ mɛ bɔ jonɔ lɛ sixu kpɔ́n ye kpo alixlɛ́mɛtɔ́ ɖé kpo. Tɛn e mɛ é ɖè bo kpankɔ́n nú sinsɛnxɔ ɔ é xlɛ́ lee sinsɛn lɛ nɔ nɔ kpɔ́ gbɔn ɖò Ouidah é."}, "yo": {"n": "Temple ti awọn Pythons", "d": "Ibi mimọ Vodun nibiti awọn pythons ọba mimọ gbe, ti nkọju si basilica.", "h": "Òrìṣà ọba ni wọ́n ń bọ̀wọ̀ fún nílùú Ouidah gẹ́gẹ́ bí dídi ẹ̀yà Dángbé, òrìṣà ààbò tó ní í ṣe pẹ̀lú ìjọba Xwéda, tó jẹ́ olórí ẹkùn àgbègbè náà kí Danxomè tó ṣẹ́gun ní ọdún 1727. Gẹ́gẹ́ bí àṣà ìbílẹ̀ ti sọ, àwọn òrìṣà ran ọba lọ́wọ́ láti sá fún àwọn ọ̀tá rẹ̀. Tẹmpili jẹ ile si ọpọlọpọ awọn ejò ti ko lewu ti awọn alejo le ṣe akiyesi pẹlu itọsọna kan. Ipo rẹ ti nkọju si basilica ṣe afihan ibagbepọ awọn ẹsin ni Ouidah."}, "ha": {"n": "Temple na Pythons", "d": "Wuri Mai Tsarki na Vodun inda tsattsauran ra'ayi na sarauta ke zaune, yana fuskantar Basilica.", "h": "Ana girmama sarauta a Ouidah kamar yadda Dangbé ya kasance cikin jiki, abin bautar da ke da alaƙa da masarautar Xwéda, wanda ya mamaye yankin kafin Danxom ya ci nasara a shekara ta 1727. Bisa ga al’ada, python sun taimaka wa sarkin ya tsere wa abokan gabansa. Haikalin gida ne ga dozin macizai marasa lahani waɗanda baƙi za su iya gani tare da jagora. Matsayinta da ke fuskantar Basilica ya kwatanta zaman tare da addinai a Ouidah."}, "sw": {"n": "Hekalu la Chatu", "d": "Mahali patakatifu pa Vodun ambapo chatu watakatifu wa kifalme wanaishi, inayokabili basilica.", "h": "Chatu wa kifalme anaabudiwa huko Ouidah kuwa mwili wa Dangbé, mungu mlinzi aliyehusishwa na ufalme wa Xwéda, ambao ulitawala eneo hilo kabla ya kutekwa na Danxomè mnamo 1727. Kulingana na mapokeo, chatu walimsaidia mfalme kutoroka adui zake. Hekalu ni nyumbani kwa nyoka kadhaa wasio na madhara ambao wageni wanaweza kutazama kwa mwongozo. Msimamo wake unaokabili basilica unaonyesha kuishi pamoja kwa dini katika Ouidah."}, "es": {"n": "Templo de las pitones", "d": "Santuario vodun donde viven pitones reales sagrados, frente a la basílica.", "h": "La pitón real es venerada en Ouidah como encarnación de Dangbé, deidad protectora asociada al reino de Xwéda, que dominaba la región antes de la conquista de Danxomè en 1727. Según la tradición, las pitones ayudaron al rey a escapar de sus enemigos. El templo alberga varias docenas de serpientes inofensivas que los visitantes pueden observar con un guía. Su posición frente a la basílica ilustra la coexistencia de religiones en Ouidah."}, "pt": {"n": "Templo das Pítons", "d": "Santuário Vodun onde vivem as pítons reais sagradas, em frente à basílica.", "h": "A píton real é venerada em Ouidah como a encarnação de Dangbé, uma divindade protetora associada ao reino de Xwéda, que dominou a região antes da conquista por Danxomè em 1727. Segundo a tradição, as pítons ajudaram o rei a escapar de seus inimigos. O templo abriga dezenas de cobras inofensivas que os visitantes podem observar com um guia. A sua posição voltada para a basílica ilustra a coexistência de religiões em Ouidah."}, "de": {"n": "Tempel der Pythons", "d": "Vodun-Heiligtum, in dem heilige Königspythons leben, gegenüber der Basilika.", "h": "Der königliche Python wird in Ouidah als Inkarnation von Dangbé verehrt, einer Schutzgottheit, die mit dem Königreich Xwéda verbunden ist, das die Region vor der Eroberung durch Danxomè im Jahr 1727 beherrschte. Der Überlieferung nach halfen Pythons dem König, seinen Feinden zu entkommen. Der Tempel beherbergt mehrere Dutzend harmlose Schlangen, die Besucher mit einem Führer beobachten können. Seine Lage gegenüber der Basilika veranschaulicht das Zusammenleben der Religionen in Ouidah."}, "it": {"n": "Tempio dei Pitoni", "d": "Santuario Vodun dove vivono i pitoni sacri reali, di fronte alla basilica.", "h": "Il pitone reale è venerato a Ouidah come incarnazione di Dangbé, divinità protettrice associata al regno di Xwéda, che dominava la regione prima della conquista di Danxomè nel 1727. Secondo la tradizione, i pitoni aiutarono il re a sfuggire ai suoi nemici. Il tempio ospita diverse dozzine di serpenti innocui che i visitatori possono osservare con una guida. La sua posizione di fronte alla basilica illustra la coesistenza delle religioni a Ouidah."}, "nl": {"n": "Tempel van de Pythons", "d": "Vodun-heiligdom waar heilige koninklijke pythons leven, tegenover de basiliek.", "h": "De koninklijke python wordt in Ouidah vereerd als de incarnatie van Dangbé, een beschermende godheid geassocieerd met het koninkrijk Xwéda, dat de regio domineerde vóór de verovering door Danxomè in 1727. Volgens de traditie hielpen pythons de koning om aan zijn vijanden te ontsnappen. De tempel herbergt enkele tientallen onschuldige slangen die bezoekers met een gids kunnen observeren. De ligging tegenover de basiliek illustreert het naast elkaar bestaan ​​van religies in Ouidah."}, "ru": {"n": "Храм Питонов", "d": "Святилище Водун, где живут священные королевские питоны, напротив базилики.", "h": "Королевский питон почитается в Уиде как воплощение Дангбе, божества-защитника, связанного с королевством Шведа, которое доминировало в регионе до завоевания Данксоме в 1727 году. Согласно традиции, питоны помогли королю спастись от врагов. В храме обитает несколько десятков безобидных змей, за которыми посетители могут наблюдать с гидом. Его расположение напротив базилики иллюстрирует сосуществование религий в Уиде."}, "ar": {"n": "معبد بايثون", "d": "محمية فودون حيث تعيش الثعابين الملكية المقدسة، مقابل الكنيسة.", "h": "يتم تبجيل الثعبان الملكي في أويدا باعتباره تجسيدًا لدانغبي، وهو إله وقائي مرتبط بمملكة زويدا، التي هيمنت على المنطقة قبل غزو دانكسومي عام 1727. وفقًا للتقاليد، ساعدت الثعابين الملك على الهروب من أعدائه. يضم المعبد عشرات الثعابين غير الضارة التي يمكن للزوار مراقبتها مع مرشد. يوضح موقعها المواجه للبازيليكا تعايش الأديان في عويضة."}, "zh": {"n": "蟒蛇神庙", "d": "沃顿保护区，神圣的皇家蟒蛇居住的地方，面向大教堂。", "h": "在维达，皇家蟒蛇被尊为当贝 (Dangbé) 的化身，当贝是与 Xwéda 王国相关的保护神，Xwéda 王国在 1727 年被 Danxomè 征服之前统治着该地区。根据传统，蟒蛇帮助国王逃离了敌人。寺庙里栖息着数十条无害的蛇，游客可以在导游的带领下观察它们。它面向大教堂的位置说明了维达宗教的共存。"}, "ja": {"n": "ニシキヘビの神殿", "d": "大聖堂に面した、聖なる王のニシキヘビが生息するヴォドゥンの聖域。", "h": "王室のニシキヘビは、1727 年にダンクソメによる征服以前にこの地域を支配していたシュウェダ王国に関連する保護神であるダンベの化身としてウィダーで崇拝されています。伝統によれば、ニシキヘビは王が敵から逃げるのを助けたとされています。この寺院には数十匹の無害なヘビが生息しており、訪問者はガイドと一緒にヘビを観察することができます。大聖堂に面したその位置は、ウィダーにおける宗教の共存を示しています。"}}, "basilique": {"fon": {"n": "Basilique de la Conception Immaculée", "d": "Sinsɛnxɔ ɖaxó e è nɔ ylɔ ɖɔ néo-gothique é ɖé ɖò Ouidah sín ayi mɛ, fí e sinsɛn Katolika tɔn gosin ɖò Bénin é.", "h": "Mɛsɛ́dó Katolika tɔn nukɔntɔn e gosin Société des missions africaines mɛ lɛ é wá Ouidah ɖò 1861. Sinsɛnxɔ e ɖò ayǐ dìn é, ee è fó ɖò bǐbɛ̌mɛ xwè kanweko 20gɔ́ ɔ tɔn é ɔ, è sɔ́ ɛ ɖó tɛn e mɛ é nɔ nyí basilique ɖè é. Ouidah wɛ lɛ́ nyí fí e sinsɛnzɔ́watɛn ɖaxó e ko lín hugǎn ɖò tò ɔ mɛ é ɖè é, é wɛ nyí Saint-Gall tɔn. Pápa Benoît XVI wá finɛ ɖò 2011. Basilique ɔ kpankɔ́n nú Tɛn Mímɛ́ Pythons tɔn, ee nyí wuntun syɛnsyɛn ɖé bo nɔ xlɛ́ ɖɔ sinsɛn Benin tɔn lɛ nɔ yí gbè nú nǔ lɛ é."}, "yo": {"n": "Basilica of the Immaculate Conception", "d": "Ile ijọsin Neo-Gotik nla ti o wa ni aarin Ouidah, ijoko ti Catholicism ni Benin.", "h": "Àwọn míṣọ́nnárì Kátólíìkì àkọ́kọ́ láti Society of African Missions dé Ouidah ní 1861. Ṣọ́ọ̀ṣì tí ó wà lọ́wọ́lọ́wọ́, tí a parí ní ìbẹ̀rẹ̀ ọ̀rúndún ogún, ni a gbéga sí ipò basilica. Ouidah tun jẹ ile si ile-ẹkọ seminari ti atijọ julọ ni orilẹ-ede naa, ti Saint-Gall. Pope Benedict XVI wa nibẹ ni ọdun 2011. Basilica dojukọ Tẹmpili ti Pythons, aami ti o lagbara ti ifarada ẹsin Benin."}, "ha": {"n": "Basilica of the Immaculate Conception", "d": "Babban cocin Neo-Gothic a tsakiyar Ouidah, shimfiɗar cocin Katolika a Benin.", "h": "Masu wa’azi na Katolika na farko daga Ƙungiyar Ofishin Jakadancin Afirka sun isa Ouidah a shekara ta 1861. Ikklisiya na yanzu, wanda aka kammala a farkon ƙarni na 20, an ɗaukaka zuwa matsayin Basilica. Ouidah kuma gida ce ga babbar makarantar hauza mafi tsufa a ƙasar, ta Saint-Gall. Paparoma Benedict na 16 ya zo wurin ne a shekara ta 2011. Basilica na fuskantar Haikali na Pythons, alama ce mai ƙarfi ta jure wa addinin Benin."}, "sw": {"n": "Basilica ya Immaculate Conception", "d": "Kanisa kubwa la Neo-Gothic katikati mwa Ouidah, chimbuko la Ukatoliki nchini Benin.", "h": "Wamisionari wa kwanza wa Kikatoliki kutoka Jumuiya ya Wamisionari wa Kiafrika walifika Ouidah mwaka wa 1861. Kanisa la sasa, lililokamilishwa mwanzoni mwa karne ya 20, lilipandishwa hadhi ya basilica. Ouidah pia ni nyumbani kwa seminari kuu kongwe zaidi nchini, ile ya Saint-Gall. Papa Benedict XVI alikuja huko mwaka wa 2011. Basilica inakabiliwa na Hekalu la Pythons, ishara yenye nguvu ya uvumilivu wa kidini wa Benin."}, "es": {"n": "Basílica de la Inmaculada Concepción", "d": "Gran iglesia neogótica en el corazón de Ouidah, cuna del catolicismo en Benin.", "h": "Los primeros misioneros católicos de la Sociedad de Misiones Africanas llegaron a Ouidah en 1861. La iglesia actual, terminada a principios del siglo XX, fue elevada al rango de basílica. Ouidah alberga también el seminario mayor más antiguo del país, el de Saint-Gall. El Papa Benedicto XVI llegó allí en 2011. La basílica está frente al Templo de las Pitones, un fuerte símbolo de la tolerancia religiosa beninesa."}, "pt": {"n": "Basílica da Imaculada Conceição", "d": "Grande igreja neogótica no coração de Ouidah, berço do catolicismo no Benin.", "h": "Os primeiros missionários católicos da Sociedade das Missões Africanas chegaram a Ouidah em 1861. A atual igreja, concluída no início do século XX, foi elevada à categoria de basílica. Ouidah também abriga o seminário maior mais antigo do país, o de Saint-Gall. O Papa Bento XVI esteve lá em 2011. A basílica fica em frente ao Templo dos Pythons, um forte símbolo da tolerância religiosa beninense."}, "de": {"n": "Basilika der Unbefleckten Empfängnis", "d": "Große neugotische Kirche im Herzen von Ouidah, der Wiege des Katholizismus in Benin.", "h": "Die ersten katholischen Missionare der Society of African Missions kamen 1861 in Ouidah an. Die heutige Kirche wurde zu Beginn des 20. Jahrhunderts fertiggestellt und in den Rang einer Basilika erhoben. In Ouidah befindet sich auch das älteste große Priesterseminar des Landes, das von Saint-Gall. Papst Benedikt XVI. kam 2011 dorthin. Die Basilika liegt gegenüber dem Tempel der Pythons, einem starken Symbol der religiösen Toleranz Benins."}, "it": {"n": "Basilica dell'Immacolata Concezione", "d": "Grande chiesa neogotica nel cuore di Ouidah, culla del cattolicesimo in Benin.", "h": "I primi missionari cattolici della Società delle Missioni Africane arrivarono a Ouidah nel 1861. L'attuale chiesa, completata all'inizio del XX secolo, è stata elevata al rango di basilica. Ouidah ospita anche il seminario maggiore più antico del paese, quello di San Gallo. Papa Benedetto XVI vi è arrivato nel 2011. La basilica si affaccia sul Tempio dei Pitoni, un forte simbolo della tolleranza religiosa beninese."}, "nl": {"n": "Basiliek van de Onbevlekte Ontvangenis", "d": "Grote neogotische kerk in het hart van Ouidah, bakermat van het katholicisme in Benin.", "h": "De eerste katholieke missionarissen van de Society of African Missions arriveerden in 1861 in Ouidah. De huidige kerk, voltooid aan het begin van de 20e eeuw, werd verheven tot de rang van basiliek. Ouidah is ook de thuisbasis van het oudste grote seminarie van het land, dat van Saint-Gall. Paus Benedictus XVI kwam daar in 2011. De basiliek kijkt uit op de Tempel van de Pythons, een sterk symbool van Beninese religieuze tolerantie."}, "ru": {"n": "Базилика Непорочного Зачатия", "d": "Большая неоготическая церковь в центре Уиды, колыбели католицизма в Бенине.", "h": "Первые католические миссионеры из Общества африканских миссий прибыли в Уиду в 1861 году. Нынешняя церковь, построенная в начале 20 века, была возведена в ранг базилики. В Уиде также находится старейшая крупная семинария в стране — семинария Сен-Галла. Папа Бенедикт XVI приехал сюда в 2011 году. Базилика обращена к Храму Питонов, яркому символу религиозной толерантности Бенина."}, "ar": {"n": "كنيسة الحبل بلا دنس", "d": "كنيسة كبيرة على الطراز القوطي الجديد في قلب مدينة عويضة، مهد الكاثوليكية في بنين.", "h": "وصل المبشرون الكاثوليك الأوائل من جمعية الإرساليات الأفريقية إلى أويدا في عام 1861. وتم رفع الكنيسة الحالية، التي اكتمل بناؤها في بداية القرن العشرين، إلى رتبة بازيليكا. تعد عويضة أيضًا موطنًا لأقدم مدرسة دينية كبرى في البلاد، وهي مدرسة سان غال. جاء البابا بنديكتوس السادس عشر إلى هناك في عام 2011. وتواجه الكاتدرائية معبد بايثون، وهو رمز قوي للتسامح الديني في بنين."}, "zh": {"n": "圣母无原罪主教座堂", "d": "位于维达市中心的大型新哥特式教堂，贝宁天主教的摇篮。", "h": "1861 年，非洲宣教协会的第一批天主教传教士抵达维达。现在的教堂于 20 世纪初竣工，被提升为大教堂级别。维达也是该国最古老的主要神学院圣加尔神学院的所在地。教皇本笃十六世于 2011 年来到这里。这座大教堂面向蟒蛇神庙，这是贝宁宗教宽容的强烈象征。"}, "ja": {"n": "無原罪の御宿りの大聖堂", "d": "ベニンのカトリック発祥の地、ウィダーの中心部にある大きなネオゴシック様式の教会。", "h": "アフリカ宣教協会の最初のカトリック宣教師が 1861 年にウィダーに到着しました。現在の教会は 20 世紀初頭に完成し、大聖堂のランクに昇格しました。ウィダーには、国内最古の主要な神学校であるサンガル神学校もあります。 2011 年に教皇ベネディクト 16 世がこの地を訪れました。この大聖堂は、ベナンの宗教的寛容の強い象徴であるニシキヘビの神殿に面しています。"}}, "fort": {"fon": {"n": "Ouidah sín hwenuxóxɔsa", "d": "São João Baptista de Ajudá e nyí xɔ ɖaxó Pɔtugal tɔn ɖ’ayǐ é, bɔ dìn ɔ, é nyí nǔ e è nɔ kpɔ́n dó kannumɔjɔ́ kpo kancica e ɖò ye kpo Brésil kpo tɛntin é wu é ɖé.", "h": "Pɔtugal-nu lɛ wɛ gbá xɔ ɖaxó ɔ sín 1721, bɔ é nyí ajɔ̌tɛn ɖé, ɖò taji ɔ, nú mɛ e è wlí lɛ é. É kpó ɖò Pɔtugal sín acɛkpikpa glɔ́ kaka jɛ 1961, hwenu e Dahomey mɛɖesúsínínɔ tɔn lɛ́vɔ yí é; mɛ gudogudo tɔn e ɖò mɔ̌to ɔ mɛ lɛ é dó zo hwenu e ye ɖò yiyi wɛ é. E vɔ́ blóɖó, bɔ é hɛn Ouidah Histoire Museum sín 1967: nǔ e ɖò axɔsuɖuto Xwéda kpo Danxomè kpo tɔn mɛ lɛ é, nǔ e è wlan lɛ é, ɖiɖe lɛ kpo kúnnuɖenú lɛ kpo dó mɛ e ɖò Aflika-Brésil lɛ é jí."}, "yo": {"n": "Ouidah History Museum", "d": "Ilé olódi ilẹ̀ Potogí tẹ́lẹ̀ São João Baptista de Ajudá, ní báyìí, ó jẹ́ ibi ìkóhun-ìṣẹ̀ǹbáyé-sí ti òwò ẹrú àti ìsopọ̀ pẹ̀lú Brazil.", "h": "Ti a ṣe nipasẹ awọn Portuguese lati 1721, odi naa ṣiṣẹ bi ifiweranṣẹ iṣowo, paapaa fun awọn igbekun. O wa ni agbegbe Portuguese titi di ọdun 1961, nigbati Dahomey olominira gba ohun-ini pada; àwọn tí wọ́n wà ní ìkẹyìn fi iná sun ún bí wọ́n ṣe ń lọ. Pada pada, o ti gbe Ile ọnọ Itan-akọọlẹ Ouidah lati ọdun 1967: awọn nkan lati ijọba Xwéda ati Danxomè, awọn aworan aworan, awọn maapu ati awọn ẹri lori awọn orilẹ-ede Afro-Brazil."}, "ha": {"n": "Gidan Tarihi na Ouidah", "d": "Tsohon sansanin Portuguese São João Baptista de Ajudá, yanzu gidan kayan gargajiya na cinikin bayi kuma yana da alaƙa da Brazil.", "h": "Turawan Portugal ne suka gina shi daga shekara ta 1721, sansanin ya zama wurin ciniki, musamman ga waɗanda aka kama. Ya kasance yankin Portuguese har zuwa 1961, lokacin da Dahomey mai zaman kansa ya dawo da mallake shi; mutanen karshe sun banka mata wuta yayin da suke tafiya. An maido da shi, ya tanadi Gidan Tarihi na Ouidah tun 1967: abubuwa daga masarautar Xwéda da Danxomè, zane-zane, taswirori da shaida akan ƴan ƙasashen Afro-Brazil."}, "sw": {"n": "Makumbusho ya Historia ya Ouidah", "d": "Ngome ya zamani ya Ureno São João Baptista de Ajudá, ambayo sasa ni jumba la makumbusho la biashara ya utumwa na ina uhusiano na Brazili.", "h": "Ilijengwa na Wareno kutoka 1721, ngome hiyo ilitumika kama kituo cha biashara, haswa kwa wafungwa. Ilibakia kuwa eneo la Ureno hadi 1961, wakati Dahomey huru ilipopata tena milki yake; wakaaji wa mwisho waliichoma moto walipoondoka. Imerejeshwa, imekuwa na Jumba la Makumbusho la Historia ya Ouidah tangu 1967: vitu kutoka kwa ufalme wa Xwéda na Danxomè, michoro, ramani na ushuhuda juu ya diaspora ya Afro-Brazili."}, "es": {"n": "Museo de Historia de Ouidah", "d": "El antiguo fuerte portugués São João Baptista de Ajudá, ahora museo de la trata de esclavos y sus vínculos con Brasil.", "h": "Construido por los portugueses a partir de 1721, el fuerte sirvió como puesto comercial, especialmente para los cautivos. Siguió siendo un enclave portugués hasta 1961, cuando el Dahomey independiente recuperó la posesión; los últimos ocupantes le prendieron fuego al salir. Restaurado, alberga desde 1967 el Museo de Historia de Ouidah: objetos del reino de Xwéda y Danxomè, grabados, mapas y testimonios de la diáspora afrobrasileña."}, "pt": {"n": "Museu de História de Ouidah", "d": "O antigo forte português São João Baptista de Ajudá, hoje museu do tráfico de escravos e ligação com o Brasil.", "h": "Construído pelos portugueses a partir de 1721, o forte serviu de entreposto comercial, principalmente para cativos. Permaneceu um enclave português até 1961, quando o Daomé independente recuperou a posse; os últimos ocupantes atearam fogo ao sair. Restaurado, abriga desde 1967 o Museu Histórico de Ouidah: objetos do reino de Xwéda e Danxomè, gravuras, mapas e testemunhos sobre a diáspora afro-brasileira."}, "de": {"n": "Ouidah-Geschichtsmuseum", "d": "Die ehemalige portugiesische Festung São João Baptista de Ajudá, heute ein Museum über den Sklavenhandel und Verbindungen zu Brasilien.", "h": "Die Festung wurde ab 1721 von den Portugiesen erbaut und diente als Handelsposten, insbesondere für Gefangene. Es blieb bis 1961 eine portugiesische Enklave, als das unabhängige Dahomey den Besitz wiedererlangte; Die letzten Bewohner zündeten es beim Verlassen an. Es wurde restauriert und beherbergt seit 1967 das Ouidah-Geschichtsmuseum: Objekte aus dem Königreich Xwéda und Danxomè, Stiche, Karten und Zeugnisse über die afro-brasilianische Diaspora."}, "it": {"n": "Museo di storia di Ouidah", "d": "L'ex forte portoghese São João Baptista de Ajudá, oggi museo della tratta degli schiavi e dei legami con il Brasile.", "h": "Costruito dai portoghesi a partire dal 1721, il forte fungeva da stazione commerciale, in particolare per i prigionieri. Rimase un'enclave portoghese fino al 1961, quando il Dahomey indipendente ne riprese il possesso; gli ultimi occupanti gli hanno dato fuoco mentre se ne andavano. Restaurato, ospita dal 1967 il Museo di Storia di Ouidah: oggetti provenienti dal regno di Xwéda e Danxomè, incisioni, mappe e testimonianze sulla diaspora afrobrasiliana."}, "nl": {"n": "Historisch Museum van Ouidah", "d": "Het voormalige Portugese fort São João Baptista de Ajudá, nu een museum over de slavenhandel en banden met Brazilië.", "h": "Het fort werd vanaf 1721 door de Portugezen gebouwd en diende als handelspost, vooral voor gevangenen. Het bleef een Portugese enclave tot 1961, toen het onafhankelijke Dahomey weer bezit kreeg; de laatste bewoners staken het in brand toen ze vertrokken. Het is gerestaureerd en biedt sinds 1967 onderdak aan het Historisch Museum van Ouidah: voorwerpen uit het koninkrijk Xwéda en Danxomè, gravures, kaarten en getuigenissen over de Afro-Braziliaanse diaspora."}, "ru": {"n": "Исторический музей Уиды", "d": "Бывший португальский форт Сан-Жуан-Баптиста-де-Ажуда, ныне музей работорговли и связей с Бразилией.", "h": "Построенный португальцами в 1721 году, форт служил торговым постом, особенно для пленников. Он оставался португальским анклавом до 1961 года, когда независимая Дагомея вернула себе владение; последние жильцы подожгли его, уходя. В отреставрированном здании с 1967 года размещается Исторический музей Уиды: предметы из королевства Шведа и Данксоме, гравюры, карты и свидетельства афро-бразильской диаспоры."}, "ar": {"n": "متحف عويدة للتاريخ", "d": "الحصن البرتغالي السابق ساو جواو بابتيستا دي أجودا، وهو الآن متحف لتجارة الرقيق والروابط مع البرازيل.", "h": "تم بناء الحصن من قبل البرتغاليين في عام 1721، وكان بمثابة مركز تجاري، وخاصة للأسرى. ظلت جيبًا برتغاليًا حتى عام 1961، عندما استعادت داهومي المستقلة حيازتها؛ أشعل آخر الركاب النار فيه أثناء مغادرتهم. تم ترميمه، وهو يضم متحف أويدا للتاريخ منذ عام 1967: أشياء من مملكة زويدا ودانكسوم، ونقوش وخرائط وشهادات عن الشتات الأفريقي البرازيلي."}, "zh": {"n": "维达历史博物馆", "d": "前葡萄牙堡垒圣若昂巴普蒂斯塔德阿茹达 (São João Baptista de Ajudá)，现为奴隶贸易博物馆，与巴西有联系。", "h": "该堡垒由葡萄牙人于 1721 年建造，曾作为贸易站，特别是针对俘虏的贸易站。它一直是葡萄牙的飞地，直到 1961 年独立的达荷美重新夺回领土为止；最后的住户在离开时将其点燃。经过修复后，自 1967 年以来，这里一直是维达历史博物馆：陈列着来自 Xwéda 和 Danxomè 王国的物品、版画、地图和非裔巴西侨民的证词。"}, "ja": {"n": "ウィダー歴史博物館", "d": "かつてのポルトガルの要塞サン ジョアン洗礼者デ アジュダ。現在は奴隷貿易とブラジルとのつながりに関する博物館となっています。", "h": "1721 年からポルトガル人によって建設されたこの砦は、特に捕虜の交易所として機能しました。 1961 年に独立したダホメが領有を取り戻すまで、ポルトガルの飛び地のままでした。最後の居住者が立ち去る際に火を放った。復元され、1967 年からウィダー歴史博物館として収蔵されています。シュウェダ王国とダンショメ王国の品物、彫刻、地図、アフリカ系ブラジル人のディアスポラに関する証言が展示されています。"}}, "kpasse": {"fon": {"n": "Zungbó mímɛ́ Kpassè tɔn", "d": "Atín mímɛ́ e mɛ vodun sín ɖiɖe lɛ gɔ́ é, bɔ è ɖɔ ɖɔ Axɔsu Kpassè huzu iroko ɖò finɛ.", "h": "Ði lee è ɖɔ gbɔn ɖò xɛxó mɛ é ɔ, Kpassè, axɔsu Xwéda tɔn kpo mɛ e ɖó Ouidah ayǐ é kpo kú ǎ: kɛntɔ́ tɔn lɛ xwedó è, bo hɔn hwla cí zunkan enɛ mɛ bo huzu atín, iroko e è nɔ xlɛ́ jonɔ lɛ kaka jɛ dìn é. Atín ɔ kpó ɖò sinsɛnzɔ́watɛn ɖé nyí wɛ. Ɖo xwe kanwe ko (1990) lɛ mɛ ɔ, e nɔ hɛn ɖiɖe gan tɔn e ɖiɖetɔ Benin tɔn lɛ ɖee nɔ xlɛ Vodun sin vodun ɖaxo lɛ e: Legba, Xêvioso, Sakpata, Mami Wata..."}, "yo": {"n": "Igbo mimọ Kpassè", "d": "Igi mimọ ti o kún fun awọn ere vodun, nibiti Ọba Kpassè ti sọ pe o ti yipada si iroko.", "h": "Gẹ́gẹ́ bí ìtàn àròsọ, Kpassè, ọba Xwéda àti olùdásílẹ̀ Ouidah, kò kú: àwọn ọ̀tá rẹ̀ lépa, ó sá di igbó yìí, ó sì sọ di igi, iroko tí a ṣì ń fi hàn sí àwọn àlejò. Igi náà ti jẹ́ ibi ìjọsìn. Lati opin awọn ọdun 1990, o ti gbalejo awọn ere irin ti a tunlo nipasẹ awọn oṣere Benin ti o nsoju awọn oriṣa Vodun nla: Legba, Xêvioso, Sakpata, Mami Wata..."}, "ha": {"n": "Daji mai tsarki na Kpassè", "d": "Itace tsattsarka tana cike da sassaka-fasalin vodun, inda aka ce Sarki Kpassè ya rikide ya zama iroko.", "h": "A cewar almara, Kpassè, sarkin Xwéda kuma wanda ya kafa Ouidah, bai mutu ba: abokan gabansa sun bi shi, ya fake cikin wannan daji kuma ya rikide ya zama itace, iroko wanda har yanzu ana nunawa ga baƙi. Itace ta kasance wurin ibada. Tun daga ƙarshen 1990s, ta karbi bakuncin sake yin fa'ida na ƙarfe daga masu fasaha na Benin waɗanda ke wakiltar manyan alloli na Vodun: Legba, Xêvioso, Sakpata, Mami Wata..."}, "sw": {"n": "Msitu mtakatifu wa Kpassè", "d": "Mbao takatifu zilizo na sanamu za vodun, ambapo Mfalme Kpassè anasemekana kubadilika na kuwa iroko.", "h": "Kulingana na hadithi, Kpassè, mfalme wa Xwéda na mwanzilishi wa Ouidah, hakufa: akifuatwa na maadui zake, alikimbilia katika msitu huu na akabadilishwa kuwa mti, iroko ambalo bado linaonyeshwa kwa wageni. Mbao zimebakia kuwa mahali pa ibada. Tangu mwisho wa miaka ya 1990, imekuwa mwenyeji wa sanamu za chuma zilizosindikwa na wasanii wa Benin wanaowakilisha miungu mikuu ya Vodun: Legba, Xêvioso, Sakpata, Mami Wata..."}, "es": {"n": "Bosque sagrado de Kpassè", "d": "Bosque sagrado poblado de esculturas vodun, donde se dice que el rey Kpassè se transformó en iroko.", "h": "Según la leyenda, Kpassè, rey Xwéda y fundador de Ouidah, no murió: perseguido por sus enemigos, se refugió en este bosque y se transformó en un árbol, un iroko que todavía se muestra a los visitantes. El bosque sigue siendo un lugar de culto. Desde finales de los años 1990, alberga esculturas de metal reciclado de artistas benineses que representan a las grandes deidades vudún: Legba, Xêvioso, Sakpata, Mami Wata..."}, "pt": {"n": "Floresta sagrada de Kpassè", "d": "Madeira sagrada povoada por esculturas de vodun, onde se diz que o Rei Kpassè se transformou num iroko.", "h": "Segundo a lenda, Kpassè, rei Xwéda e fundador de Ouidah, não morreu: perseguido pelos seus inimigos, refugiou-se nesta floresta e transformou-se numa árvore, um iroko que ainda hoje é mostrado aos visitantes. A floresta continua sendo um local de culto. Desde o final da década de 1990, acolhe esculturas de metal reciclado de artistas beninenses representando as grandes divindades Vodun: Legba, Xêvioso, Sakpata, Mami Wata..."}, "de": {"n": "Heiliger Wald von Kpassè", "d": "Heiliger Wald voller Vodun-Skulpturen, in dem sich König Kpassè angeblich in einen Iroko verwandelt hat.", "h": "Der Legende nach starb Kpassè, der Xwéda-König und Gründer von Ouidah, nicht: Von seinen Feinden verfolgt, flüchtete er in diesen Wald und verwandelte sich in einen Baum, einen Iroko, der den Besuchern noch heute gezeigt wird. Der Wald ist ein Ort der Anbetung geblieben. Seit Ende der 1990er Jahre sind hier Skulpturen aus recyceltem Metall beninischer Künstler ausgestellt, die die großen Vodun-Gottheiten darstellen: Legba, Xêvioso, Sakpata, Mami Wata ..."}, "it": {"n": "Bosco sacro di Kpassè", "d": "Bosco sacro popolato di sculture vodun, dove si dice che il re Kpassè si trasformò in iroko.", "h": "Secondo la leggenda Kpassè, re Xwéda e fondatore di Ouidah, non morì: inseguito dai suoi nemici, si rifugiò in questa foresta e si trasformò in un albero, un iroko che ancora oggi viene mostrato ai visitatori. Il bosco è rimasto un luogo di culto. Dalla fine degli anni '90, ospita sculture in metallo riciclato di artisti beninesi che rappresentano le grandi divinità Vodun: Legba, Xêvioso, Sakpata, Mami Wata..."}, "nl": {"n": "Heilig bos van Kpassè", "d": "Heilig hout bevolkt met vodun-sculpturen, waar koning Kpassè naar verluidt in een iroko is veranderd.", "h": "Volgens de legende stierf Kpassè, de Xwéda-koning en stichter van Ouidah, niet: achtervolgd door zijn vijanden zocht hij zijn toevlucht in dit bos en veranderde hij in een boom, een iroko die nog steeds aan bezoekers wordt getoond. Het bos is een plaats van aanbidding gebleven. Sinds het einde van de jaren negentig zijn er gerecyclede metalen sculpturen te zien van Beninese kunstenaars die de grote Vodun-goden vertegenwoordigen: Legba, Xêvioso, Sakpata, Mami Wata..."}, "ru": {"n": "Священный лес Кпассе", "d": "Священный лес, наполненный скульптурами водуна, где, как говорят, король Кпассе превратился в ироко.", "h": "Согласно легенде, Кпассе, король Ксведы и основатель Уиды, не умер: преследуемый врагами, он укрылся в этом лесу и превратился в дерево, ироко, которое до сих пор показывают посетителям. Лес остался местом поклонения. С конца 1990-х годов здесь выставлены скульптуры из переработанного металла работы бенинских художников, представляющие великих божеств водын: Легбу, Ксевиозо, Сакпату, Мами Вату..."}, "ar": {"n": "غابة Kpassè المقدسة", "d": "خشب مقدس مليء بمنحوتات الفودون، حيث يقال إن الملك كباسي قد تحول إلى إيروكو.", "h": "وفقًا للأسطورة، فإن Kpassè، ملك Xwéda ومؤسس Ouidah، لم يمت: لقد طارده أعداؤه، ولجأ إلى هذه الغابة وتحول إلى شجرة، وهي إيروكو لا تزال تظهر للزوار. بقي الخشب مكانًا للعبادة. منذ نهاية التسعينيات، استضافت منحوتات معدنية معاد تدويرها لفنانين من بنين يمثلون آلهة الفودون العظماء: ليغبا، كسيفيوزو، ساكباتا، مامي واتا..."}, "zh": {"n": "卡帕塞神圣森林", "d": "神圣的森林里布满了伏顿雕塑，据说国王卡帕塞在这里变成了绿柄桑木。", "h": "据传说，Xwéda 国王和维达的创始人克帕塞 (Kpassè) 并没有死：在敌人的追击下，他在这片森林中避难，并变成了一棵树，即一棵绿柄桑树，至今仍向游客展示。这片树林至今仍是礼拜场所。自 20 世纪 90 年代末以来，这里一直展出由贝宁艺术家创作的回收金属雕塑，代表伟大的伏顿神祇：Legba、Xêvioso、Sakpata、Mami Wata..."}, "ja": {"n": "クパッセの神聖な森", "d": "ヴォドゥンの彫刻が数多くある神聖な木。クパッセ王がイロコに変身したと言われている場所。", "h": "伝説によると、シュウェダ王でありウィダーの創始者であるクパッセは死なず、敵に追われ、この森に避難し、木、イロコに姿を変え、今も訪問者に見せられています。この森は礼拝の場として残されています。 1990 年代の終わり以来、レグバ、ゼヴィオソ、サクパタ、マミ ワタなど、ヴォドゥンの偉大な神々を代表するベナンの芸術家によるリサイクル金属彫刻が展示されてきました。"}}, "zinsou": {"fon": {"n": "Nǔɖiɖó hwe mǐtɔn nu tɔn sín xɔ (Villa Ajavon)", "d": "Aflika sín nǔɖiɖó hwe mǐtɔn nu tɔn lɛ ɖò xɔ ɖɛkpɛɖɛkpɛ Aflika-Brésil tɔn e è vɔ́ blóɖó é ɖé mɛ.", "h": "Zinsou Foundation wɛ hun xɔ ɔ ɖò 2013, bɔ xɔ e mɛ è nɔ hɛn nǔ xóxó lɛ ɖó é ɖò Villa Ajavon, xɔ e è gbá ɖò xwè kanweko 20gɔ́ ɔ sín bǐbɛ́mɛ é ɖé, bo nɔ ɖekúnnu nú lee xwédo e lɛkɔ sín Brésil lɛ é nɔ gbá xɔ gbɔn é. E nɔ xlɛ azɔ̌ e ɖiɖetɔ́ Aflika tɔn hwe mǐtɔn nu tɔn lɛ wà é, bo nɔ lɛ́ wà azɔ̌ taji ɖé ɖò ɖiɖetɔ́ Benin tɔn lɛ sín azɔ̌kplɔnmɛ mɛ, bo nɔ lɛ́ yì wemaxɔmɛ vɔ̌nu."}, "yo": {"n": "Ile ọnọ ti aworan ode oni (Villa Ajavon)", "d": "Iṣẹ ọna ile Afirika ti ode oni ni abule Afro-Brazil ti a tun pada ti o lẹwa.", "h": "Ti ṣii ni 2013 nipasẹ Zinsou Foundation, ile musiọmu wa ni Villa Ajavon, ile aṣa Afro-Brazil ti a ṣe ni ibẹrẹ ti ọrundun 20th, jẹri si faaji ti awọn idile ti n pada lati Brazil. O ṣe afihan awọn iṣẹ nipasẹ awọn oṣere ile Afirika ti ode oni ati pe o ṣe ipa pataki ninu eto ẹkọ iṣẹ ọna ti awọn ọdọ Benin, pẹlu awọn abẹwo si ile-iwe ọfẹ."}, "ha": {"n": "Gidan kayan tarihi na fasahar zamani (Villa Ajavon)", "d": "Fasahar zamani ta Afirka a cikin kyakkyawan gida mai kyau na Afro-Brazil.", "h": "Gidauniyar Zinsou ta bude a cikin 2013, gidan kayan gargajiya ya mamaye Villa Ajavon, wani gidan salon Afro-Brazil wanda aka gina a farkon karni na 20, wanda ke shaida gine-ginen iyalai da suka dawo daga Brazil. Yana gabatar da ayyukan masu fasaha na zamani na Afirka kuma yana taka muhimmiyar rawa a cikin ilimin fasaha na matasan Benin, tare da ziyartar makaranta kyauta."}, "sw": {"n": "Makumbusho ya Sanaa ya Kisasa (Villa Ajavon)", "d": "Sanaa ya kisasa ya Kiafrika katika jumba la kifahari lililorejeshwa la Afro-Brazil.", "h": "Ilifunguliwa mnamo 2013 na Wakfu wa Zinsou, jumba la makumbusho linachukua Villa Ajavon, nyumba ya mtindo wa Kiafrika-Brazil iliyojengwa mwanzoni mwa karne ya 20, shahidi wa usanifu wa familia zinazorejea kutoka Brazili. Inatoa kazi za wasanii wa kisasa wa Kiafrika na ina jukumu muhimu katika elimu ya kisanii ya vijana wa Benin, kwa kutembelea shule bila malipo."}, "es": {"n": "Museo de Arte Contemporáneo (Villa Ajavón)", "d": "Arte africano contemporáneo en una hermosa villa afrobrasileña restaurada.", "h": "Inaugurado en 2013 por la Fundación Zinsou, el museo ocupa la Villa Ajavón, una casa de estilo afrobrasileño construida a principios del siglo XX, testigo de la arquitectura de las familias que regresaban de Brasil. Presenta obras de artistas africanos contemporáneos y desempeña un papel importante en la educación artística de los jóvenes benineses, con visitas escolares gratuitas."}, "pt": {"n": "Museu de Arte Contemporânea (Villa Ajavon)", "d": "Arte africana contemporânea em uma bela vila afro-brasileira restaurada.", "h": "Inaugurado em 2013 pela Fundação Zinsou, o museu ocupa a Villa Ajavon, uma casa de estilo afro-brasileiro construída no início do século XX, testemunha da arquitetura de famílias que retornaram do Brasil. Apresenta obras de artistas africanos contemporâneos e desempenha um papel importante na educação artística dos jovens beninenses, com visitas escolares gratuitas."}, "de": {"n": "Museum für zeitgenössische Kunst (Villa Ajavon)", "d": "Zeitgenössische afrikanische Kunst in einer wunderschönen restaurierten afro-brasilianischen Villa.", "h": "Das 2013 von der Zinsou-Stiftung eröffnete Museum befindet sich in der Villa Ajavon, einem Haus im afro-brasilianischen Stil, das zu Beginn des 20. Jahrhunderts erbaut wurde und von der Architektur aus Brasilien zurückkehrender Familien zeugt. Es präsentiert Werke zeitgenössischer afrikanischer Künstler und spielt mit kostenlosen Schulbesuchen eine wichtige Rolle in der künstlerischen Ausbildung junger Beniner."}, "it": {"n": "Museo d'Arte Contemporanea (Villa Ajavon)", "d": "Arte africana contemporanea in una bellissima villa afro-brasiliana restaurata.", "h": "Inaugurato nel 2013 dalla Fondazione Zinsou, il museo occupa Villa Ajavon, una casa in stile afrobrasiliano costruita all'inizio del XX secolo, testimone dell'architettura delle famiglie di ritorno dal Brasile. Presenta opere di artisti africani contemporanei e svolge un ruolo importante nella formazione artistica dei giovani beninesi, con visite scolastiche gratuite."}, "nl": {"n": "Museum voor Hedendaagse Kunst (Villa Ajavon)", "d": "Hedendaagse Afrikaanse kunst in een prachtig gerestaureerde Afro-Braziliaanse villa.", "h": "Het museum werd in 2013 geopend door de Zinsou Foundation en is gevestigd in Villa Ajavon, een huis in Afro-Braziliaanse stijl gebouwd aan het begin van de 20e eeuw, getuige van de architectuur van gezinnen die terugkeren uit Brazilië. Het presenteert werken van hedendaagse Afrikaanse kunstenaars en speelt een belangrijke rol in de artistieke vorming van jonge Beninezen, met gratis schoolbezoeken."}, "ru": {"n": "Музей современного искусства (Вилла Аджавон)", "d": "Современное африканское искусство в красивой отреставрированной афро-бразильской вилле.", "h": "Открытый в 2013 году Фондом Зинсу, музей занимает виллу Аджавон, дом в афро-бразильском стиле, построенный в начале 20-го века и являющийся свидетелем архитектуры семей, вернувшихся из Бразилии. Он представляет работы современных африканских художников и играет важную роль в художественном образовании молодежи Бенина, предлагая бесплатное посещение школ."}, "ar": {"n": "متحف الفن المعاصر (فيلا أجافون)", "d": "الفن الأفريقي المعاصر في فيلا برازيلية أفريقية مرممة جميلة.", "h": "افتتح المتحف عام 2013 من قبل مؤسسة زينسو، ويحتل المتحف فيلا أجافون، وهو منزل على الطراز الأفريقي البرازيلي تم بناؤه في بداية القرن العشرين، وهو شاهد على الهندسة المعمارية للعائلات العائدة من البرازيل. ويعرض أعمال الفنانين الأفارقة المعاصرين ويلعب دورا هاما في التعليم الفني للشباب البنيني، مع زيارات مدرسية مجانية."}, "zh": {"n": "当代艺术博物馆（阿贾文别墅）", "d": "一栋经过修复的美丽的非洲裔巴西别墅内藏有当代非洲艺术。", "h": "该博物馆由 Zinsou 基金会于 2013 年开放，位于阿贾文别墅 (Villa Ajavon)，这是一座建于 20 世纪初的非洲裔巴西风格房屋，见证了从巴西归来的家庭的建筑风格。它展示了当代非洲艺术家的作品，并在贝宁年轻人的艺术教育中发挥着重要作用，并提供免费学校参观。"}, "ja": {"n": "現代美術館 (ヴィラ アジャヴォン)", "d": "美しく復元されたアフリカ系ブラジル人のヴィラに現代アフリカ美術が展示されています。", "h": "Zinsou Foundation によって 2013 年にオープンしたこの博物館は、20 世紀初頭に建てられたアフリカ系ブラジル人スタイルの邸宅、Villa Ajavon 内にあり、ブラジルから帰国した家族の建築を展示しています。アフリカの現代アーティストの作品を紹介し、無料の学校訪問を通じてベナンの若者の芸術教育に重要な役割を果たしています。"}}, "zoungbodji": {"fon": {"n": "Flǐn Zoungbodji tɔn", "d": "Fí e è nɔ flín kannumɔ ɖěɖee kú cobo byɔ tɔjihun mɛ lɛ é ɖè é.", "h": "Ðò Zoungbodji ɔ, è nɔ kplé mɛ e è wlí lɛ é dó xɔ kpɛví kpɛví lɛ mɛ, bo nɔ ɖò te kpɔ́n tɔjihun lɛ sín wìwá. Mɛ gègě kú ɖò finɛ ɖó nǔcikɔ alǒ azɔn wutu, bɔ è ɖi ye dó yɔdo mɛ gègě tɔn lɛ mɛ. Flǐn e è bló ɖò xwè kanweko 1990 tɔn lɛ mɛ ɖò Kannumɔ sín Ali ɔ jí é nɔ kpa susu nú mɛ enɛ lɛ e è ma tuùn nyikɔ yetɔn ǎ lɛ é."}, "yo": {"n": "Zoungbodji Memorial", "d": "Ibi iranti igbẹhin si igbekun ti o ku ṣaaju ki o to wiwọ.", "h": "Ní Zoungbodji, wọ́n kó àwọn òǹdè náà sínú ahéré nígbà tí wọ́n ń dúró de dídé àwọn ọkọ̀ òkun náà. Ọ̀pọ̀ èèyàn ló kú níbẹ̀ nítorí àárẹ̀ tàbí àìsàn tí wọ́n sì sin ín sí ibojì ọ̀pọ̀lọpọ̀. Iranti iranti naa, ti a ṣeto ni awọn ọdun 1990 lẹba Ọna Ẹrú, san owo-ori fun awọn olufaragba ailorukọ wọnyi."}, "ha": {"n": "Zoungbodji Memorial", "d": "Wurin tunawa da aka keɓe ga waɗanda aka kama waɗanda suka mutu kafin shiga jirgi.", "h": "A Zoungbodji, an garzaya da waɗanda aka kama a cikin bukkoki a lokacin da suke jiran isowar jiragen. Da yawa sun mutu a wurin saboda gajiya ko rashin lafiya kuma an binne su a kaburbura. Taron tunawa, wanda aka gina a cikin 1990s tare da Hanyar Bayi, yana ba da yabo ga waɗannan waɗanda abin ya shafa da ba a san su ba."}, "sw": {"n": "Makumbusho ya Zoungbodji", "d": "Mahali pa kumbukumbu iliyowekwa kwa wafungwa waliokufa kabla ya kupanda.", "h": "Huko Zoungbodji, mateka waliingizwa kwenye vibanda walipokuwa wakingojea kuwasili kwa meli. Wengi walikufa huko kwa uchovu au ugonjwa na kuzikwa kwenye makaburi ya pamoja. Ukumbusho huo, uliojengwa katika miaka ya 1990 kando ya Njia ya Watumwa, hutoa heshima kwa wahasiriwa hawa wasiojulikana."}, "es": {"n": "Monumento a Zoungbodji", "d": "Lugar de memoria dedicado a los cautivos que murieron antes de abordar.", "h": "En Zoungbodji, los cautivos fueron conducidos a chozas mientras esperaban la llegada de los barcos. Muchos murieron allí de agotamiento o enfermedad y fueron enterrados en fosas comunes. El monumento, erigido en los años 1990 a lo largo de la Ruta del Esclavo, rinde homenaje a estas víctimas anónimas."}, "pt": {"n": "Memorial Zoungbodji", "d": "Local de memória dedicado aos cativos que morreram antes do embarque.", "h": "Em Zoungbodji, os cativos foram amontoados em cabanas enquanto aguardavam a chegada dos navios. Muitos morreram ali de exaustão ou doença e foram enterrados em valas comuns. O memorial, erguido na década de 1990 ao longo da Rota dos Escravos, presta homenagem a essas vítimas anônimas."}, "de": {"n": "Zoungbodji-Denkmal", "d": "Gedenkstätte für Gefangene, die vor der Einschiffung starben.", "h": "In Zoungbodji wurden die Gefangenen in Hütten zusammengetrieben, während sie auf die Ankunft der Schiffe warteten. Viele starben dort an Erschöpfung oder Krankheit und wurden in Massengräbern begraben. Das in den 1990er Jahren entlang der Sklavenroute errichtete Denkmal ist eine Hommage an diese anonymen Opfer."}, "it": {"n": "Memoriale di Zoungbodji", "d": "Luogo della memoria dedicato ai prigionieri morti prima dell'imbarco.", "h": "A Zoungbodji, i prigionieri venivano ammassati nelle capanne in attesa dell'arrivo delle navi. Molti morirono lì per stanchezza o malattia e furono sepolti in fosse comuni. Il memoriale, eretto negli anni '90 lungo la Via degli schiavi, rende omaggio a queste vittime anonime."}, "nl": {"n": "Zoungbodji-monument", "d": "Herdenkingsplaats gewijd aan gevangenen die stierven voordat ze aan boord gingen.", "h": "In Zoungbodji werden de gevangenen in hutten gedreven in afwachting van de aankomst van de schepen. Velen stierven daar door uitputting of ziekte en werden begraven in massagraven. Het monument, opgericht in de jaren negentig langs de Slavenroute, brengt hulde aan deze anonieme slachtoffers."}, "ru": {"n": "Мемориал Зунгбоджи", "d": "Место памяти, посвященное пленникам, погибшим перед посадкой на борт.", "h": "В Зунгбоджи пленников загнали в хижины в ожидании прибытия кораблей. Многие умерли там от истощения или болезней и были похоронены в братских могилах. Мемориал, установленный в 1990-х годах на Невольничьем пути, отдает дань памяти этим анонимным жертвам."}, "ar": {"n": "نصب زونجبودجي التذكاري", "d": "مكان مخصص لذكرى الأسرى الذين ماتوا قبل الصعود إلى الطائرة.", "h": "وفي زونجبودجي، تم تجميع الأسرى في أكواخ أثناء انتظار وصول السفن. مات الكثيرون هناك بسبب الإرهاق أو المرض ودُفنوا في مقابر جماعية. يشيد النصب التذكاري، الذي تم تشييده في التسعينيات على طول طريق العبيد، بهؤلاء الضحايا المجهولين."}, "zh": {"n": "宗博吉纪念馆", "d": "纪念登船前死去的俘虏的地方。", "h": "在宗博吉，俘虏们被赶进小屋，等待船只到来。许多人因疲惫或疾病而死在那里，并被埋在万人坑中。这座纪念碑建于 20 世纪 90 年代，沿着奴隶之路，向这些匿名受害者致敬。"}, "ja": {"n": "ズンボジ記念碑", "d": "乗船前に亡くなった捕虜を追悼する場所。", "h": "ズンボジでは、捕虜たちは船の到着を待つ間小屋に集められた。多くの人がそこで疲労や病気で亡くなり、集団墓地に埋葬された。この記念碑は、1990 年代に奴隷街道沿いに建てられ、これらの匿名の犠牲者に敬意を表しています。"}}, "lama": {"fon": {"n": "Lama sɔ́ zunkan ɖó vo", "d": "Zùn ɖaxó gudogudo tɔn e ɖò tofɔligbé lɛ é ɖokpo, fí e xɛ e nɔ ɖó adɔgo vɔvɔ é nɔ hɔn hwla cí é.", "h": "La Lama nyí tɔ̀ e mɛ è nɔ mɔ kɔ́ ɖè é ɖé, bɔ zunkan e mɛ è ma nɔ mɔ ama akpáxwé ɖé ɖè ǎ é ɖé ɖò tofɔligbé Bénin tɔn. Fí e è nɔ mɔ ahwanfuntɔ́ adɔgo vɔvɔ ɖè é, ahwanfuntɔ́ e è nɔ mɔ ɖò Benin kpo tò e sɛkpɔ finɛ lɛ é kpo mɛ é ɖibla nyí fí enɛ, bo nɔ lɛ́ mɔ xɛ alɔkpa gègě. È nɔ yì ba mɛ lɛ kpɔ́n kpo alixlɛ́mɛtɔ́ zunkan lɛ tɔn lɛ kpo, é na nyɔ́ hugǎn ɖɔ è ni yì ba ye kpɔ́n ɖò zǎnzǎn tɛɛn."}, "yo": {"n": "Lama classified igbo", "d": "Ọkan ninu awọn ti o kẹhin ipon igbo agbegbe ni guusu, àbo ti awọn pupa-bellied ọbọ.", "h": "La Lama jẹ ibanujẹ amọ ti aarin mojuto ṣe itọju igbo ologbele-deciduous ti o ṣọwọn ni gusu Benin. O jẹ ile fun ọbọ bellied pupa, ọbọ kan ti a rii fere nikan ni Benin ati awọn orilẹ-ede adugbo, ati ọpọlọpọ awọn eya ti awọn ẹiyẹ. Awọn abẹwo ni a ṣe pẹlu awọn itọsọna igbo, ni pataki ni kutukutu owurọ."}, "ha": {"n": "Lama classified gandun daji", "d": "Ɗaya daga cikin yankunan dazuzzuka na ƙarshe a kudu, mafaka na biri mai ja.", "h": "La Lama wani bakin ciki ne na yumbu wanda tsakiyar tsakiyarsa ya adana dajin da ba kasafai ba a kudancin Benin. Gida ne ga biri jajayen ciki, biri da aka samu kusan a kasar Benin da kasashe makwabta, da kuma nau’in tsuntsaye masu yawa. Ana yin ziyara tare da jagororin daji, zai fi dacewa da sassafe."}, "sw": {"n": "Msitu wa aina ya Lama", "d": "Moja ya maeneo ya mwisho ya misitu mnene kusini, kimbilio la tumbili mwenye tumbo nyekundu.", "h": "La Lama ni mfinyanzi wa mfinyanzi ambao kiini chake cha kati huhifadhi msitu adimu ulio na miti mirefu kusini mwa Benin. Ni nyumbani kwa tumbili mwenye tumbo nyekundu, tumbili anayepatikana karibu tu katika Benin na nchi jirani, pamoja na aina nyingi za ndege. Ziara hufanywa na viongozi wa misitu, ikiwezekana mapema asubuhi."}, "es": {"n": "Bosque clasificado Lama", "d": "Una de las últimas zonas de bosque denso del sur, refugio del mono de vientre rojo.", "h": "La Lama es una depresión arcillosa cuyo núcleo central preserva un raro bosque semicaducifolio en el sur de Benin. Es el hogar del mono de vientre rojo, un mono que se encuentra casi únicamente en Benin y los países vecinos, así como de muchas especies de aves. Las visitas se realizan con guías forestales, preferentemente a primera hora de la mañana."}, "pt": {"n": "Floresta classificada Lama", "d": "Uma das últimas áreas de floresta densa do sul, refúgio do macaco-de-barriga-vermelha.", "h": "La Lama é uma depressão argilosa cujo núcleo central preserva uma rara floresta semidecídua no sul do Benin. É o lar do macaco de barriga vermelha, um macaco encontrado quase apenas no Benin e nos países vizinhos, bem como de muitas espécies de pássaros. As visitas são feitas com guias florestais, preferencialmente no início da manhã."}, "de": {"n": "Lama klassifizierter Wald", "d": "Eines der letzten dichten Waldgebiete im Süden, Zufluchtsort des Rotbauchaffen.", "h": "La Lama ist eine lehmige Senke, deren zentraler Kern einen seltenen Halblaubwald im Süden Benins bewahrt. Hier leben der Rotbauchaffe, ein Affe, der fast nur in Benin und den Nachbarländern vorkommt, sowie viele Vogelarten. Die Besichtigung erfolgt mit Waldführern, vorzugsweise am frühen Morgen."}, "it": {"n": "Foresta classificata dai lama", "d": "Una delle ultime fitte aree forestali del sud, rifugio della scimmia dal ventre rosso.", "h": "La Lama è una depressione argillosa il cui nucleo centrale conserva una rara foresta semidecidua nel Benin meridionale. Ospita la scimmia dal ventre rosso, una scimmia che si trova quasi solo nel Benin e nei paesi vicini, oltre a molte specie di uccelli. Le visite si effettuano con guide forestali, preferibilmente la mattina presto."}, "nl": {"n": "Lama geclassificeerd bos", "d": "Een van de laatste dichte bosgebieden in het zuiden, toevluchtsoord van de roodbuikaap.", "h": "La Lama is een kleiachtige depressie waarvan de centrale kern een zeldzaam halfverliezend bos in het zuiden van Benin bewaart. Het is de thuisbasis van de roodbuikaap, een aap die vrijwel alleen in Benin en de buurlanden voorkomt, evenals van vele soorten vogels. Bezoeken worden afgelegd met bosgidsen, bij voorkeur vroeg in de ochtend."}, "ru": {"n": "Лама классифицировал лес", "d": "Один из последних густых лесных массивов на юге, убежище краснобрюхой обезьяны.", "h": "Ла-Лама — это глинистая впадина, в центре которой находится редкий полулиственный лес на юге Бенина. Здесь обитает краснобрюхая мартышка, обезьяна, встречающаяся почти только в Бенине и соседних странах, а также множество видов птиц. Посещения осуществляются с лесными гидами, желательно рано утром."}, "ar": {"n": "لاما صنفت الغابة", "d": "واحدة من آخر مناطق الغابات الكثيفة في الجنوب، وهي ملجأ للقرد ذو البطن الحمراء.", "h": "لاما عبارة عن منخفض طيني يحتفظ قلبه المركزي بغابة شبه نفضية نادرة في جنوب بنين. فهي موطن للقرد ذو البطن الحمراء، وهو قرد لا يوجد تقريباً إلا في بنين والدول المجاورة، بالإضافة إلى العديد من أنواع الطيور. تتم الزيارات مع مرشدي الغابة، ويفضل أن يكون ذلك في الصباح الباكر."}, "zh": {"n": "喇嘛分类森林", "d": "南方最后的茂密森林地区之一，红腹猴的避难所。", "h": "拉拉马是一个粘土洼地，其中心保留着贝宁南部罕见的半落叶森林。这里是红腹猴（一种几乎只在贝宁及其邻国发现的猴子）以及许多鸟类的家园。参观是在森林导游的带领下进行的，最好是在清晨。"}, "ja": {"n": "ラマ教区指定の森", "d": "南部最後の密林地帯の 1 つで、アカハラ モンキーの隠れ家です。", "h": "ラ・ラマは粘土質の窪地で、その中心部にはベナン南部の珍しい半落葉樹林が保存されています。ここには、ベナンとその近隣諸国にしかほとんど生息しないアカハラザルや、多くの種類の鳥が生息しています。訪問は森林ガイドと一緒に行われ、できれば早朝に行われます。"}}, "ganvie": {"fon": {"n": "Ganvié, toxo e ɖò tɔsisa ɔ tó é .", "d": "“Vénétie Afrique tɔn”: gletoxo ɖé blebu wɛ ɖò xɔgbigbázɔ́watɛn lɛ jí ɖò Nokoué Tɔdo ɔ tɛntin.", "h": "Tofinu lɛ wɛ ɖó Ganvié ayǐ ɖò xwè kanweko 17gɔ́ ɔ kpo 18gɔ́ ɔ kpo mɛ bo na dó hɔn nú kannumɔ gbényatɔ́ lɛ: xóxó lɛ ɖɔ ɖɔ ahwanfuntɔ́ Danxomè tɔn lɛ kún sixu fun ahwan ɖò sin jí ó. Gletoxo ɔ mɛ égbé ɔ, gbɛtɔ́ afatɔ́n mɔkpan wɛ nɔ ɖu gbɛ̀ ɖò hwevíwlíwlí mɛ, ɖò taji ɔ, ɖó acadjas (hwevínyitɛn e è sɔ́ ala lɛ dó bló lɛ é) wutu. Mǐ nɔ dó tɔjihun bo nɔ yì finɛ sín tɔjihunglintɛn Abomey-Calavi tɔn jí; axi e ɖò sìn jí é wɛ nyí nǔ taji hugǎn e è bló ɖò mɛbakpɔ́n ɔ hwenu é. Akwɛ e è xlɛ́ é wɛ nyí tɔjihun e è má é ɖé tɔn, bɔ è na ɖɔ xó d’eji."}, "yo": {"n": "Ganvié, ìlú tó wà lẹ́gbẹ̀ẹ́ adágún", "d": "\"Venice ti Afirika\": gbogbo abule kan ti o wa ni agbedemeji adagun Nokoué.", "h": "Awọn Tofinu ṣeto Ganvié ni awọn ọdun 17th ati 18th lati sa fun awọn ode-ode ẹrú: aṣa sọ pe awọn alagbara Danxomè ko le ja lori omi. Abule loni ni ọpọlọpọ awọn ẹgbẹẹgbẹrun awọn olugbe ti wọn ṣe igbe aye lati ipeja, paapaa ọpẹ si awọn acadjas (awọn papa itura ẹja ti awọn ẹka ṣe). A lọ sibẹ nipasẹ ọkọ-ọkọ lati oju-omi Abomey-Calavi; ọjà lilefoofo ni aaye pataki ti ibẹwo naa. Iye owo ti a tọka si jẹ ti ọkọ oju-omi ti o pin, lati ṣe idunadura."}, "ha": {"n": "Ganvié, birni na gefen tafkin", "d": "\"Venice na Afirka\": ƙauyen gabaɗayan kan tudu a tsakiyar tafkin Nokoué.", "h": "Tofinu ya kafa Ganvié a ƙarni na 17 da 18 don tserewa mafarautan bayi: al'adar ta ba da rahoton cewa mayaƙan Danxomè ba za su iya yin yaƙi a kan ruwa ba. Kauyen a yau yana da dubun dubatar mazaunan da ke rayuwa daga kamun kifi, musamman godiya ga acadjas ( wuraren shakatawa na kifi da aka yi da rassa). Muna zuwa can ta kwale-kwale daga kogin Abomey-Calavi; Kasuwar da ke iyo ita ce ta fi daukar hankali a ziyarar. Farashin da aka nuna shine na kwale-kwalen da aka raba, don yin shawarwari."}, "sw": {"n": "Ganvié, jiji la kando ya ziwa", "d": "\"Venice ya Afrika\": kijiji kizima kwenye nguzo katikati ya Ziwa Nokoué.", "h": "Tofinu ilianzisha Ganvié katika karne ya 17 na 18 ili kuwatoroka wawindaji watumwa: hadithi zinaripoti kwamba wapiganaji wa Danxomè hawakuweza kupigana juu ya maji. Kijiji hiki leo kina makumi kadhaa ya maelfu ya wakaazi ambao wanapata riziki kutokana na uvuvi, haswa shukrani kwa acadjas (mbuga za samaki zilizotengenezwa kwa matawi). Tunaenda huko kwa mtumbwi kutoka gati ya Abomey-Calavi; soko linaloelea ndilo jambo kuu la ziara hiyo. Bei iliyoonyeshwa ni ile ya mtumbwi wa pamoja, utakaojadiliwa."}, "es": {"n": "Ganvié, la ciudad lacustre", "d": "La “Venecia de África”: un pueblo entero sobre pilotes en medio del lago Nokoué.", "h": "Los Tofinu fundaron Ganvié en los siglos XVII y XVIII para escapar de los cazadores de esclavos: la tradición cuenta que los guerreros Danxomè no podían luchar en el agua. El pueblo cuenta hoy con varias decenas de miles de habitantes que se ganan la vida con la pesca, en particular gracias a las acadjas (parques de pesca hechos de ramas). Llegamos en canoa desde el muelle de Abomey-Calavi; El mercado flotante es lo más destacado de la visita. El precio indicado es el de una canoa compartida, a negociar."}, "pt": {"n": "Ganvié, a cidade à beira do lago", "d": "A “Veneza da África”: uma vila inteira sobre palafitas no meio do Lago Nokoué.", "h": "Os Tofinu fundaram Ganvié nos séculos XVII e XVIII para escapar dos caçadores de escravos: a tradição relata que os guerreiros Danxomè não podiam lutar na água. A aldeia conta hoje com várias dezenas de milhares de habitantes que vivem da pesca, nomeadamente graças às acadjas (parques de pesca feitos de ramos). Vamos de canoa desde o cais Abomey-Calavi; o mercado flutuante é o destaque da visita. O preço indicado é o de canoa compartilhada, a negociar."}, "de": {"n": "Ganvié, die Stadt am See", "d": "Das „Venedig Afrikas“: ein ganzes Dorf auf Stelzen mitten im Nokoué-See.", "h": "Die Tofinu gründeten Ganvié im 17. und 18. Jahrhundert, um Sklavenjägern zu entkommen: Überlieferungen zufolge konnten die Danxomè-Krieger nicht auf dem Wasser kämpfen. Das Dorf hat heute mehrere Zehntausend Einwohner, die vor allem dank der Acadjas (Fischparks aus Ästen) vom Fischfang leben. Wir fahren mit dem Kanu vom Abomey-Calavi-Pier dorthin; Der schwimmende Markt ist der Höhepunkt des Besuchs. Der angegebene Preis bezieht sich auf ein gemeinsames Kanu und muss ausgehandelt werden."}, "it": {"n": "Ganvié, la città lacustre", "d": "La “Venezia dell'Africa”: un intero villaggio su palafitte in mezzo al lago Nokoué.", "h": "I Tofinu fondarono Ganvié nei secoli XVII e XVIII per sfuggire ai cacciatori di schiavi: la tradizione narra che i guerrieri Danxomè non potevano combattere sull'acqua. Il villaggio conta oggi diverse decine di migliaia di abitanti che vivono di pesca, soprattutto grazie alle acadjas (parchi ittici fatti di rami). Ci si arriva in canoa dal molo Abomey-Calavi; il mercato galleggiante è il momento clou della visita. Il prezzo indicato è quello di una canoa condivisa, da concordare."}, "nl": {"n": "Ganvié, de stad aan het meer", "d": "Het “Venetië van Afrika”: een heel dorp op palen midden in het Nokoué-meer.", "h": "De Tofinu stichtten Ganvié in de 17e en 18e eeuw om aan slavenjagers te ontsnappen: de traditie meldt dat de Danxomè-krijgers niet op het water konden vechten. Het dorp telt vandaag enkele tienduizenden inwoners die van de visserij leven, met name dankzij de acadjas (visparken gemaakt van takken). We gaan er met de kano naartoe vanaf de Abomey-Calavi pier; de drijvende markt is het hoogtepunt van het bezoek. De aangegeven prijs is die van een gedeelde kano, waarover te onderhandelen is."}, "ru": {"n": "Ганвье, город на берегу озера", "d": "«Африканская Венеция»: целая деревня на сваях посреди озера Нокуэ.", "h": "Тофину основали Ганвье в 17-18 веках, спасаясь от охотников за рабами: традиция гласит, что воины Данксоме не могли сражаться на воде. Сегодня в деревне проживает несколько десятков тысяч жителей, которые зарабатывают на жизнь рыбной ловлей, в частности благодаря акаджам (рыбным паркам из ветвей). Отправляемся туда на каноэ от причала Абомей-Калави; плавучий рынок является изюминкой визита. Указана цена за общее каноэ, подлежит обсуждению."}, "ar": {"n": "جانفي، المدينة المطلة على البحيرة", "d": "\"فينيسيا أفريقيا\": قرية بأكملها قائمة على ركائز متينة وسط بحيرة نوكوي.", "h": "أسس قبيلة توفينو مدينة جانفي في القرنين السابع عشر والثامن عشر هربًا من صيادي العبيد: تشير التقاليد إلى أن محاربي دانكسومي لم يتمكنوا من القتال على الماء. تضم القرية اليوم عشرات الآلاف من السكان الذين يكسبون عيشهم من صيد الأسماك، ولا سيما بفضل الأكادجا (حدائق الأسماك المصنوعة من الفروع). نذهب إلى هناك بالزورق من رصيف أبومي-كالافي؛ السوق العائم هو أبرز ما في الزيارة. السعر المشار إليه هو سعر الزورق المشترك الذي سيتم التفاوض عليه."}, "zh": {"n": "甘维埃 (Ganvié)，湖滨城市", "d": "“非洲威尼斯”：位于诺库埃湖中心的整个高跷村庄。", "h": "托菲努人于 17 世纪和 18 世纪建立了甘维埃，以躲避奴隶猎人：传统报道称，丹克索梅战士无法在水上作战。如今，该村有数万名居民以捕鱼为生，这要归功于阿卡贾斯（用树枝搭建的鱼园）。我们从阿波美-卡拉维码头乘独木舟前往那里；水上市场是参观的亮点。所示价格为共用独木舟的价格，有待协商。"}, "ja": {"n": "湖畔の街、ガンヴィエ", "d": "「アフリカのベニス」: ノクエ湖の真ん中にある高床式の村全体。", "h": "トフィーヌ族は 17 世紀から 18 世紀に奴隷狩りから逃れるためにガンヴィエを設立しました。伝承によれば、ダンクソメの戦士たちは水上で戦うことができませんでした。現在、この村には数万人の住民がおり、特にアカジャ (枝で作られた魚公園) のおかげで、漁業で生計を立てています。私たちはアボメイ・カラヴィ桟橋からカヌーでそこに行きます。水上マーケットはこの訪問のハイライトです。表示価格は乗合カヌーの価格です。交渉の余地があります。"}}, "amazone": {"fon": {"n": "Amazonie sín ɖiɖe", "d": "30 m ganvɔ ɖiɖe e nɔ kpa susu nú ahwanfuntɔ́ Danxomè tɔn lɛ é.", "h": "È hun ɖiɖe ɖaxó enɛ ɖò azǎn 30gɔ́ ɔ Kɔnyásun 2022 tɔn gbè ɖò Esplanade des Amazones jí, bo kpankɔ́n nú xù ɔ, bo nɔte nú Agojié ɖé, bo nyí hagbɛ̌ sɔja nyɔnu lɛ sín gbɛ̌ta axɔsuɖuto Danxomè tɔn tɔn tɔn. Ahwanfuntɔ enɛ lɛ e Elɔpunu lɛ nɔ ylɔ ɖɔ “Amazons” lɛ ɔ, ye fun ahwan xá ahwanfuntɔ France tɔn lɛ ɖo xwe 1890 kpodo 1892 kpo mɛ."}, "yo": {"n": "Ere ere Amazon", "d": "30 m ère idẹ ti n san owo-ori fun awọn alagbara ti Danxomè.", "h": "Ti ṣe ifilọlẹ ni Oṣu Keje Ọjọ 30, Ọdun 2022 lori Esplanade des Amazones, ti nkọju si okun, ere nla yii duro fun Agojié kan, ọmọ ẹgbẹ ti ẹgbẹ awọn ọmọ ogun obinrin ti ijọba Danxomè. Awọn jagunjagun wọnyi, eyiti awọn ara ilu Yuroopu pe ni “Amazons”, ni pataki ja awọn ọmọ ogun amunisin Faranse ni ọdun 1890 ati 1892. Ere naa ti di ọkan ninu awọn aami tuntun ti Cotonou."}, "ha": {"n": "Mutum-mutumi na Amazon", "d": "Mutum-mutumin tagulla mai tsawon mita 30 yana ba da kyauta ga mayaƙan Danxomè.", "h": "An ƙaddamar da shi a ranar 30 ga Yuli, 2022 a kan Esplanade des Amazones, da ke fuskantar teku, wannan katafaren mutum-mutumi na wakiltar Agojié, memba na ƙungiyar sojojin mata na masarautar Danxomè. Wadannan mayaka, wadanda Turawa ke kira da \"Amazons\", musamman sun yi yaki da sojojin Faransa na mulkin mallaka a 1890 da 1892. Mutum-mutumi ya zama daya daga cikin sabbin alamomin Cotonou."}, "sw": {"n": "Sanamu ya Amazon", "d": "Sanamu ya shaba ya mita 30 ikitoa heshima kwa wapiganaji wa Danxomè.", "h": "Ilizinduliwa mnamo Julai 30, 2022 kwenye Esplanade des Amazones, inayoelekea bahari, sanamu hii kubwa inawakilisha Agojié, mwanachama wa maiti ya askari wa kike wa ufalme wa Danxomè. Wapiganaji hawa, ambao Wazungu waliwaita \"Amazons\", haswa walipigana na askari wa kikoloni wa Ufaransa mnamo 1890 na 1892. Sanamu hiyo imekuwa moja ya alama mpya za Cotonou."}, "es": {"n": "Estatua del Amazonas", "d": "Estatua de bronce de 30 m en homenaje a los guerreros de Danxomè.", "h": "Inaugurada el 30 de julio de 2022 en la Explanada de las Amazonas, frente al océano, esta estatua gigante representa una Agojié, miembro del cuerpo de mujeres soldado del reino de Danxomè. Estas guerreras, a las que los europeos llamaban “amazonas”, lucharon especialmente contra las tropas coloniales francesas en 1890 y 1892. La estatua se ha convertido en uno de los nuevos símbolos de Cotonú."}, "pt": {"n": "Estátua da Amazônia", "d": "Estátua de bronze de 30 m em homenagem aos guerreiros de Danxomè.", "h": "Inaugurada em 30 de julho de 2022 na Esplanade des Amazones, de frente para o oceano, esta estátua gigante representa uma Agojié, integrante do corpo de mulheres soldados do reino de Danxomè. Estes guerreiros, a quem os europeus chamavam de “Amazonas”, lutaram nomeadamente contra as tropas coloniais francesas em 1890 e 1892. A estátua tornou-se um dos novos símbolos de Cotonou."}, "de": {"n": "Amazonenstatue", "d": "30 m hohe Bronzestatue als Hommage an die Krieger von Danxomè.", "h": "Diese riesige Statue wurde am 30. Juli 2022 auf der Esplanade des Amazones mit Blick auf den Ozean eingeweiht und stellt eine Agojié dar, ein Mitglied des weiblichen Soldatenkorps des Königreichs Danxomè. Diese Krieger, die die Europäer „Amazonen“ nannten, kämpften 1890 und 1892 vor allem gegen französische Kolonialtruppen. Die Statue ist zu einem der neuen Symbole von Cotonou geworden."}, "it": {"n": "Statua dell'Amazzonia", "d": "Statua in bronzo di 30 metri che rende omaggio ai guerrieri di Danxomè.", "h": "Inaugurata il 30 luglio 2022 sull'Esplanade des Amazones, di fronte all'oceano, questa gigantesca statua rappresenta una Agojié, membro del corpo delle donne soldato del regno di Danxomè. Questi guerrieri, che gli europei chiamavano “Amazzoni”, combatterono in particolare le truppe coloniali francesi nel 1890 e nel 1892. La statua è diventata uno dei nuovi simboli di Cotonou."}, "nl": {"n": "Amazone-standbeeld", "d": "Bronzen beeld van 30 m hoog ter ere van de krijgers van Danxomè.", "h": "Dit gigantische beeld, ingehuldigd op 30 juli 2022 op de Esplanade des Amazones, met uitzicht op de oceaan, vertegenwoordigt een Agojié, een lid van het korps vrouwelijke soldaten van het koninkrijk Danxomè. Deze krijgers, die de Europeanen ‘Amazones’ noemden, vochten met name tegen Franse koloniale troepen in 1890 en 1892. Het beeld is een van de nieuwe symbolen van Cotonou geworden."}, "ru": {"n": "Статуя Амазонки", "d": "Бронзовая статуя высотой 30 м, воздающая дань уважения воинам Данксоме.", "h": "Эта гигантская статуя, открытая 30 июля 2022 года на Эспланаде Амазонок, обращенная к океану, представляет собой Агожие, члена корпуса женщин-солдат королевства Данксоме. Эти воины, которых европейцы называли «амазонками», особенно сражались с французскими колониальными войсками в 1890 и 1892 годах. Статуя стала одним из новых символов Котону."}, "ar": {"n": "تمثال الأمازون", "d": "تمثال برونزي بطول 30 مترًا تكريمًا لمحاربي دانكسومي.", "h": "تم افتتاح هذا التمثال العملاق في 30 يوليو 2022 في Esplanade des Amazones، المواجه للمحيط، وهو يمثل Agojié، وهي عضوة في فيلق المجندات في مملكة Danxomè. هؤلاء المحاربون، الذين أطلق عليهم الأوروبيون اسم \"الأمازون\"، قاتلوا بشكل خاص القوات الاستعمارية الفرنسية في عامي 1890 و1892. وأصبح التمثال أحد الرموز الجديدة لكوتونو."}, "zh": {"n": "亚马逊雕像", "d": "30 m 青铜雕像，向 Danxomè 战士致敬。", "h": "这座面向大海的巨型雕像于 2022 年 7 月 30 日在亚马逊滨海大道落成，代表的是丹克索梅王国女兵军团的成员阿戈杰 (Agojié)。这些被欧洲人称为“亚马逊人”的战士曾在 1890 年和 1892 年与法国殖民军队作战。这座雕像已成为科托努的新象征之一。"}, "ja": {"n": "アマゾンの像", "d": "ダンクソメの戦士たちに敬意を表した 30 メートルの銅像。", "h": "2022 年 7 月 30 日に海に面したアマゾネス広場に設置されたこの巨大な像は、ダンクソメ王国の女性兵士の軍団の一員であるアゴジエを表しています。ヨーロッパ人が「アマゾン」と呼んだこれらの戦士たちは、特に 1890 年と 1892 年にフランス植民地軍と戦いました。この像はコトヌーの新しいシンボルの 1 つになりました。"}}, "dantokpa": {"fon": {"n": "Axi Dantokpa tɔn", "d": "Axi ɖaxó e ɖò kɔ́xota ɖò Totaligbé Aflika tɔn lɛ é ɖokpo, ɖò tɔsisa ɔ tó.", "h": "È nɔ ylɔ́ axi ɔ́ kpowun ɖɔ “Tokpa”, é ɖiga hú hectare ko mɔ̌ ɖò tɔsisa Cotonou tɔn kpá. A sixu mɔ nǔ lɛ bǐ ɖò finɛ: avɔ e è sɔ́ célu dó bló na lɛ é, nǔhwɛ́nkún lɛ, nǔ e è nɔ zán ɖò gle mɛ ɖò tò ɔ bǐ mɛ lɛ é, nǔ e è nɔ zán dó ɖyɔ ye lɛ é, kpo axi e mɛ è nɔ sà nǔ e è nɔ zán dó bló nǔwiwa vodun tɔn lɛ ɖè é ɖé kpo bɔ è tuùn ganji. É nyí fɔngɔ́ akwɛzinzan tɔn nú Benin kpo tò e sɛkpɔ ɛ lɛ é kpo. Mi hɛn nǔ mitɔn lɛ́ɛ sɛkpɔ́ miɖée, bó wá zǎnzǎn."}, "yo": {"n": "Oja Dantokpa", "d": "Ọkan ninu awọn ọja ita gbangba ti o tobi julọ ni Iwọ-oorun Afirika, ni eti adagun naa.", "h": "Nìkan pe “Tokpa”, ọja naa gbooro to bii ogun saare lẹba adagun Cotonou. O le wa ohun gbogbo nibẹ: awọn aṣọ epo-eti, awọn turari, awọn ọja ogbin lati gbogbo orilẹ-ede, awọn ohun elo apoju, ati ọja ọjà olokiki kan nibiti a ti n ta awọn eroja fun awọn ayẹyẹ vodun. O jẹ ẹdọfóró aje fun Benin ati awọn orilẹ-ede adugbo. Jeki awọn nkan rẹ sunmọ ọ ki o wa ni owurọ."}, "ha": {"n": "Kasuwar Dantokpa", "d": "Ɗaya daga cikin manyan kasuwannin buɗaɗɗen iska a yammacin Afirka, a gefen tafkin.", "h": "Kawai ana kiransa \"Tokpa\", kasuwar ta zarce sama da kadada ashirin tare da tafkin Cotonou. Kuna iya samun komai a wurin: kayan kakin zuma, kayan yaji, kayan aikin noma daga ko'ina cikin ƙasar, kayayyakin gyara, da kuma wata shahararriyar kasuwa mai fa'ida inda ake sayar da kayan marmari na vodun. Huhu ce ta tattalin arziki ga Benin da kasashen makwabta. Ka kiyaye abubuwanka kusa da kai kuma ka zo da safe."}, "sw": {"n": "Soko la Dantokpa", "d": "Moja ya soko kubwa la wazi katika Afrika Magharibi, kwenye ukingo wa rasi.", "h": "Inaitwa tu \"Tokpa\", soko linaenea zaidi ya hekta ishirini kando ya rasi ya Cotonou. Unaweza kupata kila kitu hapo: vitambaa vya nta, viungo, bidhaa za kilimo kutoka kote nchini, vipuri, na soko maarufu la fetish ambapo viungo vya sherehe za vodun huuzwa. Ni pafu la kiuchumi kwa Benin na nchi jirani. Weka vitu vyako karibu nawe na uje asubuhi."}, "es": {"n": "Mercado Dantokpa", "d": "Uno de los mercados al aire libre más grandes de África Occidental, al borde de la laguna.", "h": "Llamado simplemente “Tokpa”, el mercado se extiende sobre una veintena de hectáreas a lo largo de la laguna de Cotonú. Allí se puede encontrar de todo: telas enceradas, especias, productos agrícolas de todo el país, repuestos y un famoso mercado fetichista donde se venden los ingredientes para las ceremonias vodun. Es un pulmón económico para Benin y los países vecinos. Mantén tus cosas cerca de ti y ven por la mañana."}, "pt": {"n": "Mercado Dantokpa", "d": "Um dos maiores mercados ao ar livre da África Ocidental, à beira da lagoa.", "h": "Chamado simplesmente de “Tokpa”, o mercado estende-se por cerca de vinte hectares ao longo da lagoa de Cotonou. Lá você encontra de tudo: tecidos de cera, temperos, produtos agrícolas de todo o país, peças de reposição e um famoso mercado fetichista onde são vendidos os ingredientes para as cerimônias do vodun. É um pulmão económico para o Benim e os países vizinhos. Mantenha suas coisas perto de você e venha pela manhã."}, "de": {"n": "Dantokpa-Markt", "d": "Einer der größten Freiluftmärkte Westafrikas, am Rande der Lagune.", "h": "Der einfach „Tokpa“ genannte Markt erstreckt sich über rund zwanzig Hektar entlang der Lagune von Cotonou. Dort finden Sie alles: Wachsstoffe, Gewürze, landwirtschaftliche Produkte aus dem ganzen Land, Ersatzteile und einen berühmten Fetischmarkt, auf dem die Zutaten für Vodun-Zeremonien verkauft werden. Es ist eine wirtschaftliche Lunge für Benin und die Nachbarländer. Behalten Sie Ihre Sachen in Ihrer Nähe und kommen Sie morgens vorbei."}, "it": {"n": "Mercato Dantokpa", "d": "Uno dei mercati all'aperto più grandi dell'Africa occidentale, ai margini della laguna.", "h": "Chiamato semplicemente “Tokpa”, il mercato si estende su una ventina di ettari lungo la laguna di Cotonou. Lì puoi trovare di tutto: tessuti di cera, spezie, prodotti agricoli provenienti da tutto il Paese, pezzi di ricambio e un famoso mercato dei feticci dove si vendono gli ingredienti per le cerimonie vodun. È un polmone economico per il Benin e i paesi vicini. Tieni le tue cose vicino a te e vieni domattina."}, "nl": {"n": "Dantokpa-markt", "d": "Een van de grootste openluchtmarkten in West-Afrika, aan de rand van de lagune.", "h": "De markt, eenvoudigweg “Tokpa” genoemd, strekt zich uit over ongeveer twintig hectare langs de Cotonou-lagune. Je vindt er alles: wasstoffen, kruiden, landbouwproducten uit het hele land, reserveonderdelen en een beroemde fetisjmarkt waar de ingrediënten voor vodun-ceremonies worden verkocht. Het is een economische long voor Benin en de buurlanden. Houd je spullen bij je en kom 's ochtends."}, "ru": {"n": "Рынок Дантокпа", "d": "Один из крупнейших рынков под открытым небом в Западной Африке, на берегу лагуны.", "h": "Рынок, называемый просто «Токпа», занимает площадь около двадцати гектаров вдоль лагуны Котону. Там можно найти все: вощеные ткани, специи, сельскохозяйственную продукцию со всей страны, запчасти и знаменитый фетиш-рынок, где продаются ингредиенты для церемоний водун. Это экономическое легкое для Бенина и соседних стран. Держи свои вещи при себе и приходи утром."}, "ar": {"n": "سوق دانتوكبا", "d": "أحد أكبر الأسواق المفتوحة في غرب أفريقيا، على حافة البحيرة.", "h": "ويسمى السوق ببساطة \"توكبا\"، ويمتد على مساحة حوالي عشرين هكتارًا على طول بحيرة كوتونو. يمكنك أن تجد كل شيء هناك: الأقمشة الشمعية، والتوابل، والمنتجات الزراعية من جميع أنحاء البلاد، وقطع الغيار، وسوق الوثن الشهير حيث يتم بيع المكونات اللازمة لاحتفالات الفودون. وهي رئة اقتصادية لبنين والدول المجاورة. أبقِ أغراضك قريبة منك وتعال في الصباح."}, "zh": {"n": "丹托克帕市场", "d": "西非最大的露天市场之一，位于泻湖边缘。", "h": "该市场简称为“Tokpa”，沿着科托努泻湖占地约二十公顷。在那里你可以找到一切：蜡织物、香料、来自全国各地的农产品、备件，还有一个著名的拜物市场，那里出售伏顿仪式的原料。它是贝宁及周边国家的经济肺。把你的东西放在身边，早上来。"}, "ja": {"n": "ダントクパ市場", "d": "ラグーンの端にある西アフリカ最大の野外市場の 1 つ。", "h": "単に「トクパ」と呼ばれるこの市場は、コトヌーのラグーン沿いに約 20 ヘクタールにわたって広がっています。そこでは、ワックス生地、スパイス、全国からの農産物、スペアパーツ、そしてヴォドゥンの儀式の材料が販売される有名なフェチ マーケットなど、あらゆるものを見つけることができます。それはベナンと近隣諸国にとって経済の肺です。荷物を近くに置いて、午前中に来てください。"}}, "cathedrale": {"fon": {"n": "Sinsɛnxɔ Notre-Dame-des-Apôtre tɔn", "d": "Cathédrale avec des rayures rouges et blanches, emblème du centre de Cotonou.", "h": "Acɛkpikpa Cotonou tɔn sín tɛnmɛ wɛ, bɔ è nɔ tuùn sinsɛnxɔ ɔ tlolo gbɔn nukɔn tɔn e ɖó ɖiɖe vɔvɔ kpo wewé kpo é gblamɛ. È gbá ɖò xwè kanweko 20gɔ́ ɔ sín akpáxwé nukɔntɔn ɔ mɛ, hwenu e Cotonou huzu tɔjihunglintɛn ɖaxó Dahomey tɔn é, bo kpó ɖò wuntun ɖé nyí wɛ ɖò Ganhi sín ayǐkúngban jí."}, "yo": {"n": "Notre-Dame-des-Apôtres Katidira", "d": "Katidira pẹlu pupa ati funfun orisirisi, emblem ti aarin ti Cotonou.", "h": "Ijoko ti Archdiocese ti Cotonou, Katidira naa jẹ idanimọ lẹsẹkẹsẹ nipasẹ facade didan pupa ati funfun. A kọ ọ ni idaji akọkọ ti ọrundun 20, nigbati Cotonou di ibudo akọkọ ti Dahomey, ati pe o jẹ ami-ilẹ ti agbegbe Ganhi."}, "ha": {"n": "Notre-Dame-des-Apôtres Cathedral", "d": "Cathedral mai ratsi ja da fari, alamar tsakiyar Cotonou.", "h": "Wurin zama na Archdiocese na Cotonou, nan da nan ana gane babban cocin ta hanyar facade na ja da fari. An gina ta ne a farkon rabin karni na 20, lokacin da Cotonou ta zama babbar tashar jiragen ruwa ta Dahomey, kuma ta kasance tambarin gundumar Ganhi."}, "sw": {"n": "Kanisa kuu la Notre-Dame-des-Apôtres", "d": "Kanisa kuu lenye mistari nyekundu na nyeupe, nembo ya kituo cha Cotonou.", "h": "Kiti cha Jimbo Kuu la Cotonou, kanisa kuu hilo linatambulika mara moja na facade yake yenye milia nyekundu na nyeupe. Ilijengwa katika nusu ya kwanza ya karne ya 20, wakati Cotonou ilipokuwa bandari kuu ya Dahomey, na inabakia kuwa alama ya wilaya ya Ganhi."}, "es": {"n": "Catedral de Notre-Dame-des-Apôtres", "d": "Catedral con franjas rojas y blancas, emblema del centro de Cotonou.", "h": "Sede de la archidiócesis de Cotonú, la catedral es inmediatamente reconocible por su fachada a rayas rojas y blancas. Fue construido en la primera mitad del siglo XX, cuando Cotonú se convirtió en el puerto principal de Dahomey, y sigue siendo un hito del distrito de Ganhi."}, "pt": {"n": "Catedral de Notre-Dame-des-Apótres", "d": "Catedral com listras vermelhas e brancas, emblema do centro de Cotonou.", "h": "Sede da Arquidiocese de Cotonou, a catedral é imediatamente reconhecível pela sua fachada listrada de vermelho e branco. Foi construído na primeira metade do século XX, quando Cotonou se tornou o principal porto do Daomé, e continua a ser um marco do distrito de Ganhi."}, "de": {"n": "Kathedrale Notre-Dame-des-Apôtres", "d": "Kathedrale mit roten und weißen Streifen, Wahrzeichen des Zentrums von Cotonou.", "h": "Die Kathedrale ist Sitz der Erzdiözese Cotonou und ist sofort an ihrer rot-weiß gestreiften Fassade zu erkennen. Es wurde in der ersten Hälfte des 20. Jahrhunderts erbaut, als Cotonou zum Haupthafen von Dahomey wurde, und ist bis heute ein Wahrzeichen des Bezirks Ganhi."}, "it": {"n": "Cattedrale di Notre-Dame-des-Apôtres", "d": "Cattedrale a strisce rosse e bianche, emblema del centro di Cotonou.", "h": "Sede dell'arcidiocesi di Cotonou, la cattedrale è immediatamente riconoscibile per la sua facciata a strisce bianche e rosse. Fu costruito nella prima metà del XX secolo, quando Cotonou divenne il porto principale del Dahomey, e rimane un punto di riferimento del distretto di Ganhi."}, "nl": {"n": "Kathedraal Notre-Dame-des-Apôtres", "d": "Kathedraal met rode en witte strepen, embleem van het centrum van Cotonou.", "h": "De kathedraal, zetel van het aartsbisdom Cotonou, is onmiddellijk herkenbaar aan de rood-wit gestreepte gevel. Het werd gebouwd in de eerste helft van de 20e eeuw, toen Cotonou de belangrijkste haven van Dahomey werd, en blijft een herkenningspunt van het Ganhi-district."}, "ru": {"n": "Собор Нотр-Дам-де-Апотр", "d": "Собор с красными и белыми полосами, эмблема центра Котону.", "h": "Собор, резиденция архиепархии Котону, сразу узнаваем по красно-белому полосатому фасаду. Он был построен в первой половине 20 века, когда Котону стал главным портом Дагомеи, и остается достопримечательностью района Гани."}, "ar": {"n": "كاتدرائية نوتردام دي أبوتريس", "d": "كاتدرائية ذات خطوط حمراء وبيضاء، شعار وسط كوتونو.", "h": "مقر أبرشية كوتونو، يمكن التعرف على الكاتدرائية على الفور من خلال واجهتها المخططة باللونين الأحمر والأبيض. تم بناؤه في النصف الأول من القرن العشرين، عندما أصبحت كوتونو الميناء الرئيسي لداهومي، ولا تزال علامة بارزة في منطقة غانهي."}, "zh": {"n": "巴黎圣母院大教堂", "d": "红白条纹大教堂，科托努市中心的象征。", "h": "这座大教堂是科托努总教区的所在地，其红白条纹的外观非常容易辨认。它建于 20 世纪上半叶，当时科托努成为达荷美的主要港口，至今仍是甘西区的地标。"}, "ja": {"n": "ノートルダム デ アポトル大聖堂", "d": "赤と白の縞模様の大聖堂、コトヌー中心部の象徴。", "h": "コトヌー大司教区の本拠地である大聖堂は、赤と白の縞模様のファサードですぐにわかります。コトヌーがダホメの主要港となった 20 世紀前半に建設され、今でもガンヒ地区のランドマークとなっています。"}}, "etoile": {"fon": {"n": "Sunví Vɔvɔ ɔ sín Kplé", "d": "Ali ɖaxó ɖaxó e è ɖu gǔ tɔn ɖò gǔfínfɔ́n hwenu é.", "h": "Nǔ énɛ́ ɔ́, è bló ɖò République Populaire du Bénin (1975-1990), hwenu e è nɔ ɖu acɛ ɖò tò ɔ mɛ é. Sunví vɔvɔ tɔn wɛ nyí wuntun tɔn. È sɔ́ ɖó vo nú ahwanfuntɔ́ ɖěɖee j’ayǐ nú tò yetɔn lɛ é sín flínflín, bo kpó ɖò toxo ɔ sín wuntun ɖaxó lɛ ɖokpo nyí wɛ, ɖò ali e jí axɔ́su ɖaxó ɖaxó gègě nɔ kpé ɖè é."}, "yo": {"n": "Red Star Square", "d": "Ikorita nla nla ti a jogun lati akoko rogbodiyan.", "h": "Ohun iranti yii wa lati Orilẹ-ede Republic of Benin (1975-1990), akoko Marxist-Leninist ti orilẹ-ede naa. Irawọ pupa rẹ jẹ aami rẹ. O ti wa ni igbẹhin si iranti ti awọn onija ti o ṣubu fun ile-ile ati pe o jẹ ọkan ninu awọn ami-ilẹ nla ti ilu, ni ikorita ti ọpọlọpọ awọn aake pataki."}, "ha": {"n": "Red Star Square", "d": "Manyan mararraba da aka gada daga lokacin juyin juya hali.", "h": "Wannan abin tunawa ya samo asali ne daga Jamhuriyar Jama'ar Benin (1975-1990), zamanin Marxist-Leninist na kasar. Jajayen tauraronsa shine alamarsa. An sadaukar da ita ne don tunawa da mayakan da suka fada wa kasarsu kuma ya kasance daya daga cikin manyan wuraren tarihi na birnin, a kan mararrabar manyan gatari da dama."}, "sw": {"n": "Red Star Square", "d": "Njia kuu kubwa za kumbukumbu zilizorithiwa kutoka wakati wa mapinduzi.", "h": "Mnara huu ulianzia Jamhuri ya Watu wa Benin (1975-1990), kipindi cha Umarxist-Leninist nchini. Nyota yake nyekundu ni ishara yake. Imejitolea kwa kumbukumbu ya wapiganaji walioanguka kwa nchi na inabaki kuwa moja ya alama kuu za jiji, kwenye njia panda za shoka kadhaa kuu."}, "es": {"n": "Plaza de la Estrella Roja", "d": "Gran cruce monumental heredero del período revolucionario.", "h": "Este monumento data de la República Popular de Benin (1975-1990), el período marxista-leninista del país. Su estrella roja es su símbolo. Está dedicado a la memoria de los luchadores que cayeron por la patria y sigue siendo uno de los grandes hitos de la ciudad, en el cruce de varios ejes importantes."}, "pt": {"n": "Praça Estrela Vermelha", "d": "Grande encruzilhada monumental herdada do período revolucionário.", "h": "Este monumento data da República Popular do Benin (1975-1990), período marxista-leninista do país. Sua estrela vermelha é seu símbolo. É dedicado à memória dos lutadores que tombaram pela pátria e continua a ser um dos grandes ex-libris da cidade, no cruzamento de vários grandes eixos."}, "de": {"n": "Platz des Roten Sterns", "d": "Große monumentale Kreuzung aus der Revolutionszeit.", "h": "Dieses Denkmal stammt aus der Volksrepublik Benin (1975-1990), der marxistisch-leninistischen Zeit des Landes. Sein roter Stern ist sein Symbol. Es ist dem Gedenken an die Kämpfer gewidmet, die sich für ihr Heimatland entschieden haben, und bleibt eines der großen Wahrzeichen der Stadt, am Schnittpunkt mehrerer wichtiger Achsen."}, "it": {"n": "Piazza della Stella Rossa", "d": "Grande crocevia monumentale ereditato dal periodo rivoluzionario.", "h": "Questo monumento risale alla Repubblica popolare del Benin (1975-1990), il periodo marxista-leninista del paese. La sua stella rossa è il suo simbolo. È dedicato alla memoria dei combattenti caduti per la patria e rimane uno dei grandi simboli della città, al crocevia di diversi assi importanti."}, "nl": {"n": "Rode Sterplein", "d": "Groot monumentaal kruispunt, geërfd uit de revolutionaire periode.", "h": "Dit monument dateert uit de Volksrepubliek Benin (1975-1990), de marxistisch-leninistische periode van het land. De rode ster is het symbool. Het is opgedragen aan de nagedachtenis van de strijders die vielen voor het vaderland en blijft een van de belangrijkste herkenningspunten van de stad, op het kruispunt van verschillende grote assen."}, "ru": {"n": "Площадь Красной Звезды", "d": "Большой монументальный перекресток, унаследованный от революционного периода.", "h": "Этот памятник датируется Народной Республикой Бенин (1975-1990 годы), марксистско-ленинским периодом страны. Его красная звезда является его символом. Он посвящен памяти борцов, павших за Родину, и остается одной из величайших достопримечательностей города, на пересечении нескольких важнейших направлений."}, "ar": {"n": "ساحة النجم الأحمر", "d": "مفترق طرق ضخم موروث من الفترة الثورية.", "h": "يعود تاريخ هذا النصب التذكاري إلى جمهورية بنين الشعبية (1975-1990)، وهي الفترة الماركسية اللينينية في البلاد. نجمها الأحمر هو رمزها. وهو مخصص لذكرى المناضلين الذين سقطوا في سبيل الوطن، ويبقى أحد معالم المدينة العظيمة، على مفترق طرق عدة محاور رئيسية."}, "zh": {"n": "红星广场", "d": "从革命时期继承下来的大型纪念性十字路口。", "h": "这座纪念碑的历史可以追溯到贝宁人民共和国（1975-1990），即该国的马克思列宁主义时期。它的红星是它的标志。它是为了纪念那些为祖国而牺牲的战士，并且仍然是这座城市的伟大地标之一，位于几个主要轴线的十字路口。"}, "ja": {"n": "レッドスタースクエア", "d": "革命時代から受け継がれた記念碑的な大きな交差点。", "h": "この記念碑は、ベニン人民共和国 (1975 ～ 1990 年) のマルクス・レーニン主義時代に建てられたものです。赤い星がシンボルです。それは祖国のために散った戦闘員の記憶に捧げられており、いくつかの主要な軸の交差点にある街の偉大なランドマークの 1 つであり続けています。"}}, "fidjrosse": {"fon": {"n": "Fidjrosse sín xùtó", "d": "Cotonou sín xùtó e mɛ gbɛtɔ́ lɛ nɔ nɔ é, bɔ maquis kpo hweyixɔ kpo ɖò Atlantique jí.", "h": "Fidjrossè wɛ nyí fí e Cotonois nɔ kplé ɖè ɖò aklunɔzán gblamɛ fifó mɛ é: mǐ nɔ ɖu hweví e è ɖa é ɖò nǔɖutɛn kpɛví kpɛví lɛ mɛ (maquis) bo nɔ ɖò hwesivɔ kpɔ́n wɛ. Mi cɔ́ miɖée, xù ɔ nɔ syɛn hwɛhwɛ ɖò Benin sín agě jí: tɔlinlin ɖò finɛ nyí awovinú, mi ba dò nú nǔ ɖò xá ɔ mɛ."}, "yo": {"n": "Fidjrosse eti okun", "d": "Awọn iwunlere eti okun ti Cotonou, pẹlu maquis ati Iwọoorun lori awọn Atlantic.", "h": "Fidjrossè jẹ ibi ipade ipari ose fun Cotonois: a jẹ ẹja braised ni awọn ile ounjẹ kekere (maquis) lakoko ti o nwo oorun ti n lọ. Ṣọra, okun nigbagbogbo ni inira ni etikun Beninese: odo nibẹ ni ewu, wa ni agbegbe."}, "ha": {"n": "Fidjrosse bakin teku", "d": "Babban bakin tekun Cotonou, tare da maquis da faɗuwar rana akan Tekun Atlantika.", "h": "Fidjrossè ita ce wurin taron karshen mako don Cotonois: muna cin kifin da aka girka a cikin ƙananan gidajen abinci (maquis) yayin kallon faɗuwar rana. Yi hankali, yawancin tekun yana da ƙarfi a bakin tekun Benin: yin iyo a can yana da haɗari, gano a cikin gida."}, "sw": {"n": "Pwani ya Fidjrosse", "d": "Pwani ya kupendeza ya Cotonou, na maquis na machweo juu ya Atlantiki.", "h": "Fidjrossè ni mahali pa kukutania wikendi kwa Cotonois: tunakula samaki waliooka katika mikahawa midogo (maquis) huku tukitazama jua likitua. Kuwa makini, bahari mara nyingi ni mbaya kwenye pwani ya Benin: kuogelea kuna hatari, tafuta ndani ya nchi."}, "es": {"n": "Playa de Fidjrosse", "d": "La animada playa de Cotonou, con maquis y puesta de sol sobre el Atlántico.", "h": "Fidjrossè es el lugar de encuentro de los cotonois los fines de semana: comemos pescado estofado en pequeños restaurantes (maquis) mientras contemplamos la puesta de sol. Tenga cuidado, el mar suele estar agitado en la costa beninesa: nadar allí es peligroso, infórmese localmente."}, "pt": {"n": "Praia de Fidjrosse", "d": "A animada praia de Cotonou, com maquis e pôr do sol sobre o Atlântico.", "h": "Fidjrossè é o ponto de encontro de fim de semana dos Cotonois: comemos peixe refogado em pequenos restaurantes (maquis) enquanto vemos o sol se pôr. Tenha cuidado, o mar costuma ser agitado na costa beninense: nadar lá é perigoso, descubra localmente."}, "de": {"n": "Fidjrosse-Strand", "d": "Der lebhafte Strand von Cotonou mit Macchia und Sonnenuntergang über dem Atlantik.", "h": "Fidjrossè ist der Wochenend-Treffpunkt der Cotonois: Wir essen geschmorten Fisch in kleinen Restaurants (Maquis) und beobachten dabei den Sonnenuntergang. Seien Sie vorsichtig, das Meer ist an der beninischen Küste oft rau: Das Schwimmen dort ist gefährlich, informieren Sie sich vor Ort."}, "it": {"n": "La spiaggia di Fidjrosse", "d": "La vivace spiaggia di Cotonou, con la macchia mediterranea e il tramonto sull'Atlantico.", "h": "Fidjrossè è il ritrovo del fine settimana per i Cotonois: mangiamo pesce brasato in piccoli ristoranti (maquis) mentre guardiamo il tramonto. Attenzione, il mare è spesso mosso sulla costa del Benin: fare il bagno è pericoloso, informatevi sul posto."}, "nl": {"n": "Fidjrosse-strand", "d": "Het levendige strand van Cotonou, met maquis en zonsondergang boven de Atlantische Oceaan.", "h": "Fidjrossè is de ontmoetingsplaats voor Cotonois in het weekend: we eten gestoofde vis in kleine restaurants (maquis) terwijl we de zon zien ondergaan. Wees voorzichtig, de zee is vaak ruw aan de Beninese kust: zwemmen daar is gevaarlijk, ontdek dit ter plaatse."}, "ru": {"n": "Пляж Фиджроссе", "d": "Оживленный пляж Котону с маквисом и закатом над Атлантикой.", "h": "Фиджроссе — это место встреч жителей Котонуа по выходным: мы едим тушеную рыбу в небольших ресторанчиках (маки), наблюдая за закатом солнца. Будьте осторожны, море на бенинском побережье часто неспокойное: купаться там опасно, узнайте на месте."}, "ar": {"n": "شاطئ فيدجروس", "d": "شاطئ كوتونو النابض بالحياة، مع مناظر غروب الشمس فوق المحيط الأطلسي.", "h": "Fidjrossè هو مكان لقاء كوتونوا في عطلة نهاية الأسبوع: فنحن نأكل السمك المطهو ​​ببطء في المطاعم الصغيرة (maquis) بينما نشاهد غروب الشمس. كن حذرًا، فالبحر غالبًا ما يكون هائجًا على ساحل بنين: السباحة هناك خطيرة، اكتشف ذلك محليًا."}, "zh": {"n": "非昭赛海滩", "d": "热闹的科托努海滩，有马基岛和大西洋上的日落。", "h": "Fidjrossè 是科托努瓦人的周末聚会场所：我们在小餐馆 (maquis) 一边吃着红烧鱼，一边看着太阳落山。请注意，贝宁海岸的海浪经常很汹涌：在那里游泳很危险，请在当地了解。"}, "ja": {"n": "フィジロッセ ビーチ", "d": "マキと大西洋に沈む夕日が見えるコトヌーの活気あるビーチ。", "h": "フィジロッセはコトノワの週末の集まりの場所です。私たちは日が沈むのを眺めながら、小さなレストラン (マキ) で魚の煮込みを食べます。ベナンの海岸では海が荒れることが多いので注意してください。そこで泳ぐのは危険なので、現地で調べてください。"}}, "artisanat": {"fon": {"n": "Centre pour la promotion des artisanats", "d": "Azɔ̌xwé alɔnuzɔ́watɔ́ lɛ tɔn kpo axixɔsa lɛ kpo: ganvɔ lɛ, nǔ e è nɔ sɔ́ dó kɔ́mɛ lɛ é, nǔ e è nɔ sɔ́ dó kɔ́mɛ lɛ é, jɛ̌ lɛ.", "h": "È bló tɛn enɛ ɔ bo na dó d’alɔ nyɔblotɔ́ tò ɔ tɔn lɛ, bɔ é nɔ kplé azɔ̌xɔsa mɔkpan bɔ mǐ nɔ mɔ ganvɔblotɔ́ lɛ, ɖiɖetɔ́ lɛ, avɔkantɔ́ lɛ kpodo avɔkanfúntɔ́ e nɔ bló nǔ e è sɔ́ dó jǐ lɛ é kpo bɔ Abomey sín ayixa nɔ w’azɔ̌ na lɛ é. Fí ɖagbe hugǎn e ɖò Cotonou bo na xɔ nǔ e è nɔ flín mɛ é tlɔlɔ ɖò mɛ e bló é gɔ́n é nɛ."}, "yo": {"n": "Center fun Igbega ti Crafts", "d": "Awọn idanileko oniṣọnà ati awọn boutiques: bronzes, ikele, awọn iboju iparada, awọn ohun ọṣọ.", "h": "Ti a ṣẹda lati ṣe atilẹyin fun awọn alamọdaju ti orilẹ-ede, ile-iṣẹ n ṣajọpọ ọpọlọpọ awọn idanileko nibiti a ti rii awọn oluṣe idẹ, awọn alarinrin, awọn alaṣọ ati awọn afọwọṣe ti awọn ikele ti a lo ni atilẹyin nipasẹ Abomey ṣiṣẹ. Eyi ni aaye ti o dara julọ ni Cotonou lati ra iranti taara lati ọdọ ẹlẹda rẹ."}, "ha": {"n": "Cibiyar inganta sana'a", "d": "Masu sana'a bita da boutiques: tagulla, rataye, masks, kayan ado.", "h": "Cibiyar da aka kirkire ta don tallafa wa masu sana’ar hannu a kasar, ta hada tarurrukan bita da dama inda muke ganin masu sana’ar tagulla, masu sassaka, masaka da masu yin kwalliyar rataye da Abomey ke aiki. Wannan shine mafi kyawun wuri a Cotonou don siyan abin tunawa kai tsaye daga mahaliccinsa."}, "sw": {"n": "Kituo cha Ukuzaji wa Ufundi", "d": "Warsha za ufundi na boutiques: bronzes, hangings, masks, kujitia.", "h": "Kituo hiki kimeundwa kusaidia mafundi nchini, kinaleta pamoja kadhaa ya warsha ambapo tunaona watengenezaji wa shaba, wachongaji, wafumaji na wadarizi wa vitambaa vya kupachikwa vilivyochochewa na Abomey wakifanya kazi. Hapa ndipo mahali pazuri zaidi Cotonou pa kununua zawadi moja kwa moja kutoka kwa mtayarishi wake."}, "es": {"n": "Centro de Promoción de la Artesanía", "d": "Talleres y boutiques artesanales: bronces, tapices, máscaras, joyería.", "h": "Creado para apoyar a los artesanos del país, el centro reúne decenas de talleres donde vemos trabajar a bronceadores, escultores, tejedores y bordadores de tapices aplicados inspirados en Abomey. Este es el mejor lugar en Cotonou para comprar un recuerdo directamente de su creador."}, "pt": {"n": "Centro de Promoção do Artesanato", "d": "Oficinas e boutiques de artesanato: bronzes, tapeçarias, máscaras, joias.", "h": "Criado para apoiar os artesãos do país, o centro reúne dezenas de oficinas onde vemos trabalhar bronzeadores, escultores, tecelões e bordadeiras de cortinas aplicadas inspiradas em Abomey. Este é o melhor lugar em Cotonou para comprar uma lembrança diretamente do seu criador."}, "de": {"n": "Zentrum zur Förderung des Handwerks", "d": "Handwerksbetriebe und Boutiquen: Bronzen, Wandbehänge, Masken, Schmuck.", "h": "Das Zentrum wurde zur Unterstützung der Kunsthandwerker des Landes gegründet und vereint Dutzende Werkstätten, in denen wir Bronzemacher, Bildhauer, Weber und Sticker bei der Arbeit beobachten können, die von Abomey inspirierte Wandbehänge herstellen. Dies ist der beste Ort in Cotonou, um ein Souvenir direkt von seinem Schöpfer zu kaufen."}, "it": {"n": "Centro per la Promozione dell'Artigianato", "d": "Laboratori e boutique artigianali: bronzi, tendaggi, maschere, gioielli.", "h": "Creato per sostenere gli artigiani del paese, il centro riunisce decine di laboratori dove vediamo bronzisti, scultori, tessitori e ricamatori di tendaggi applicati ispirati alla lavorazione di Abomey. Questo è il posto migliore a Cotonou per acquistare un souvenir direttamente dal suo creatore."}, "nl": {"n": "Centrum voor de Promotie van Ambachten", "d": "Ambachtelijke ateliers en boetieks: bronzen beelden, ophangingen, maskers, sieraden.", "h": "Het centrum is opgericht om de ambachtslieden van het land te ondersteunen en brengt tientallen werkplaatsen samen waar we bronsmakers, beeldhouwers, wevers en borduurders van toegepaste ophangingen, geïnspireerd door Abomey, aan het werk zien. Dit is de beste plek in Cotonou om een ​​souvenir rechtstreeks van de maker te kopen."}, "ru": {"n": "Центр развития ремесел", "d": "Ремесленные мастерские и бутики: изделия из бронзы, драпировки, маски, украшения.", "h": "Созданный для поддержки ремесленников страны, центр объединяет десятки мастерских, где мы видим мастеров по бронзе, скульпторов, ткачей и вышивальщиц прикладных драпировок, вдохновленных работами Абомея. Это лучшее место в Котону, где можно купить сувенир напрямую у его создателя."}, "ar": {"n": "مركز ترويج الحرف", "d": "ورش الحرفيين والمحلات: البرونزيات والمعلقات والأقنعة والمجوهرات.", "h": "تم إنشاء المركز لدعم الحرفيين في البلاد، وهو يجمع العشرات من ورش العمل حيث نرى صانعي البرونز والنحاتين والنساجين والمطرزين للتعليقات التطبيقية المستوحاة من أعمال أبومي. هذا هو أفضل مكان في كوتونو لشراء هدية تذكارية مباشرة من صانعها."}, "zh": {"n": "手工艺推广中心", "d": "工匠作坊和精品店：青铜器、挂饰、面具、珠宝。", "h": "该中心的创建是为了支持该国的工匠，汇集了数十个作坊，在那里我们可以看到青铜制造商、雕塑家、编织者和刺绣师，他们的灵感来自阿波美工作。这是科托努直接从其创造者那里购买纪念品的最佳地点。"}, "ja": {"n": "工芸振興センター", "d": "職人のワークショップとブティック: ブロンズ、壁掛け、マスク、ジュエリー。", "h": "この国の職人を支援するために設立されたこのセンターには、数十の工房が集まり、青銅器製作者、彫刻家、織り手、刺繍家たちがアボメイの仕事にインスピレーションを得た応用吊り下げ品を制作しているのを見ることができます。ここはコトヌーで作者から直接お土産を買うのに最適な場所です。"}}, "bioguera": {"fon": {"n": "Bio Guéra sín ɖiɖe", "d": "Sɔ́xátɔ́ sín ɖiɖe ahwanfuntɔ́ ɖaxó e ɖò ahwanfunfun Totaligbé tɔn mɛ é tɔn.", "h": "Baatonu axɔ́ví Bembèrèkè tɔn, Bio Guéra (1856-1916) kplá sɔ́xátɔ́ tɔn lɛ kpó ahwanfunfun e è fun xá acɛkpikpa Flansé tɔn ɖò Borgou é. E ku ɖo ahwan mɛ ɖo xwe 1916. E hun ɖiɖe tɔn ɖo Cotonou ɖo xwe 2020 lɛ sin bibɛ mɛ ɔ, e nyi ɖokpo ɖo ɖiɖe e nɔ ɖu vivɛ nu mɛ ɖaxo ɖaxo e ɖo Benin sin hwenuxo mɛ lɛ e mɛ."}, "yo": {"n": "Ere ti Bio Guéra", "d": "Equestrian ere ti akoni ti awọn Northern resistance.", "h": "Baatonu ọmọ-alade Bembèrèkè, Bio Guéra (1856-1916) mu pẹlu awọn ẹlẹṣin rẹ lati koju ija ti ijọba Faranse ni Borgou. O ku ni ija ni 1916. Ere rẹ, ti a ṣe ifilọlẹ ni Cotonou ni ibẹrẹ ọdun 2020, jẹ ọkan ninu awọn arabara ti o ṣe ayẹyẹ awọn eeyan nla ti itan-akọọlẹ Benin."}, "ha": {"n": "Mutum-mutumi na Bio Guéra", "d": "Mutum-mutumin dawaki na jarumin Arewa.", "h": "Baatonu yariman Bembèrèkè, Bio Guéra (1856-1916) ya jagoranci tare da mahayan dawakansa juriya ga mulkin mallaka na Faransa a Borgou. Ya rasu ne a wajen yaki a shekarar 1916. Mutum-mutumin da aka kaddamar a Cotonou a farkon shekarar 2020, na daya daga cikin abubuwan tarihi da ke nuna manyan tarihin kasar Benin."}, "sw": {"n": "Sanamu ya Bio Guéra", "d": "Sanamu ya Equestrian ya shujaa wa upinzani wa Kaskazini.", "h": "Baatonu mkuu wa Bembèrèkè, Bio Guéra (1856-1916) aliongoza pamoja na wapanda farasi wake upinzani dhidi ya ukoloni wa Ufaransa huko Borgou. Alikufa katika mapigano mwaka wa 1916. Sanamu yake, iliyozinduliwa huko Cotonou mapema miaka ya 2020, ni mojawapo ya makaburi ambayo huadhimisha watu wakuu wa historia ya Benin."}, "es": {"n": "Estatua de Bio Guéra", "d": "Estatua ecuestre del héroe de la resistencia del Norte.", "h": "El príncipe Baatonu de Bembèrèkè, Bio Guéra (1856-1916) dirigió con sus jinetes la resistencia contra la colonización francesa en Borgou. Murió en combate en 1916. Su estatua, inaugurada en Cotonú a principios de la década de 2020, es uno de los monumentos que celebran a las grandes figuras de la historia beninesa."}, "pt": {"n": "Estátua de Bio Guéra", "d": "Estátua equestre do herói da resistência do Norte.", "h": "Príncipe Baatonu de Bembèrèkè, Bio Guéra (1856-1916) liderou com seus cavaleiros a resistência contra a colonização francesa em Borgou. Morreu em combate em 1916. A sua estátua, inaugurada em Cotonou no início da década de 2020, é um dos monumentos que celebram as grandes figuras da história beninense."}, "de": {"n": "Statue von Bio Guéra", "d": "Reiterstatue des Helden des nördlichen Widerstands.", "h": "Baatonu-Prinz von Bembèrèkè, Bio Guéra (1856-1916), führte mit seinen Reitern den Widerstand gegen die französische Kolonisierung in Borgou an. Er starb 1916 im Kampf. Seine Statue, die Anfang der 2020er Jahre in Cotonou eingeweiht wurde, ist eines der Denkmäler, die die großen Persönlichkeiten der beninischen Geschichte ehren."}, "it": {"n": "Statua di Bio Guera", "d": "Statua equestre dell'eroe della resistenza del Nord.", "h": "Baatonu principe di Bembèrèkè, Bio Guéra (1856-1916) guidò con i suoi cavalieri la resistenza contro la colonizzazione francese a Borgou. Morì in combattimento nel 1916. La sua statua, inaugurata a Cotonou all'inizio degli anni '20, è uno dei monumenti che celebrano i grandi personaggi della storia del Benin."}, "nl": {"n": "Standbeeld van Bio Guéra", "d": "Ruiterstandbeeld van de held van het Noordelijke verzet.", "h": "Baatonu prins van Bembèrèkè, Bio Guéra (1856-1916) leidde met zijn ruiters het verzet tegen de Franse kolonisatie in Borgou. Hij sneuvelde in een gevecht in 1916. Zijn standbeeld, dat begin jaren twintig in Cotonou werd ingehuldigd, is een van de monumenten die de grote figuren uit de Beninese geschiedenis vieren."}, "ru": {"n": "Статуя Био Гера", "d": "Конная статуя героя Северного сопротивления.", "h": "Баатону, принц Бембереке, Био Гера (1856-1916) возглавил со своими всадниками сопротивление французской колонизации в Боргу. Он погиб в бою в 1916 году. Его статуя, открытая в Котону в начале 2020-х годов, является одним из памятников, прославляющих великих деятелей истории Бенина."}, "ar": {"n": "تمثال بيو جويرا", "d": "تمثال الفروسية لبطل المقاومة الشمالية.", "h": "قاد باتونو أمير بمبيريكي، بيو غيرا (1856-1916) مع فرسانه المقاومة ضد الاستعمار الفرنسي في بورغو. توفي في القتال عام 1916. ويعد تمثاله، الذي تم افتتاحه في كوتونو في أوائل عشرينيات القرن الحالي، أحد المعالم الأثرية التي تحتفي بالشخصيات العظيمة في تاريخ بنين."}, "zh": {"n": "比奥·格拉雕像", "d": "北方抵抗英雄的骑马雕像。", "h": "本贝雷克的巴托努亲王比奥·盖拉（Bio Guéra，1856-1916 年）率领他的骑兵抵抗法国在博尔古的殖民统治。他于 1916 年战死。他的雕像于 2020 年代初在科托努落成，是纪念贝宁历史上伟大人物的纪念碑之一。"}, "ja": {"n": "ビオ・ゲラの像", "d": "北部レジスタンスの英雄の騎馬像。", "h": "ベンベルレケのバートヌ王子ビオ ゲラ (1856-1916) は騎兵とともにボルグーでのフランス植民地化に対する抵抗運動を率いました。彼は 1916 年に戦闘で亡くなりました。2020 年代初頭にコトヌーに設置された彼の像は、ベナンの歴史の偉大な人物を讃える記念碑の 1 つです。"}}, "honme": {"fon": {"n": "Honmè Musée (axɔsuxɔsa)", "d": "Axɔsu Hogbonou tɔn lɛ sín hɔnmɛ xóxó ɔ, égbé ɔ, axɔsu lɛ sín xɔgbigbázɔ́watɛn wɛ.", "h": "È nɔ ylɔ Porto-Novo ɖɔ Hogbonou abǐ Adjatchè ɖò xá ɔ mɛ sín gbè mɛ. Honmè (“ɖò xwé ɔ gbè”) wɛ nyí fí e axɔsu tɔn lɛ nɔ nɔ é, kaka jɛ Toffa I jí, ee ɖu axɔsu sín 1874 jɛ 1908 bo sɔ́ axɔsuɖuto tɔn ɖó acɛkpikpa France tɔn glɔ́ é. Hɔnmɛ ɔ nɔ xlɛ́ axɔsuxɔsa lɛ, axɔsi lɛ sín xɔ lɛ, nǔ e è nɔ zán ɖò acɛkpikpa ɔ glɔ́ lɛ é kpo fí e è nɔ sɛ̀n sinsɛn ɖè ɖò axɔsuɖuto ɔ mɛ lɛ é kpo."}, "yo": {"n": "Ile ọnọ ti Honmè (aafin ọba)", "d": "Ile atijọ ti awọn ọba Hogbonou, loni ile ọnọ ti ijọba.", "h": "Porto-Novo ni a npe ni Hogbonou tabi Adjatchè ni awọn ede agbegbe. Honmè (\"ninu ile\") jẹ ibugbe ti awọn ọba rẹ, pẹlu Toffa I, ti o jọba lati 1874 si 1908 ti o si fi ijọba rẹ si abẹ aabo Faranse. Aafin naa ṣafihan awọn ile-ẹjọ ọba, awọn iyẹwu awọn ayaba, awọn ohun elo agbara ati awọn aaye ijosin ti idile ọba."}, "ha": {"n": "Gidan kayan tarihi na Honmè (fadar sarauta)", "d": "Tsohon fadar sarakunan Hogbonou, a yau gidan kayan gargajiya na sarakuna.", "h": "Porto-Novo ana kiranta Hogbonou ko Adjatchè a cikin harsunan gida. Honmè (\"a cikin gidan\") shine mazaunin sarakunanta, ciki har da Toffa I, wanda ya yi sarauta daga 1874 zuwa 1908 kuma ya sanya mulkinsa a ƙarƙashin Faransanci. Fadar ta gabatar da gidajen sarauta, gidajen sarauniya, kayan mulki da wuraren bautar daular."}, "sw": {"n": "Makumbusho ya Honmè (ikulu ya kifalme)", "d": "Ikulu ya zamani ya wafalme wa Hogbonou, leo makumbusho ya kifalme.", "h": "Porto-Novo inaitwa Hogbonou au Adjatchè katika lugha za kienyeji. Honmè (\"nyumbani\") ilikuwa makazi ya wafalme wake, ikiwa ni pamoja na Toffa I, ambaye alitawala kutoka 1874 hadi 1908 na kuweka ufalme wake chini ya ulinzi wa Kifaransa. Ikulu inatoa mahakama za kifalme, vyumba vya malkia, vitu vya mamlaka na mahali pa ibada za nasaba."}, "es": {"n": "Museo Honmè (palacio real)", "d": "El antiguo palacio de los reyes de Hogbonou, hoy museo de la realeza.", "h": "Porto-Novo se llama Hogbonou o Adjatchè en los idiomas locales. El Honmè (“en la casa”) fue la residencia de sus reyes, entre ellos Toffa I, que reinó de 1874 a 1908 y puso su reino bajo protectorado francés. El palacio presenta las cortes reales, los aposentos de las reinas, los objetos de poder y los lugares de culto de la dinastía."}, "pt": {"n": "Museu Honmè (palácio real)", "d": "O antigo palácio dos reis de Hogbonou, hoje um museu da realeza.", "h": "Porto-Novo é chamado Hogbonou ou Adjatchè nas línguas locais. O Honmè (“na casa”) foi a residência dos seus reis, incluindo Toffa I, que reinou de 1874 a 1908 e colocou o seu reino sob o protetorado francês. O palácio apresenta as cortes reais, os aposentos das rainhas, os objetos de poder e os locais de culto da dinastia."}, "de": {"n": "Honmè Museum (Königspalast)", "d": "Der ehemalige Palast der Könige von Hogbonou, heute ein königliches Museum.", "h": "Porto-Novo wird in den Landessprachen Hogbonou oder Adjatchè genannt. Das Honmè („im Haus“) war die Residenz seiner Könige, darunter Toffa I., der von 1874 bis 1908 regierte und sein Königreich unter französisches Protektorat stellte. Der Palast präsentiert die königlichen Höfe, die Gemächer der Königinnen, die Machtobjekte und die Kultstätten der Dynastie."}, "it": {"n": "Museo Honmè (palazzo reale)", "d": "L'antico palazzo dei re di Hogbonou, oggi museo della famiglia reale.", "h": "Porto-Novo si chiama Hogbonou o Adjatchè nelle lingue locali. L'Honmè (“nella casa”) fu la residenza dei suoi re, tra cui Toffa I, che regnò dal 1874 al 1908 e pose il suo regno sotto protettorato francese. Il palazzo presenta le corti reali, gli appartamenti delle regine, gli oggetti del potere e i luoghi di culto della dinastia."}, "nl": {"n": "Honmè Museum (koninklijk paleis)", "d": "Het voormalige paleis van de koningen van Hogbonou, tegenwoordig een koninklijk museum.", "h": "Porto-Novo wordt in de lokale talen Hogbonou of Adjatchè genoemd. De Honmè (“in het huis”) was de residentie van de koningen, waaronder Toffa I, die regeerde van 1874 tot 1908 en zijn koninkrijk onder Frans protectoraat plaatste. Het paleis presenteert de koninklijke hoven, de appartementen van de koninginnen, de machtsobjecten en de gebedshuizen van de dynastie."}, "ru": {"n": "Музей Хонме (королевский дворец)", "d": "Бывший дворец королей Хогбону, сегодня музей королевской семьи.", "h": "Порто-Ново на местных языках называется Хогбону или Аджаче. Хонме («в доме») был резиденцией его королей, в том числе Тоффы I, который правил с 1874 по 1908 год и передал свое королевство под протекторат Франции. Во дворце представлены королевские дворы, покои королев, объекты власти и места поклонения династии."}, "ar": {"n": "متحف هونمي (القصر الملكي)", "d": "القصر السابق لملوك هوغبونو، أصبح اليوم متحفًا ملكيًا.", "h": "يُطلق على بورتو نوفو اسم Hogbonou أو Adjatchè باللغات المحلية. كان هونمي (\"في المنزل\") مقر إقامة ملوكها، بما في ذلك توفا الأول، الذي حكم من عام 1874 إلى عام 1908 ووضع مملكته تحت الحماية الفرنسية. يعرض القصر البلاط الملكي وشقق الملكات وأشياء السلطة وأماكن العبادة الخاصة بالسلالة."}, "zh": {"n": "本目博物馆（皇宫）", "d": "霍格博努国王的前宫殿，如今是皇家博物馆。", "h": "波多诺伏在当地语言中被称为 Hogbonou 或 Adjatchè。 Honmè（“屋内”）是国王的住所，其中包括托法一世 (Toffa I)，他于 1874 年至 1908 年在位，并将其王国置于法国保护之下。宫殿是王朝的宫廷、王后的寝宫、权力的象征和礼拜场所。"}, "ja": {"n": "ホンメ美術館（王宮）", "d": "かつてはホグボヌー王の宮殿でしたが、現在は王族の博物館となっています。", "h": "ポルトノボは現地の言語でホグボヌーまたはアジャッチェと呼ばれます。オンメ (「家の」) は、1874 年から 1908 年まで統治し、王国をフランスの保護下に置いたトッファ 1 世を含む王たちの住居でした。この宮殿には、王宮、王妃の住居、権力の対象、王朝の礼拝所が展示されています。"}}, "adande": {"fon": {"n": "Alexandre Sènou Adandé Musée Ethnographique", "d": "Gèlèdè sín nukúnmɛ, nǔxixo, nǔ e è nɔ zán ɖò sinsɛnzɔ́ mɛ lɛ é sín Bɛnin tò ɔ bǐ mɛ.", "h": "È sun nyǐ nǔ e è nɔ hɛn ɖ’ayǐ lɛ é sín xɔ enɛ ɖó akɔta Benin tɔn e nyí gbexosin-alijitɔ́ ɖé é wu. É nɔ xlɛ́ nǔ e è nɔ zán ayihɔngbe ayihɔngbe lɛ é kpo nǔ mímɛ́ lɛ kpo sín kplékplé ɖaxó ɖé: Gèlèdè sín nukúnmɛ (weɖuɖu Yoruba tɔn e è sɔ́ dó UNESCO sín nǔɖokan e è ma sixu mɔ ǎ é mɛ é), hanjiji sín nǔ lɛ, nǔ e è nɔ zán dó nya gbě na lɛ é kpo nǔ e è nɔ zán dó ɖɔ nǔ dó nǔɖɔɖ’ayǐ lɛ wu lɛ é kpo. Nǔkplɔnmɛ ɖagbe ɖé dó aca tò ɔ tɔn lɛ wu."}, "yo": {"n": "Alexandre Sènou Adandé Ethnographic Museum", "d": "Awọn iboju iparada Gèlèdè, awọn ohun-elo, awọn ohun elo aṣa lati gbogbo orilẹ-ede Benin.", "h": "Ile ọnọ yii jẹ orukọ lẹhin aṣaaju-ọna ara ilu Benin kan. Ó ṣe àkójọpọ̀ ọ̀pọ̀lọpọ̀ àwọn ohun mímọ́ lójoojúmọ́: Gèlèdè masks (ijó Yorùbá tí a ṣe akojọ rẹ̀ gẹ́gẹ́ bí àjogúnbá tí a kò lè rí ti UNESCO), àwọn ohun èlò orin, ọdẹ àti àwọn ohun ìmúṣẹ. Ifihan to dara si awọn aṣa ti orilẹ-ede naa."}, "ha": {"n": "Alexandre Sènou Adande Ethnographic Museum", "d": "Gèlèdè masks, kayan kida, abubuwan al'ada daga ko'ina cikin Benin.", "h": "Sunan wannan gidan kayan tarihin ne bayan ƙwararren masanin ƙabilar Benin. Yana gabatar da tarin tarin abubuwa na yau da kullun da masu tsarki: Gèlèdè masks (Rawar Yarbawa da aka jera a matsayin abubuwan tarihi na UNESCO), kayan kida, farauta da abubuwan duba. Kyakkyawan gabatarwa ga al'adun kasar."}, "sw": {"n": "Makumbusho ya Ethnographic ya Alexandre Sènou Adande", "d": "Vinyago vya Gèlèdè, ala, vitu vya ibada kutoka kote nchini Benin.", "h": "Jumba la kumbukumbu hili limepewa jina la mtaalam wa ethnologist wa Benin. Inaonyesha mkusanyiko tajiri wa vitu vya kila siku na vitakatifu: Vinyago vya Gèlèdè (ngoma ya Kiyoruba iliyoorodheshwa kama turathi zisizoonekana za UNESCO), ala za muziki, uwindaji na vitu vya uaguzi. Utangulizi mzuri kwa tamaduni za nchi."}, "es": {"n": "Museo Etnográfico Alexandre Sènou Adandé", "d": "Máscaras, instrumentos y objetos rituales de Gèlèdè procedentes de todo Benin.", "h": "Este museo lleva el nombre de un etnólogo beninés pionero. Presenta una rica colección de objetos cotidianos y sagrados: máscaras Gèlèdè (danza yoruba catalogada como patrimonio inmaterial de la UNESCO), instrumentos musicales, objetos de caza y adivinación. Una buena introducción a las culturas del país."}, "pt": {"n": "Museu Etnográfico Alexandre Sènou Adandé", "d": "Máscaras Gèlèdè, instrumentos, objetos rituais de todo o Benin.", "h": "Este museu leva o nome de um etnólogo pioneiro do Benim. Apresenta uma rica coleção de objetos cotidianos e sagrados: máscaras Gèlèdè (dança iorubá tombada como patrimônio imaterial da UNESCO), instrumentos musicais, objetos de caça e adivinhação. Uma boa introdução às culturas do país."}, "de": {"n": "Ethnografisches Museum Alexandre Sènou Adandé", "d": "Gèlèdè-Masken, Instrumente, Ritualgegenstände aus ganz Benin.", "h": "Dieses Museum ist nach einem bahnbrechenden beninischen Ethnologen benannt. Es präsentiert eine reiche Sammlung alltäglicher und heiliger Gegenstände: Gèlèdè-Masken (Yoruba-Tanz, der zum immateriellen UNESCO-Weltkulturerbe gehört), Musikinstrumente, Jagd- und Wahrsagungsgegenstände. Eine gute Einführung in die Kulturen des Landes."}, "it": {"n": "Museo Etnografico Alexandre Sènou Adandé", "d": "Maschere Gèlèdè, strumenti, oggetti rituali provenienti da tutto il Benin.", "h": "Questo museo prende il nome da un pioniere etnologo del Benin. Presenta una ricca collezione di oggetti quotidiani e sacri: maschere Gèlèdè (danza yoruba inserita nel patrimonio immateriale dell'UNESCO), strumenti musicali, oggetti per la caccia e la divinazione. Una buona introduzione alle culture del paese."}, "nl": {"n": "Etnografisch Museum Alexandre Sènou Adandé", "d": "Gèlèdè-maskers, instrumenten, rituele voorwerpen uit heel Benin.", "h": "Dit museum is vernoemd naar een baanbrekende Beninese etnoloog. Het presenteert een rijke collectie alledaagse en heilige voorwerpen: Gèlèdè-maskers (Yoruba-dans geklasseerd als immaterieel erfgoed van UNESCO), muziekinstrumenten, jacht- en waarzeggerij-objecten. Een goede kennismaking met de culturen van het land."}, "ru": {"n": "Этнографический музей Александра Сену Аданде", "d": "Маски, инструменты, ритуальные предметы Gèlèdè со всего Бенина.", "h": "Этот музей назван в честь новаторского бенинского этнолога. Здесь представлена ​​богатая коллекция предметов быта и священных предметов: маски геледе (танец йоруба, внесенный в список нематериального наследия ЮНЕСКО), музыкальные инструменты, предметы охоты и гадания. Хорошее знакомство с культурой страны."}, "ar": {"n": "متحف ألكسندر سينو أداندي الإثنوغرافي", "d": "أقنعة Gèlèdè والأدوات وأدوات الطقوس من جميع أنحاء بنين.", "h": "تم تسمية هذا المتحف على اسم عالم الأعراق البينيني الرائد. يقدم مجموعة غنية من الأشياء اليومية والمقدسة: أقنعة Gèlèdè (رقصة اليوروبا المدرجة ضمن التراث غير المادي لليونسكو)، والآلات الموسيقية، وأدوات الصيد والعرافة. مقدمة جيدة لثقافات البلاد."}, "zh": {"n": "亚历山大·塞努·阿丹德民族志博物馆", "d": "来自贝宁各地的 Gèlèdè 面具、乐器、仪式物品。", "h": "该博物馆以一位贝宁民族学家先驱的名字命名。它展示了丰富的日常和神圣物品：Gèlèdè面具（被联合国教科文组织列为非物质遗产的约鲁巴舞蹈）、乐器、狩猎和占卜物品。对这个国家的文化有很好的介绍。"}, "ja": {"n": "アレクサンドル・セヌー・アダンデ民族学博物館", "d": "ベナン全土から集められたゲレデのマスク、楽器、儀式用の品々。", "h": "この博物館はベナンの先駆的な民族学者にちなんで名付けられました。ここには、ゲレーデの仮面 (ユネスコ無形文化遺産に登録されているヨルバ舞踊)、楽器、狩猟、占いなどの日常品や神聖な品の豊富なコレクションが展示されています。その国の文化についての良い入門書です。"}}, "mosquee": {"fon": {"n": "Mɛsɛ́dó ɖaxó Porto-Novo tɔn", "d": "Mosque Afro-Brésil tɔn e ɖó sinmɛ vovo lɛ é, ee è sɔ́ sinsɛnxɔ Bahia tɔn lɛ dó bló na é.", "h": "Nukɔn tɔn e ɖó sinmɛ ɖagbeɖagbe lɛ é nɔ flín sinsɛnxɔ Baroque tɔn e ɖò Brésil lɛ é: Afro-Brésil musulman lɛ wɛ gbá ɖò xwè kanweko 20gɔ́ ɔ sín bǐbɛ́mɛ, kannumɔ xóxó lɛ alǒ kannumɔ sín kúnkan e lɛkɔ sín Bahia lɛ é. É nyí ɖokpo ɖò kpɔ́ndéwú xɔgbigbá Afro-Brésil tɔn e jiwǔ hugǎn ɖò tɔtɛntinto Benin tɔn mɛ é mɛ."}, "yo": {"n": "Mossalassi nla ti Porto-Novo", "d": "Mossalassi ara Afro-Brazil ti o ni awọ, atilẹyin nipasẹ awọn ile ijọsin ti Bahia.", "h": "Facade ti o ni awọ ti o ni imọlẹ jẹ iranti ti awọn ile ijọsin Baroque ti Brazil: a kọ ọ ni ibẹrẹ ti 20th orundun nipasẹ Musulumi Afro-Brazilians, awọn ẹrú tẹlẹ tabi awọn ọmọ ti awọn ẹrú ti o pada lati Bahia. O jẹ ọkan ninu awọn apẹẹrẹ iyalẹnu julọ ti faaji Afro-Brazil ni Gulf of Benin."}, "ha": {"n": "Babban Masallacin Porto-Novo", "d": "Kyawawan masallacin Afro-Brazil, wanda majami'u na Bahia suka yi wahayi.", "h": "Facade mai launi mai haske yana tunawa da majami'un Baroque na Brazil: an gina shi a farkon karni na 20 da Musulmai Afro-Brazil, tsoffin bayi ko zuriyar bayi da suka dawo daga Bahia. Yana daya daga cikin misalan gine-ginen Afro-Brazil a cikin Gulf of Benin."}, "sw": {"n": "Msikiti Mkuu wa Porto-Novo", "d": "Msikiti wa rangi wa mtindo wa Kiafro-Brazili, uliochochewa na makanisa ya Bahia.", "h": "Kitambaa chake cha rangi ya kung'aa kinakumbusha makanisa ya Baroque ya Brazili: ilijengwa mwanzoni mwa karne ya 20 na Waislamu wa Afro-Brazilian, watumwa wa zamani au wazao wa watumwa waliorudi kutoka Bahia. Ni mojawapo ya mifano ya kuvutia zaidi ya usanifu wa Afro-Brazili katika Ghuba ya Benin."}, "es": {"n": "Gran Mezquita de Porto Novo", "d": "Colorida mezquita de estilo afrobrasileño, inspirada en las iglesias de Bahía.", "h": "Su fachada de vivos colores recuerda a las iglesias barrocas de Brasil: fue construida a principios del siglo XX por musulmanes afrobrasileños, antiguos esclavos o descendientes de esclavos que regresaron de Bahía. Es uno de los ejemplos más llamativos de arquitectura afrobrasileña en el Golfo de Benin."}, "pt": {"n": "Grande Mesquita de Porto-Novo", "d": "Mesquita colorida de estilo afro-brasileiro, inspirada nas igrejas da Bahia.", "h": "Sua fachada de cores vivas lembra as igrejas barrocas do Brasil: foi construída no início do século XX por afro-brasileiros muçulmanos, ex-escravos ou descendentes de escravos que retornaram da Bahia. É um dos exemplos mais marcantes da arquitetura afro-brasileira no Golfo do Benin."}, "de": {"n": "Große Moschee von Porto-Novo", "d": "Farbenfrohe Moschee im afro-brasilianischen Stil, inspiriert von den Kirchen Bahias.", "h": "Ihre farbenfrohe Fassade erinnert an die barocken Kirchen Brasiliens: Sie wurde zu Beginn des 20. Jahrhunderts von muslimischen Afro-Brasilianern, ehemaligen Sklaven oder Nachkommen von aus Bahia zurückgekehrten Sklaven, erbaut. Es ist eines der markantesten Beispiele afrobrasilianischer Architektur im Golf von Benin."}, "it": {"n": "Grande Moschea di Porto-Novo", "d": "Colorata moschea in stile afrobrasiliano, ispirata alle chiese di Bahia.", "h": "La sua facciata dai colori vivaci ricorda le chiese barocche del Brasile: fu costruita all'inizio del XX secolo da musulmani afrobrasiliani, ex schiavi o discendenti di schiavi tornati da Bahia. È uno degli esempi più sorprendenti di architettura afro-brasiliana nel Golfo del Benin."}, "nl": {"n": "Grote Moskee van Porto-Novo", "d": "Kleurrijke moskee in Afro-Braziliaanse stijl, geïnspireerd op de kerken van Bahia.", "h": "De felgekleurde gevel doet denken aan de barokke kerken van Brazilië: het werd aan het begin van de 20e eeuw gebouwd door islamitische Afro-Brazilianen, voormalige slaven of afstammelingen van slaven die terugkeerden uit Bahia. Het is een van de meest opvallende voorbeelden van Afro-Braziliaanse architectuur in de Golf van Benin."}, "ru": {"n": "Великая мечеть Порто-Ново", "d": "Красочная мечеть в афро-бразильском стиле, вдохновленная церквями Баии.", "h": "Его яркий фасад напоминает барочные церкви Бразилии: он был построен в начале 20 века мусульманами-афразильцами, бывшими рабами или потомками рабов, вернувшихся из Баии. Это один из самых ярких примеров афро-бразильской архитектуры в Бенинском заливе."}, "ar": {"n": "المسجد الكبير في بورتو نوفو", "d": "مسجد ملون على الطراز الأفريقي البرازيلي، مستوحى من كنائس باهيا.", "h": "تذكرنا واجهته ذات الألوان الزاهية بالكنائس الباروكية في البرازيل: فقد تم بناؤه في بداية القرن العشرين من قبل البرازيليين الأفارقة المسلمين، أو العبيد السابقين أو أحفاد العبيد الذين عادوا من باهيا. إنه أحد أبرز الأمثلة على العمارة الأفروبرازيلية في خليج بنين."}, "zh": {"n": "波多诺伏大清真寺", "d": "色彩缤纷的非洲裔巴西风格清真寺，灵感来自巴伊亚教堂。", "h": "其色彩鲜艳的立面让人想起巴西的巴洛克教堂​​：它是由从巴伊亚返回的前奴隶或奴隶后裔的穆斯林非裔巴西人于 20 世纪初建造的。它是贝宁湾非洲裔巴西建筑最引人注目的例子之一。"}, "ja": {"n": "ポルトノボの大モスク", "d": "バイーア州の教会からインスピレーションを得た、カラフルなアフリカ系ブラジル様式のモスク。", "h": "その明るい色のファサードはブラジルのバロック様式の教会を彷彿とさせます。この教会は 20 世紀初頭に、バイア州から帰国した元奴隷または奴隷の子孫であるイスラム教徒のアフリカ系ブラジル人によって建てられました。これは、ベニン湾におけるアフリカ系ブラジル建築の最も印象的な例の 1 つです。"}}, "jpn": {"fon": {"n": "Jikpá Atín lɛ kpo Nǔɖiɖó lɛ kpo Tɔn", "d": "Zùn mímɛ́ e ɖò toxo ɔ tɛntin é, bɔ ahwanfuntɔ́ lɛ kpo atín e nɔ na amasin lɛ é kpo ɖò finɛ.", "h": "JPN nyí zunkan mímɛ́ hwexónu tɔn ɖé bɔ è huzu jikpá ɖé, bo hɛn tɔtɛntinto e mɛ atín e nɔ nɔ fí e jǐ nɔ ja ɖè lɛ é ɖè é ɖé ɖó te ɖò toxo ɖaxó ɔ tɛntin. Ahwanfuntɔ́ mona, atín kpo atínkwín kpo e ɖó xwè kanweko lɛ é kpo tíìn bɔ è nɔ zán ɖò amasin xóxó lɛ mɛ. Fí e cí xwii bɔ è na gbɔjɛ ɖè é."}, "yo": {"n": "Ọgba ti Eweko ati Iseda", "d": "Igbo mimọ ni aarin ilu, pẹlu awọn obo ati awọn eweko oogun.", "h": "Igbo mimọ atijọ ti o yipada si ọgba kan, JPN ṣe itọju erekusu ti eweko igbona ni okan olu-ilu naa. Awọn obo monaki wa, awọn igi atijọ ati awọn eweko ti a lo ninu oogun ibile. A idakẹjẹ ibi kan Bireki."}, "ha": {"n": "Lambun Tsirrai da Yanayi", "d": "Daji mai alfarma a tsakiyar gari, tare da birai da tsire-tsire na magani.", "h": "Wani tsohon daji mai tsarki da ya koma lambu, JPN yana adana tsibiri na ciyayi masu zafi a tsakiyar babban birnin. Akwai birai da bishiyu da kuma shuke-shuke da ake amfani da su wajen maganin gargajiya. Wurin shiru don hutu."}, "sw": {"n": "Bustani ya Mimea na Asili", "d": "Msitu mtakatifu katikati ya mji, na nyani na mimea ya dawa.", "h": "Msitu mtakatifu wa kale uliogeuzwa kuwa bustani, JPN huhifadhi kisiwa cha mimea ya kitropiki katikati ya mji mkuu. Kuna nyani, miti ya karne na mimea inayotumiwa katika dawa za jadi. Mahali pa utulivu kwa mapumziko."}, "es": {"n": "Jardín de Plantas y Naturaleza", "d": "Bosque sagrado en medio del pueblo, con monos y plantas medicinales.", "h": "Antiguo bosque sagrado reconvertido en jardín, el JPN conserva una isla de vegetación tropical en el corazón de la capital. Hay monos mona, árboles centenarios y plantas utilizadas en la medicina tradicional. Un lugar tranquilo para un descanso."}, "pt": {"n": "Jardim de Plantas e Natureza", "d": "Floresta sagrada no meio da cidade, com macacos e plantas medicinais.", "h": "Antiga floresta sagrada convertida em jardim, o JPN preserva uma ilha de vegetação tropical no coração da capital. Existem macacos mona, árvores centenárias e plantas utilizadas na medicina tradicional. Um lugar tranquilo para uma pausa."}, "de": {"n": "Garten der Pflanzen und Natur", "d": "Heiliger Wald mitten in der Stadt, mit Affen und Heilpflanzen.", "h": "Das JPN ist ein alter heiliger Wald, der in einen Garten umgewandelt wurde und eine Insel tropischer Vegetation im Herzen der Hauptstadt bewahrt. Es gibt Mona-Affen, jahrhundertealte Bäume und Pflanzen, die in der traditionellen Medizin verwendet werden. Ein ruhiger Ort für eine Pause."}, "it": {"n": "Giardino delle Piante e della Natura", "d": "Foresta sacra nel centro della città, con scimmie e piante medicinali.", "h": "Antica foresta sacra trasformata in giardino, il JPN preserva un'isola di vegetazione tropicale nel cuore della capitale. Sono presenti scimmie mona, alberi secolari e piante utilizzate nella medicina tradizionale. Un posto tranquillo per una pausa."}, "nl": {"n": "Tuin van planten en natuur", "d": "Heilig bos midden in de stad, met apen en geneeskrachtige planten.", "h": "Het JPN is een eeuwenoud heilig bos dat is omgebouwd tot een tuin en bewaart een eiland met tropische vegetatie in het hart van de hoofdstad. Er zijn mona-apen, eeuwenoude bomen en planten die in de traditionele geneeskunde worden gebruikt. Een rustige plek voor een pauze."}, "ru": {"n": "Сад растений и природы", "d": "Священный лес в центре города, с обезьянами и лекарственными растениями.", "h": "Древний священный лес, превращенный в сад, JPN сохраняет остров тропической растительности в самом сердце столицы. Здесь обитают обезьяны-мона, вековые деревья и растения, используемые в традиционной медицине. Тихое место для отдыха."}, "ar": {"n": "حديقة النباتات والطبيعة", "d": "غابة مقدسة في وسط المدينة، بها القرود والنباتات الطبية.", "h": "غابة مقدسة قديمة تم تحويلها إلى حديقة، تحافظ JPN على جزيرة من النباتات الاستوائية في قلب العاصمة. هناك قرود المونى والأشجار والنباتات التي يبلغ عمرها قرنًا من الزمان والتي تستخدم في الطب التقليدي. مكان هادئ لقضاء عطلة."}, "zh": {"n": "植物与自然花园", "d": "镇中心的神圣森林，有猴子和药用植物。", "h": "JPN 将古老的神圣森林改造成花园，在首都中心保留了一座热带植被岛。这里有莫纳猴、百年古树和传统医学植物。一个安静的休息场所。"}, "ja": {"n": "植物と自然の庭園", "d": "猿と薬用植物が生息する町の真ん中にある神聖な森。", "h": "古代の神聖な森を庭園に改造した JPN は、首都の中心部に熱帯植物の島を保存しています。伝統医学で使用される樹齢数世紀の木や植物であるモナ モンキーもあります。静かな休憩場所。"}}, "dasilva": {"fon": {"n": "Silva sín nǔxɔsa", "d": "Musée privé e è sɔ́ ɖó vo nú nǔɖokan Afro-Brésil tɔn lɛ é, ɖò xwé e gbè è nɔ nɔ ɖò acɛkpikpa ɔ glɔ́ é ɖé mɛ.", "h": "Xwé ɖaxó Afro-Brésil tɔn ɖé mɛ wɛ è sɔ́ nǔ e ɖò xɔ ɔ mɛ lɛ é ɖó, bo nɔ xlɛ́ tan “Agoudas” lɛ tɔn, kannumɔ xóxó lɛ kpo ajɔ̌tɔ́ e lɛkɔ sín Brésil ɖò xwè kanweko 19gɔ́ ɔ mɛ lɛ é sín xwédo lɛ kpo tɔn. Azinkpo lɛ, fɔto lɛ, nu lɛ kpodo mɔto xoxo lɛ kpo nɔ ɖɔ nu do hlɔnhlɔn e ye ɖo do xɔgbigbá, nuɖuɖu kpodo gbɛtɔ sin gbɛta lɛ kpo ji ɖo tɔdo ɔ mɛ e wu."}, "yo": {"n": "Silva Museum", "d": "Ile ọnọ ikọkọ ti a ṣe igbẹhin si ohun-ini Afro-Brazil, ni ibugbe ileto kan.", "h": "Ti o wa ni ile nla Afro-Brazil, ile musiọmu naa tọpasẹ itan-akọọlẹ ti “Agoudas”, awọn idile ti awọn ẹrú iṣaaju ati awọn oniṣowo ti o pada lati Brazil ni ọrundun 19th. Awọn ohun-ọṣọ, awọn fọto, awọn nkan ati awọn ọkọ ayọkẹlẹ atijọ sọ nipa ipa wọn lori faaji, ounjẹ ati awujọ ti eti okun."}, "ha": {"n": "Gidan kayan tarihi na Silva", "d": "Gidan kayan tarihi mai zaman kansa wanda aka keɓe don al'adun Afro-Brazil, a cikin mazaunin mulkin mallaka.", "h": "An gina shi a cikin babban gidan Afro-Brazil, gidan kayan gargajiya ya gano tarihin \"Agoudas\", iyalan tsoffin bayi da 'yan kasuwa da suka dawo daga Brazil a karni na 19. Furnitures, hotuna, abubuwa da tsoffin motoci suna ba da labarin tasirinsu akan gine-gine, abinci da al'ummar bakin teku."}, "sw": {"n": "Makumbusho ya Silva", "d": "Makumbusho ya kibinafsi yaliyotolewa kwa urithi wa Afro-Brazilian, katika makazi ya wakoloni.", "h": "Imewekwa katika nyumba kubwa ya Afro-Brazil, jumba la makumbusho linafuatilia historia ya \"Agoudas\", familia za watumwa wa zamani na wafanyabiashara waliorudi kutoka Brazili katika karne ya 19. Samani, picha, vitu na magari ya zamani yanaelezea ushawishi wao juu ya usanifu, vyakula na jamii ya pwani."}, "es": {"n": "Museo Silva", "d": "Museo privado dedicado a la herencia afrobrasileña, en una residencia colonial.", "h": "Ubicado en una gran casa afrobrasileña, el museo recorre la historia de los \"Agoudas\", familias de antiguos esclavos y comerciantes que regresaron de Brasil en el siglo XIX. Muebles, fotografías, objetos y coches antiguos hablan de su influencia en la arquitectura, la gastronomía y la sociedad de la costa."}, "pt": {"n": "Museu Silva", "d": "Museu particular dedicado à herança afro-brasileira, em residência colonial.", "h": "Instalado em um grande casario afro-brasileiro, o museu traça a história dos “Agoudas”, famílias de ex-escravos e comerciantes que retornaram do Brasil no século XIX. Móveis, fotografias, objetos e carros antigos contam sua influência na arquitetura, na culinária e na sociedade do litoral."}, "de": {"n": "Silva-Museum", "d": "Privates Museum zum afro-brasilianischen Erbe in einer Kolonialresidenz.", "h": "Das in einem großen afro-brasilianischen Haus untergebrachte Museum zeichnet die Geschichte der „Agoudas“ nach, Familien ehemaliger Sklaven und Händler, die im 19. Jahrhundert aus Brasilien zurückkehrten. Möbel, Fotografien, Gegenstände und alte Autos erzählen von ihrem Einfluss auf die Architektur, Küche und Gesellschaft der Küste."}, "it": {"n": "Museo Silva", "d": "Museo privato dedicato al patrimonio afrobrasiliano, in una residenza coloniale.", "h": "Ospitato in una grande casa afro-brasiliana, il museo ripercorre la storia degli “Agoudas”, famiglie di ex schiavi e commercianti ritornati dal Brasile nel XIX secolo. Mobili, fotografie, oggetti e vecchie automobili raccontano la loro influenza sull'architettura, sulla cucina e sulla società della costa."}, "nl": {"n": "Silva-museum", "d": "Privémuseum gewijd aan het Afro-Braziliaanse erfgoed, in een koloniale residentie.", "h": "Het museum is gehuisvest in een groot Afro-Braziliaans huis en volgt de geschiedenis van de “Agoudas”, families van voormalige slaven en handelaars die in de 19e eeuw uit Brazilië terugkeerden. Meubels, foto's, voorwerpen en oude auto's vertellen over hun invloed op de architectuur, de keuken en de samenleving van de kust."}, "ru": {"n": "Музей Сильвы", "d": "Частный музей афро-бразильского наследия в колониальной резиденции.", "h": "Размещенный в большом афро-бразильском доме, музей прослеживает историю «Агуда», семей бывших рабов и торговцев, вернувшихся из Бразилии в 19 веке. Мебель, фотографии, предметы и старые автомобили рассказывают об их влиянии на архитектуру, кухню и общество побережья."}, "ar": {"n": "متحف سيلفا", "d": "متحف خاص مخصّص للتراث الأفريقي البرازيلي يقع في مبنى على الطراز الاستعماري", "h": "يقع المتحف في منزل كبير من أصل أفريقي برازيلي، ويتتبع تاريخ \"أجوداس\"، عائلات العبيد والتجار السابقين الذين عادوا من البرازيل في القرن التاسع عشر. يخبرنا الأثاث والصور الفوتوغرافية والأشياء والسيارات القديمة عن تأثيرها على الهندسة المعمارية والمطبخ ومجتمع الساحل."}, "zh": {"n": "席尔瓦博物馆", "d": "位于殖民地住宅内的私人博物馆，致力于展示非洲裔巴西遗产。", "h": "该博物馆坐落在一栋大型非裔巴西人房屋内，追溯了“阿古达”家族的历史，该家族由 19 世纪从巴西返回的前奴隶和商人组成。家具、照片、物品和旧汽车讲述了它们对沿海建筑、美食和社会的影响。"}, "ja": {"n": "シルバ博物館", "d": "植民地時代の邸宅内にあるアフリカ系ブラジル人の遺産を専門とする私設博物館。", "h": "アフリカ系ブラジル人の大きな家を利用したこの博物館は、19 世紀にブラジルから帰国した元奴隷や商人の家族である「アゴダ家」の歴史をたどります。家具、写真、オブジェ、古い車は、海岸の建築、料理、社会に与えた影響を物語っています。"}}, "adjarra": {"fon": {"n": "Axi Adjarra tɔn", "d": "Axi e è tuùn ɖó hǔn, zɛ̌nzɛ́n kpo alɔnuzɔ́ lɛ kpo wu é.", "h": "Adjarra ɖò dogbó Nigeria tɔn kpá, bɔ è tuùn i ɖó hǔnblotɔ́ tɔn lɛ wu. Axi e è nɔ bló sɔgbe xá sunzanwema xóxó ɔ ɖò azǎn ɛnɛ ɖokpo ɖokpo jí é nɔ dɔn xɔtɔ́ lɛ sín Benin kpo Nigeria kpo. Zɛ̌n, xasun kpo avɔ e è nɔ lɔn é kpo lɔ ɖò finɛ."}, "yo": {"n": "Ọja Adjara", "d": "Oja olokiki fun awọn ilu, apadì o ati iṣẹ ọwọ.", "h": "Nítòsí ààlà orílẹ̀-èdè Nàìjíríà, Adjarra jẹ́ olókìkí fún àwọn onílù. Ọja naa, eyiti o waye ni ibamu si kalẹnda aṣa ni gbogbo ọjọ mẹrin, ṣe ifamọra awọn olura lati Benin ati Nigeria. Nibẹ ni o wa tun apadì o, agbọn iṣẹ ati hun loincloths."}, "ha": {"n": "Kasuwar Adjara", "d": "Kasuwa ta shahara da ganguna, tukwane da sana'ar hannu.", "h": "Kusa da kan iyakar Najeriya, Adjarra ya shahara da masu yin ganga. Kasuwar wadda ake gudanar da ita bisa kalandar gargajiya duk bayan kwana hudu, tana samun masu saye daga Benin da Najeriya. Akwai kuma tukwane, kayan kwando da saƙan tsumma."}, "sw": {"n": "Soko la Adjarra", "d": "Soko maarufu kwa ngoma, ufinyanzi na kazi za mikono.", "h": "Karibu na mpaka wa Nigeria, Adjarra ni maarufu kwa watengenezaji wake wa ngoma. Soko hilo, ambalo hufanyika kulingana na kalenda ya kitamaduni kila baada ya siku nne, huvutia wanunuzi kutoka Benin na Nigeria. Pia kuna vyombo vya udongo, vikapu na vitambaa vya kusuka kiunoni."}, "es": {"n": "Mercado de Adjarra", "d": "Mercado reconocido por sus tambores, alfarería y artesanías.", "h": "Cerca de la frontera con Nigeria, Adjarra es famosa por sus fabricantes de tambores. El mercado, que se celebra según el calendario tradicional cada cuatro días, atrae a compradores de Benín y Nigeria. También hay cerámica, cestería y taparrabos tejidos."}, "pt": {"n": "Mercado Adjarra", "d": "Mercado conhecido pelos seus tambores, cerâmica e artesanato.", "h": "Perto da fronteira com a Nigéria, Adjarra é famosa pelos seus fabricantes de tambores. O mercado, que acontece de acordo com o calendário tradicional a cada quatro dias, atrai compradores do Benin e da Nigéria. Há também cerâmica, cestaria e tangas tecidas."}, "de": {"n": "Adjarra-Markt", "d": "Markt, der für seine Trommeln, Töpferwaren und Kunsthandwerk bekannt ist.", "h": "Adjarra nahe der nigerianischen Grenze ist berühmt für seine Trommelbauer. Der Markt, der nach dem traditionellen Kalender alle vier Tage stattfindet, lockt Käufer aus Benin und Nigeria an. Es gibt auch Töpferwaren, Korbwaren und gewebte Lendenschurze."}, "it": {"n": "Mercato di Agiarra", "d": "Mercato rinomato per i suoi tamburi, ceramiche e artigianato.", "h": "Vicino al confine nigeriano, Adjarra è famosa per i suoi produttori di tamburi. Il mercato, che si tiene secondo il calendario tradizionale ogni quattro giorni, attira acquirenti dal Benin e dalla Nigeria. Ci sono anche ceramiche, vimini e perizomi intrecciati."}, "nl": {"n": "Adjarra-markt", "d": "Markt bekend om zijn trommels, aardewerk en handwerk.", "h": "Dichtbij de Nigeriaanse grens staat Adjarra bekend om zijn drummakers. De markt, die volgens de traditionele kalender elke vier dagen wordt gehouden, trekt kopers uit Benin en Nigeria. Er zijn ook aardewerk, mandenwerk en geweven lendendoeken."}, "ru": {"n": "Рынок Аджарры", "d": "Рынок, известный своими барабанами, гончарными изделиями и изделиями ручной работы.", "h": "Расположенная недалеко от границы с Нигерией Аджария славится своими производителями барабанов. Рынок, который проводится по традиционному календарю каждые четыре дня, привлекает покупателей из Бенина и Нигерии. Есть также керамика, плетеные изделия и тканые набедренные повязки."}, "ar": {"n": "سوق أدجارا", "d": "سوق يشتهر بالطبول والأواني الفخارية والحرف اليدوية.", "h": "بالقرب من الحدود النيجيرية، تشتهر أدجاريا بصانعي الطبول. ويجذب السوق، الذي يقام حسب التقويم التقليدي كل أربعة أيام، المشترين من بنين ونيجيريا. هناك أيضًا أواني فخارية وسلال ومآزر منسوجة."}, "zh": {"n": "阿扎尔市场", "d": "市场以鼓、陶器和手工艺品而闻名。", "h": "阿贾拉靠近尼日利亚边境，以其鼓制造商而闻名。该市场按照传统日历每四天举行一次，吸引了来自贝宁和尼日利亚的买家。还有陶器、编织品和编织腰带。"}, "ja": {"n": "アジャラ マーケット", "d": "太鼓、陶器、手工芸品で有名な市場。", "h": "ナイジェリア国境近くのアジャラはドラムメーカーで有名です。伝統的なカレンダーに従って 4 日ごとに開催されるこの市場には、ベナンとナイジェリアからのバイヤーが集まります。陶器、かご細工、織りふんどしもあります。"}}, "ketou": {"fon": {"n": "Akaba Idɛna hɔn Kétou tɔn", "d": "Hɔntogbo e è bló syɛnsyɛn é sín axɔsuɖuto Yoruba hwexónu tɔn Kétou tɔn mɛ.", "h": "Kétou nyí ɖokpo ɖò axɔsuɖuto Yoruba tɔn xóxó lɛ mɛ, bɔ mɛ e gosin Ilé-Ifè bo wá tò ɔ mɛ lɛ é wɛ ɖó ayǐ sɔgbe xá aca. Dotɔ kpó ahohó kpó wɛ lɛ́ lɛ̌ dó toxo ɔ́; hɔntogbo Akaba Idéna tɔn e nǔmɛsɛn lɛ nɔ cyɔn alɔ jí é wɛ nyí hɔntogbo taji ɔ. Axɔsu Alakétu kpó ɖò toxo ɔ mɛ. È nɔ bló mɛbakpɔ́n ɔ kpo alixlɛ́mɛtɔ́ e nɔ ɖɔ xɛxó e cá kàn xá hɔn ɔ lɛ é kpo é."}, "yo": {"n": "Akaba Idéna Gate of Kétou", "d": "Ẹnu odi ti ijọba Yorùbá atijọ ti Kétou.", "h": "Kétou jẹ́ ọ̀kan lára ​​àwọn ìjọba ilẹ̀ Yorùbá tó ti dàgbà jù, tí àwọn aṣíkiri láti Ilé-Ifẹ̀ dá sílẹ̀. Awọn koto ati awọn odi ti yika ilu naa; ẹnu-ọ̀nà Àkábà Ìdénà tí àwọn òrìṣà dáàbò bò ni ẹnu ọ̀nà àkọ́kọ́. Oba Alakétu si n gbe ilu naa. Ibẹwo naa ṣe pẹlu itọsọna kan ti o sọ awọn arosọ ti o sopọ mọ ẹnu-ọna."}, "ha": {"n": "Akaba Idéna Ƙofar Kétou", "d": "Ƙofar kagara ta tsohuwar masarautar Yarbawa ta Kétou.", "h": "Kétou ɗaya ce daga cikin tsofaffin masarautun Yarbawa, waɗanda ƴan ƙaura daga Ifè suka kafa bisa al'ada. An kewaye birnin da ramuka da tarkace; Ƙofar Akaba Idéna, da alloli ke kiyaye shi, ita ce babbar ƙofar. Har yanzu sarki Alakétu yana zaune a garin. Ana yin ziyarar tare da jagora wanda ke ba da labarin almara da ke da alaƙa da ƙofar."}, "sw": {"n": "Akaba Idéna Lango la Kétou", "d": "Lango lenye ngome la ufalme wa kale wa Kiyoruba wa Kétou.", "h": "Kétou ni mojawapo ya falme kongwe zaidi za Kiyoruba, iliyoanzishwa kulingana na mila na wahamiaji kutoka Ilé-Ifè. Mji ulikuwa umezungukwa na mitaro na maboma; lango la Akaba Idéna, lililolindwa na miungu, lilikuwa lango kuu. Mfalme, Alakétu, bado anaishi katika jiji hilo. Ziara hiyo inafanywa na mwongozo ambaye anasimulia hadithi zilizounganishwa na mlango."}, "es": {"n": "Puerta Akaba Idéna de Kétou", "d": "Puerta fortificada del antiguo reino yoruba de Kétou.", "h": "Kétou es uno de los reinos yoruba más antiguos, fundado según la tradición por inmigrantes de Ilé-Ifè. La ciudad estaba rodeada de fosos y murallas; la puerta Akaba Idéna, protegida por divinidades, era la entrada principal. El rey Alakétu todavía reside en la ciudad. La visita se realiza con un guía que cuenta las leyendas vinculadas a la puerta."}, "pt": {"n": "Portão Akaba Idéna de Kétou", "d": "Portão fortificado do antigo reino iorubá de Kétou.", "h": "Kétou é um dos mais antigos reinos iorubás, fundado segundo a tradição por migrantes de Ilé-Ifè. A cidade era cercada por fossos e muralhas; o portão Akaba Idéna, protegido por divindades, era a entrada principal. O rei, Alakétu, ainda reside na cidade. A visita é feita com um guia que conta as lendas ligadas à porta."}, "de": {"n": "Akaba-Idéna-Tor von Kétou", "d": "Befestigtes Tor des alten Yoruba-Königreichs Kétou.", "h": "Kétou ist eines der ältesten Yoruba-Königreiche, das der Überlieferung nach von Einwanderern aus Ilé-Ifè gegründet wurde. Die Stadt war von Gräben und Stadtmauern umgeben; Das von Gottheiten beschützte Akaba-Idéna-Tor war der Haupteingang. Der König Alakétu residiert immer noch in der Stadt. Der Besuch erfolgt mit einem Führer, der die mit der Tür verbundenen Legenden erzählt."}, "it": {"n": "Porta Akaba Idéna di Kétou", "d": "Porta fortificata dell'antico regno yoruba di Kétou.", "h": "Kétou è uno dei regni yoruba più antichi, fondato secondo la tradizione da migranti provenienti da Ilé-Ifè. La città era circondata da fossati e bastioni; la porta Akaba Idéna, protetta dalle divinità, era l'ingresso principale. Il re, Alakétu, risiede ancora in città. La visita si effettua con una guida che racconta le leggende legate alla porta."}, "nl": {"n": "Akaba Idéna-poort van Kétou", "d": "Versterkte poort van het oude Yoruba-koninkrijk Kétou.", "h": "Kétou is een van de oudste Yoruba-koninkrijken, volgens de traditie gesticht door migranten uit Ilé-Ifè. De stad was omgeven door sloten en wallen; de Akaba Idéna-poort, beschermd door godheden, was de hoofdingang. De koning, Alakétu, woont nog steeds in de stad. Het bezoek wordt gedaan met een gids die de legendes vertelt die verband houden met de deur."}, "ru": {"n": "Ворота Акаба Идена в Кету", "d": "Укрепленные ворота древнего королевства йоруба Кету.", "h": "Кету — одно из старейших королевств йоруба, основанное по традиции переселенцами из Илье-Ифе. Город был окружен рвами и валами; Ворота Акаба-Идена, охраняемые божествами, были главным входом. Король Алакету до сих пор проживает в городе. Посещение совершается в сопровождении гида, который рассказывает легенды, связанные с дверью."}, "ar": {"n": "بوابة أكابا إيدينا في كيتو", "d": "البوابة المحصنة لمملكة كيتو اليوروبا القديمة.", "h": "كيتو هي واحدة من أقدم ممالك اليوروبا، تأسست وفقًا للتقاليد على يد مهاجرين من إيلي-إيفي. كانت المدينة محاطة بالخنادق والأسوار. وكانت بوابة العقبة إيدينا، المحمية بالآلهة، هي المدخل الرئيسي. ولا يزال الملك ألاكيتو يقيم في المدينة. تتم الزيارة برفقة مرشد يروي الأساطير المرتبطة بالباب."}, "zh": {"n": "Kétou 的阿卡巴伊德纳门", "d": "古代约鲁巴王国 Kétou 的坚固大门。", "h": "凯图是最古老的约鲁巴王国之一，由来自伊莱伊夫的移民按照传统建立。这座城市被沟渠和城墙包围。受到神灵保护的阿卡巴伊德纳门是主要入口。国王阿拉凯图仍然居住在这座城市。这次参观是在导游的带领下进行的，他会讲述与门相关的传说。"}, "ja": {"n": "アカバ・イデナ・ケトゥの門", "d": "古代ヨルバ王国ケトゥの要塞門。", "h": "ケトゥは、イレ・イフェからの移民によって伝統に従って設立されたヨルバ王国最古の王国の一つです。都市は溝と城壁に囲まれていました。神に守られたアカバ・イデナ門が正門であった。アラケトゥ王は今もこの街に住んでいます。訪問にはガイドが同行し、扉にまつわる伝説を語ります。"}}, "abomey": {"fon": {"n": "Axɔsuxɔsa Abomey tɔn lɛ .", "d": "Toxo ɖaxó axɔsuɖuto Danxomè tɔn tɔn, bɔ è sɔ́ UNESCO dó ɖó nǔɖokan gbɛ̀ ɔ tɔn lɛ mɛ.", "h": "Sín 1625 jɛ 1900 ɔ, axɔsu wěwe wɛ ɖyɔ yeɖée ɖò Danxomè sín axɔsuɖuto ɔ sín ta. Mɛ ɖokpó ɖokpó gbá hɔnmɛ é ɖésúnɔ tɔn ɖo hɔnmɛ e jɛ nukɔn n'i é kpá: xɔ ɔ́ bǐ bló hectare kanɖé mɔ̌. Dǒ lɛ ɖó nǔ e è sɔ́ ayikúngban e ɖó sinmɛ vovo lɛ é dó bló na lɛ é, bɔ ye ɖò nǔ e axɔsu lɛ wà lɛ é ɖɔ wɛ. Ðò 1892 ɔ, hwenu e Axɔsu Béhanzin ɖò ahwanfuntɔ́ France tɔn lɛ nukɔn é ɔ, é dó toxo ɔ zo cobo yì hwla. È sɔ́ fí enɛ dó wema mɛ bo na dó ɖó nǔɖokan gbɛ̀ ɔ tɔn lɛ ɖò 1985; Musée Historique Abomey tɔn nɔ xlɛ́ axɔsuzinkpo lɛ, recades lɛ kpo nǔ e è sɔ́ dó jǐ lɛ é kpo."}, "yo": {"n": "Awọn ile ọba ti Abomey", "d": "Olu ti ijọba Danxomè, ti a ṣe akojọ si bi aaye ohun-ini ohun-ini agbaye ti UNESCO.", "h": "Láti 1625 sí 1900, àwọn ọba méjìlá rọ́pò ara wọn ní olórí ìjọba Danxomè. Olukuluku eniyan kọ ile ti ara wọn lẹgbẹẹ ti iṣaaju wọn: gbogbo eka naa bo ni ayika ogoji saare. Odi jẹri bas-reliefs ni polychrome aiye recounts awọn exploits ti awọn ọba. Ni ọdun 1892, ti nkọju si awọn ọmọ ogun Faranse, Ọba Béhanzin ti fi iná kun ilu naa ṣaaju ki o to lọ si ibi ipamọ. Aaye naa ni a ṣe akojọ bi aaye ohun-ini agbaye ni ọdun 1985; Ile ọnọ Itan Abomey ṣafihan awọn itẹ, awọn atunkọ ati awọn ikele ti a lo."}, "ha": {"n": "Fadojin sarauta na Abomey", "d": "Babban birnin masarautar Danxomè, wanda aka jera a matsayin wurin tarihi na UNESCO.", "h": "Daga shekara ta 1625 zuwa 1900, sarakuna goma sha biyu suka gaje juna a fadar Danxomè. Kowane mutum ya gina nasa fadar kusa da na magabacinsa: gaba dayan ginin ya kai kadada arba'in. Ganuwar suna ɗauke da bas-reliefs a cikin polychrome earth suna ba da labarin abubuwan da sarakuna suka yi. A shekara ta 1892, yayin da yake fuskantar sojojin Faransa, Sarki Béhanzin ya cinnawa birnin wuta kafin ya ɓuya. An jera wurin a matsayin wurin tarihi na duniya a shekarar 1985; Gidan kayan tarihi na Abomey yana gabatar da karagai, recades da rataye da aka yi amfani da su."}, "sw": {"n": "Majumba ya kifalme ya Abomey", "d": "Mji mkuu wa ufalme wa Danxomè, ulioorodheshwa kama tovuti ya urithi wa dunia wa UNESCO.", "h": "Kuanzia 1625 hadi 1900, wafalme kumi na wawili walifuatana katika kichwa cha ufalme wa Danxomè. Kila mtu alijenga jumba lake karibu na lile la mtangulizi wao: tata nzima inashughulikia karibu hekta arobaini. Kuta hizo zina michoro ya msingi katika ardhi ya polychrome inayosimulia ushujaa wa wafalme. Mnamo 1892, akiwakabili wanajeshi wa Ufaransa, Mfalme Béhanzin alichoma moto jiji kabla ya kujificha. Tovuti hiyo iliorodheshwa kama tovuti ya urithi wa dunia mwaka 1985; Jumba la Makumbusho la Kihistoria la Abomey linatoa viti vya enzi, miongo na kuning'inia."}, "es": {"n": "Palacios reales de Abomey", "d": "Capital del reino Danxomè, declarada patrimonio de la humanidad por la UNESCO.", "h": "De 1625 a 1900, doce reyes se sucedieron al frente del reino de Danxomè. Cada uno construyó su propio palacio al lado del de su predecesor: todo el complejo ocupa unas cuarenta hectáreas. Las paredes lucen bajorrelieves en tierra policromada que relatan las hazañas de los reyes. En 1892, frente a las tropas francesas, el rey Béhanzin prendió fuego a la ciudad antes de esconderse. El sitio fue catalogado como patrimonio de la humanidad en 1985; El Museo Histórico de Abomey presenta tronos, recadas y tapices aplicados."}, "pt": {"n": "Palácios reais de Abomey", "d": "Capital do reino Danxomè, listada como património mundial da UNESCO.", "h": "De 1625 a 1900, doze reis se sucederam à frente do reino Danxomè. Cada pessoa construiu o seu próprio palácio ao lado do do seu antecessor: todo o complexo abrange cerca de quarenta hectares. As paredes apresentam baixos-relevos em terra policromada que narram as façanhas dos reis. Em 1892, enfrentando as tropas francesas, o rei Béhanzin incendiou a cidade antes de se esconder. O local foi listado como patrimônio mundial em 1985; O Museu Histórico de Abomey apresenta tronos, recadas e tapeçarias aplicadas."}, "de": {"n": "Königliche Paläste von Abomey", "d": "Hauptstadt des Danxomè-Königreichs, UNESCO-Weltkulturerbe.", "h": "Von 1625 bis 1900 folgten zwölf Könige aufeinander an der Spitze des Königreichs Danxomè. Jeder baute seinen eigenen Palast neben dem seines Vorgängers: Die gesamte Anlage umfasst rund vierzig Hektar. An den Wänden sind Flachreliefs aus polychromer Erde angebracht, die von den Taten der Könige erzählen. Im Jahr 1892 steckte König Béhanzin angesichts der französischen Truppen die Stadt in Brand, bevor er untertauchte. Die Stätte wurde 1985 zum Weltkulturerbe erklärt; Das Abomey Historical Museum präsentiert Throne, Rekaden und angewandte Behänge."}, "it": {"n": "Palazzi reali di Abomey", "d": "Capitale del regno di Danxomè, dichiarata patrimonio dell'umanità dall'UNESCO.", "h": "Dal 1625 al 1900 dodici re si succedettero alla guida del regno di Danxomè. Ciascuno costruì il proprio palazzo accanto a quello del predecessore: l'intero complesso si estende per circa quaranta ettari. Le pareti recano bassorilievi in ​​terra policroma che raccontano le imprese dei re. Nel 1892, di fronte alle truppe francesi, il re Béhanzin incendiò la città prima di nascondersi. Il sito è stato inserito nell'elenco dei siti del patrimonio mondiale nel 1985; Il Museo Storico di Abomey presenta troni, ricostruzioni e tendaggi applicati."}, "nl": {"n": "Koninklijke paleizen van Abomey", "d": "Hoofdstad van het Danxomè-koninkrijk, vermeld op de werelderfgoedlijst van UNESCO.", "h": "Van 1625 tot 1900 volgden twaalf koningen elkaar op aan het hoofd van het Danxomè-koninkrijk. Iedereen bouwde naast dat van zijn voorganger zijn eigen paleis: het hele complex beslaat zo’n veertig hectare. De muren zijn voorzien van bas-reliëfs in polychrome aarde die de heldendaden van de koningen vertellen. In 1892 stak koning Béhanzin, tegenover Franse troepen, de stad in brand voordat hij onderduikte. De site werd in 1985 op de werelderfgoedlijst geplaatst; Het Abomey Historisch Museum presenteert tronen, recades en toegepaste ophangingen."}, "ru": {"n": "Королевские дворцы Абомея", "d": "Столица королевства Данксоме, внесенная в список Всемирного наследия ЮНЕСКО.", "h": "С 1625 по 1900 год двенадцать королей сменяли друг друга во главе королевства Данксоме. Каждый человек построил свой дворец рядом со дворцом своего предшественника: весь комплекс занимает около сорока гектаров. На стенах изображены барельефы из полихромной земли, рассказывающие о подвигах королей. В 1892 году, столкнувшись с французскими войсками, король Беханзен поджег город, прежде чем скрыться. В 1985 году это место было внесено в список всемирного наследия; В Историческом музее Абомея представлены троны, рекады и прикладные драпировки."}, "ar": {"n": "القصور الملكية في أبومي", "d": "عاصمة مملكة دانكسومي، وهي مدرجة ضمن مواقع التراث العالمي لليونسكو.", "h": "من عام 1625 إلى عام 1900، خلف اثنا عشر ملكًا بعضهم البعض على رأس مملكة دانكسومي. قام كل شخص ببناء قصره الخاص بجوار قصر سلفه: يغطي المجمع بأكمله حوالي أربعين هكتارًا. تحمل الجدران نقوشًا بارزة على الأرض متعددة الألوان تحكي مآثر الملوك. في عام 1892، في مواجهة القوات الفرنسية، أشعل الملك بيهانزين النار في المدينة قبل أن يختبئ. تم إدراج الموقع كموقع للتراث العالمي في عام 1985؛ يعرض متحف أبومي التاريخي العروش والمعلقات والمعلقات المطبقة."}, "zh": {"n": "阿波美王宫", "d": "丹克索梅王国的首都，被联合国教科文组织列为世界遗产。", "h": "从 1625 年到 1900 年，十二位国王相继继承了丹克索梅王国的统治权。每个人都在前任的宫殿旁边建造了自己的宫殿：整个建筑群占地约四十公顷。墙壁上有彩土浅浮雕，讲述了国王的功绩。 1892 年，面对法国军队，贝汉津国王放火焚烧了这座城市，然后躲藏起来。该遗址于1985年被列为世界遗产；阿波美历史博物馆展示宝座、装饰物和实用的挂饰。"}, "ja": {"n": "アボメイの王宮", "d": "ダンクソメ王国の首都で、ユネスコの世界遺産に登録されています。", "h": "1625 年から 1900 年まで、12 人の王がダンクソメ王国の首長の座を次々と継承しました。各人は前任者の宮殿の隣に自分の宮殿を建てました。複合施設全体は約 40 ヘクタールに及びます。壁には、王たちの偉業を物語る多色の土の浅浮き彫りが施されています。 1892年、フランス軍と対峙したベアンザン国王は、隠れる前に街に火を放った。この場所は 1985 年に世界遺産に登録されました。アボメイ歴史博物館には、玉座、レケード、応用された壁掛けが展示されています。"}}, "behanzin": {"fon": {"n": "Axɔsu Béhanzin sín ɖiɖe (Goho sín tɛnmɛ)", "d": "Axɔsu e nɔ ɖí xwi xá nǔ é, alɔ e è sɔ́ jǐ ɖò mɛ e wá tɔ́n ahwan tò ɔ é nukɔn é.", "h": "Béhanzin, axɔsu Danxomè tɔn sín 1889 jɛ 1894 wɛ nɔ nukɔn nú ahwan e è fun xá acɛkpikpa Flansé tɔn é. È wlí i ɖò xwè 1894 mɛ, bɔ è kplá ɛ yì Martinique bɔ enɛ gudo ɔ, è kplá ɛ yì Algérie, bɔ é kú ɖò finɛ ɖò xwè 1906. Nǔɖiɖó tɔn e ɖò Place Goho jí é xlɛ́ ɛ bɔ é sɔ́ alɔ tɔn jǐ, bɔ è tinmɛ ɖɔ é gbɛ́ nǔ nú mɛ e wá tɔ́n ahwan ɛ é. È lɛkɔ hɛn cyɔ tɔn wa Abomey ɖo xwe 1928 mɛ."}, "yo": {"n": "Ere ti Ọba Béhanzin (Goho Square)", "d": "Awọn sooro ọba, ọwọ dide ni iwaju ti awọn invader.", "h": "Béhanzin, ọba Danxomè láti ọdún 1889 sí 1894, ló ṣamọ̀nà àtakò lòdì sí ìṣẹ́gun àwọn ará Faransé. Ti o gba ni 1894, o ti gbe lọ si Martinique lẹhinna si Algeria, nibiti o ti ku ni 1906. Aworan rẹ, lori Place Goho, fihan pe o gbe ọwọ rẹ soke, idari ti a tumọ bi ijusile lodi si apanirun naa. Awọn iyokù rẹ ni a mu pada si Abomey ni ọdun 1928."}, "ha": {"n": "Mutum-mutumi na King Béhanzin (Goho Square)", "d": "Sarki mai juriya, hannu ya daga gaban maharin.", "h": "Béhanzin, sarkin Danxomè daga 1889 zuwa 1894, ya jagoranci gwagwarmayar mamayar Faransawa. An kama shi a cikin 1894, an kai shi gudun hijira zuwa Martinique daga nan zuwa Algeria, inda ya mutu a 1906. Mutum-mutuminsa, a Place Goho, ya nuna shi tare da ɗaga hannunsa, alamar da aka fassara a matsayin kin amincewa da maharan. An dawo da gawarsa Abomey a cikin 1928."}, "sw": {"n": "Sanamu ya Mfalme Béhanzin (Mraba wa Goho)", "d": "Mfalme pinzani, mkono ulioinuliwa mbele ya mvamizi.", "h": "Béhanzin, mfalme wa Danxomè kuanzia 1889 hadi 1894, aliongoza upinzani dhidi ya ushindi wa wakoloni wa Ufaransa. Alitekwa mwaka wa 1894, alihamishwa hadi Martinique kisha Algeria, ambako alikufa mwaka wa 1906. Sanamu yake, kwenye Place Goho, inamwonyesha akiwa ameinua mkono wake, ishara iliyotafsiriwa kama kukataa dhidi ya mvamizi. Mabaki yake yalirudishwa Abomey mnamo 1928."}, "es": {"n": "Estatua del rey Béhanzin (Plaza Goho)", "d": "El rey resistente, con la mano levantada frente al invasor.", "h": "Béhanzin, rey de Danxomè de 1889 a 1894, encabezó la resistencia contra la conquista colonial francesa. Capturado en 1894, fue exiliado a Martinica y luego a Argelia, donde murió en 1906. Su estatua, en la plaza Goho, lo muestra con la mano levantada, gesto interpretado como un rechazo al invasor. Sus restos fueron llevados a Abomey en 1928."}, "pt": {"n": "Estátua do Rei Béhanzin (Praça Goho)", "d": "O rei resistente, mão levantada diante do invasor.", "h": "Béhanzin, rei de Danxomè de 1889 a 1894, liderou a resistência contra a conquista colonial francesa. Capturado em 1894, foi exilado para a Martinica e depois para a Argélia, onde faleceu em 1906. A sua estátua, na Praça Goho, mostra-o com a mão levantada, gesto interpretado como uma recusa ao invasor. Seus restos mortais foram trazidos de volta para Abomey em 1928."}, "de": {"n": "Statue von König Béhanzin (Goho-Platz)", "d": "Der widerständige König, die Hand vor dem Eindringling erhoben.", "h": "Béhanzin, König von Danxomè von 1889 bis 1894, führte den Widerstand gegen die französische Kolonialeroberung an. 1894 gefangen genommen, wurde er nach Martinique und dann nach Algerien verbannt, wo er 1906 starb. Seine Statue auf dem Place Goho zeigt ihn mit erhobener Hand, eine Geste, die als Ablehnung gegenüber dem Eindringling interpretiert wird. Seine sterblichen Überreste wurden 1928 nach Abomey zurückgebracht."}, "it": {"n": "Statua del re Béhanzin (Piazza Goho)", "d": "Il re resistente, con la mano alzata davanti all'invasore.", "h": "Béhanzin, re di Danxomè dal 1889 al 1894, guidò la resistenza contro la conquista coloniale francese. Catturato nel 1894, fu esiliato in Martinica poi in Algeria, dove morì nel 1906. La sua statua, in Place Goho, lo mostra con la mano alzata, gesto interpretato come un rifiuto contro l'invasore. I suoi resti furono riportati ad Abomey nel 1928."}, "nl": {"n": "Standbeeld van koning Béhanzin (Goho-plein)", "d": "De resistente koning, met de hand opgeheven voor de indringer.", "h": "Béhanzin, koning van Danxomè van 1889 tot 1894, leidde het verzet tegen de Franse koloniale verovering. Hij werd gevangengenomen in 1894 en verbannen naar Martinique en vervolgens naar Algerije, waar hij in 1906 stierf. Zijn standbeeld op Place Goho toont hem met opgeheven hand, een gebaar dat wordt geïnterpreteerd als een weigering tegen de indringer. Zijn stoffelijk overschot werd in 1928 teruggebracht naar Abomey."}, "ru": {"n": "Статуя короля Беханзина (площадь Гохо)", "d": "Стойкий король, поднявший руку перед захватчиком.", "h": "Беханзен, король Данксоме с 1889 по 1894 год, возглавлял сопротивление французскому колониальному завоеванию. Схваченный в 1894 году, он был сослан на Мартинику, а затем в Алжир, где умер в 1906 году. Его статуя на площади Гохо изображает его с поднятой рукой — жест, интерпретируемый как отказ от захватчика. Его останки были доставлены обратно в Абомей в 1928 году."}, "ar": {"n": "تمثال الملك بيهانزين (ساحة جوهو)", "d": "الملك المقاوم يرفع يده أمام الغازي.", "h": "قاد بيهانزين، ملك دانكسومي من عام 1889 إلى عام 1894، المقاومة ضد الغزو الاستعماري الفرنسي. تم القبض عليه عام 1894، وتم نفيه إلى المارتينيك ثم إلى الجزائر، حيث توفي عام 1906. ويظهره تمثاله، الموجود في ساحة جوهو، رافعا يده، في لفتة تم تفسيرها على أنها رفض للغزاة. أعيد رفاته إلى أبومي في عام 1928."}, "zh": {"n": "贝汉赞国王雕像（Goho 广场）", "d": "抵抗的国王，在入侵者面前举起手来。", "h": "贝汉津 (Béhanzin)，1889 年至 1894 年间担任丹克索梅国王，领导反抗法国殖民征服。他于 1894 年被捕，随后被流放到马提尼克岛，然后流放到阿尔及利亚，并于 1906 年在那里去世。他在戈霍广场 (Place Goho) 的雕像上，他举起了手，这一姿势被解读为拒绝入侵者。 1928年，他的遗体被运回阿波美。"}, "ja": {"n": "ベアンジン王像（ゴホ広場）", "d": "抵抗する王が侵略者の前に手を挙げた。", "h": "1889 年から 1894 年までダンクソメ王だったベアンザンは、フランスの植民地征服に対する抵抗運動を率いました。 1894年に捕らえられ、マルティニークに追放され、その後アルジェリアに追放され、1906年に死去した。ゴホ広場にある彼の像には、手を上げた彼の像があり、その動作は侵略者に対する拒否と解釈されている。彼の遺骨は1928年にアボメイに持ち帰られた。"}}, "agongointo": {"fon": {"n": "Agongointo-Zoungoudo sín xwé e ɖò ayikúngban glɔ́ lɛ é", "d": "Do e è kun ɖò ayikúngban glɔ́ lɛ é sín hǔn ɖé, bɔ è mɔ ɖò nǔjlɛdonǔwu mɛ.", "h": "Ðò 1998 ɔ, azɔ̌ e è wà ɖò ali jí lɛ é xlɛ́ ɖɔ dotɔ mɔkpan ɖò ayikúngban glɔ́ ɖò Bohicon kpá. Enyi è kun ye dó laterite mɛ ɔ, ye na ko nyí bibɛtɛn kpo nǔ e è na bɛ́ lɛ é kpo, vlafo ɖò ahwan e è fun ɖò Danxomè hwenu lɛ é hwenu. A sixu jɛte yì ye mɛ ɖokpo jí bɔ è sɔnǔ na nú mɛbakpɔ́n ɔ."}, "yo": {"n": "Awọn ibugbe ipamo ti Agongointo-Zoungoudo", "d": "Nẹtiwọọki ti awọn cavities ti a wa labẹ ilẹ, ti a rii nipasẹ aye.", "h": "Ni ọdun 1998, awọn iṣẹ opopona ṣafihan ọpọlọpọ awọn iho ipamo mejila mejila nitosi Bohicon. Wọ́n ti gbẹ́ sóde lẹ́yìn-ọ̀-rẹyìn, wọn ì bá ti ṣiṣẹ́ sìn gẹ́gẹ́ bí ibi ìsádi àti ibi ìpamọ́, bóyá nígbà àwọn ogun ìgbà Danxomè. O le sọkalẹ lọ si ọkan ninu wọn ti a ṣeto fun ibewo naa."}, "ha": {"n": "Gidajen karkashin kasa na Agongointo-Zoungoudo", "d": "Cibiyar sadarwa ta cavities da aka haƙa a ƙarƙashin ƙasa, an gano ta kwatsam.", "h": "A cikin 1998, ayyukan hanya sun bayyana kogon ƙasa dozin da yawa kusa da Bohicon. Da aka haƙa daga baya, da sun zama mafaka da wuraren ajiya, wataƙila a lokacin yaƙe-yaƙe na zamanin Danxo. Kuna iya zuwa ɗaya daga cikinsu da aka saita don ziyarar."}, "sw": {"n": "Makao ya chini ya ardhi ya Agongointo-Zoungoudo", "d": "Mtandao wa mashimo ulichimbwa chini ya ardhi, uligunduliwa kwa bahati.", "h": "Mnamo 1998, kazi za barabara zilifunua mashimo kadhaa ya chini ya ardhi karibu na Bohicon. Wakichimbwa baadaye, wangetumika kama kimbilio na mahali pa kuhifadhi, labda wakati wa vita vya enzi ya Danxomè. Unaweza kwenda chini kwa mmoja wao kuweka kwa ajili ya ziara."}, "es": {"n": "Viviendas subterráneas de Agongointo-Zoungoudo", "d": "Una red de cavidades excavadas bajo tierra, descubiertas por casualidad.", "h": "En 1998, las obras viales revelaron varias docenas de cavidades subterráneas cerca de Bohicon. Excavadas en la laterita, habrían servido de refugio y lugar de almacenamiento, quizás durante las guerras de la época Danxomè. Puedes bajar a alguno de ellos habilitados para la visita."}, "pt": {"n": "Habitações subterrâneas de Agongointo-Zoungoudo", "d": "Uma rede de cavidades escavadas no subsolo, descobertas por acaso.", "h": "Em 1998, obras rodoviárias revelaram várias dezenas de cavidades subterrâneas perto de Bohicon. Escavados na laterita, teriam servido como refúgios e locais de armazenamento, talvez durante as guerras da era Danxomè. Você pode descer até um deles preparado para a visita."}, "de": {"n": "Unterirdische Behausungen von Agongointo-Zoungoudo", "d": "Ein Netzwerk von Hohlräumen, die unter der Erde gegraben und durch Zufall entdeckt wurden.", "h": "Im Jahr 1998 wurden bei Straßenarbeiten in der Nähe von Bohicon mehrere Dutzend unterirdische Hohlräume freigelegt. Sie wurden in den Laterit gegraben und dienten möglicherweise während der Kriege der Danxomè-Ära als Zufluchts- und Lagerorte. Sie können zu einem der für den Besuch eingerichteten Plätze hinuntergehen."}, "it": {"n": "Abitazioni sotterranee di Agongointo-Zoungoudo", "d": "Una rete di cavità scavate nel sottosuolo, scoperte per caso.", "h": "Nel 1998, dei lavori stradali hanno portato alla luce diverse dozzine di cavità sotterranee vicino a Bohicon. Scavati nella laterite, sarebbero serviti come rifugi e magazzini, forse durante le guerre dell'epoca Danxomè. Puoi scendere in uno di essi predisposto per la visita."}, "nl": {"n": "Ondergrondse woningen van Agongointo-Zoungoudo", "d": "Een netwerk van ondergrondse holtes die bij toeval zijn ontdekt.", "h": "In 1998 brachten wegenwerken enkele tientallen ondergrondse holtes aan het licht nabij Bohicon. Uitgegraven in de lateriet zouden ze hebben gediend als toevluchtsoorden en opslagplaatsen, misschien tijdens de oorlogen van het Danxomè-tijdperk. Je kunt naar een van hen gaan die voor het bezoek is ingericht."}, "ru": {"n": "Подземные жилища Агонгоинто-Зунгудо", "d": "Сеть полостей, вырытых под землей, обнаруженных случайно.", "h": "В 1998 году в ходе дорожных работ возле Бохикона было обнаружено несколько десятков подземных полостей. Вырытые в латерите, они служили убежищами и местами хранения, возможно, во время войн эпохи Данксоме. Вы можете спуститься к одному из них, подготовленному для посещения."}, "ar": {"n": "المساكن تحت الأرض في Agongointo-Zoungoudo", "d": "شبكة من التجاويف المحفورة تحت الأرض، تم اكتشافها بالصدفة.", "h": "وفي عام 1998، كشفت أعمال الطرق عن عشرات التجاويف تحت الأرض بالقرب من بوهيكون. وقد تم حفرها في اللاتريت، وكانت بمثابة ملاجئ وأماكن تخزين، ربما خلال حروب عصر دانكسومي. يمكنك النزول إلى إحداها المعدة للزيارة."}, "zh": {"n": "阿贡戈因托-宗古杜的地下住宅", "d": "偶然发现的地下挖掘的洞穴网络。", "h": "1998 年，道路工程在博希孔附近发现了数十个地下洞穴。挖掘到红土中后，它们可能会成为避难所和储藏室，也许是在丹克索梅时代的战争期间。您可以前往其中一间专为参观而设置的场所。"}, "ja": {"n": "アゴンゴイント・ゾウンゴウドの地下住居", "d": "偶然発見された、地下に掘られた空洞のネットワーク。", "h": "1998 年の道路工事により、ボヒコン近くの数十の地下空洞が明らかになりました。ラテライトに掘られたそれらは、おそらくダンクソメ時代の戦争中に避難所や保管場所として機能したと思われます。訪問用に設定されたそのうちの 1 つに行くことができます。"}}, "dassa": {"fon": {"n": "Dassa-Zoumè, toxo e mɛ só 41 ɖè é", "d": "Ayikúngban e jí sókanmɛ sókanmɛ sókanmɛ tɔn lɛ ɖè é kpo fí mímɛ́ Marian tɔn ɖaxó Arigbo tɔn kpo.", "h": "Dassa ɔ, sókanmɛ sókanmɛ e nyí bibɛtɛn nú mɛ e nɔ nɔ finɛ lɛ é wɛ lɛlɛ̌ dó, bɔ ye gosin Yoruba (Idaasha). Sín 1954 ɔ, sókanmɛ Marian tɔn e ɖò Arigbo é nɔ bló tomɛyiyi ɖaxó ɖé ɖò Katolika lɛ mɛ xwewu xwewu ɖò août mɛ, bɔ mɛ gègě nɔ kplé ɖò tò ɔ bǐ mɛ kpo tò ɖevo lɛ mɛ kpo. Toxo ɔ mɛ wɛ Axɔsu Dassa tɔn sín hɔnmɛ kpo fí mímɛ́ gègě kpo ɖè ɖò sókan mɛ."}, "yo": {"n": "Dassa-Zoumè, ilu ti 41 òke", "d": "Ilẹ-ilẹ ti awọn oke granite ati ibi mimọ Marian nla ti Arigbo.", "h": "Dassa wa ni ayika awọn oke granite ti o jẹ ibi aabo fun awọn olugbe rẹ, ti ipilẹṣẹ Yoruba (Idaasha). Lati ọdun 1954, Marian grotto ti Arigbo ti gbalejo irin-ajo mimọ pataki kan ti Katoliki ni gbogbo ọdun ni Oṣu Kẹjọ, eyiti o mu awọn eniyan papọ lati gbogbo orilẹ-ede ati ni okeere. Ilu naa tun jẹ ile si aafin Ọba Dassa ati ọpọlọpọ awọn aaye mimọ lori awọn oke."}, "ha": {"n": "Dassa-Zoumè, birni mai tsaunuka 41", "d": "Tsarin ƙasa na tuddai na granite da babban wurin Marian na Arigbo.", "h": "Dassa tana kewaye da tsaunin dutse wanda ya zama mafaka ga mazaunanta, na asalin Yarbawa (Idaasha). Tun shekarar 1954, babban dakin taro na Marian na Arigbo ya karbi bakuncin babban hajjin Katolika a kowace shekara a cikin watan Agusta, wanda ya hada da jama'a daga ko'ina cikin kasar da kuma kasashen waje. Har ila yau birnin yana da fadar Sarkin Dassa da kuma wurare masu tsarki da yawa a kan tsaunuka."}, "sw": {"n": "Dassa-Zoumè, jiji la vilima 41", "d": "Mazingira ya vilima vya granite na patakatifu pa Marian huko Arigbo.", "h": "Dassa imezungukwa na vilima vya granite ambavyo vilitumika kama kimbilio kwa wakazi wake, wenye asili ya Kiyoruba (Idaasha). Tangu 1954, ukumbi wa Marian wa Arigbo umekuwa mwenyeji wa hija kuu ya Kikatoliki kila mwaka mnamo Agosti, ambayo huleta pamoja umati wa watu kutoka kote nchini na nje ya nchi. Jiji pia ni nyumbani kwa ikulu ya Mfalme wa Dassa na maeneo mengi matakatifu kwenye vilima."}, "es": {"n": "Dassa-Zoumè, la ciudad de las 41 colinas", "d": "Paisaje de cerros graníticos y el gran santuario mariano de Arigbó.", "h": "Dassa está rodeada de colinas de granito que sirvieron de refugio a sus habitantes, de origen yoruba (Idaasha). Desde 1954, la gruta mariana de Arigbo acoge cada año en agosto una importante peregrinación católica, que reúne a multitudes de todo el país y del extranjero. La ciudad también alberga el palacio del rey de Dassa y muchos lugares sagrados en las colinas."}, "pt": {"n": "Dassa-Zoumè, a cidade das 41 colinas", "d": "Paisagem de colinas graníticas e do grande santuário mariano de Arigbo.", "h": "Dassa é cercada por colinas graníticas que serviram de refúgio aos seus habitantes, de origem iorubá (Idaasha). Desde 1954, a gruta mariana de Arigbo acolhe todos os anos em agosto uma grande peregrinação católica, que reúne multidões de todo o país e do estrangeiro. A cidade também abriga o palácio do Rei de Dassa e muitos locais sagrados nas colinas."}, "de": {"n": "Dassa-Zoumè, die Stadt der 41 Hügel", "d": "Landschaft aus Granithügeln und dem großen Marienheiligtum von Arigbo.", "h": "Dassa ist von Granithügeln umgeben, die den Bewohnern Yorubas (Idaasha) als Zufluchtsort dienten. Seit 1954 findet in der Mariengrotte von Arigbo jedes Jahr im August eine große katholische Wallfahrt statt, zu der Menschen aus dem ganzen Land und dem Ausland zusammenkommen. Die Stadt beherbergt auch den Palast des Königs von Dassa und viele heilige Stätten auf den Hügeln."}, "it": {"n": "Dassa-Zoumè, la città delle 41 colline", "d": "Paesaggio di colline granitiche e il grande santuario mariano di Arigbo.", "h": "Dassa è circondata da colline granitiche che fungevano da rifugio per i suoi abitanti, di origine yoruba (Idaasha). Dal 1954, la grotta mariana di Arigbo ospita ogni anno nel mese di agosto un grande pellegrinaggio cattolico, che riunisce folle provenienti da tutto il Paese e dall'estero. La città ospita anche il palazzo del re di Dassa e numerosi luoghi sacri sulle colline."}, "nl": {"n": "Dassa-Zoumè, de stad van 41 heuvels", "d": "Landschap van granieten heuvels en het grote Mariaheiligdom van Arigbo.", "h": "Dassa is omgeven door granieten heuvels die dienden als toevluchtsoord voor de inwoners, van Yoruba-afkomst (Idaasha). Sinds 1954 organiseert de Mariagrot van Arigbo elk jaar in augustus een grote katholieke bedevaart, die menigten uit het hele land en het buitenland samenbrengt. De stad is ook de thuisbasis van het paleis van de koning van Dassa en vele heilige plaatsen op de heuvels."}, "ru": {"n": "Дасса-Зуме, город на 41 холме", "d": "Пейзаж гранитных холмов и великого святилища Марии Аригбо.", "h": "Дасса окружена гранитными холмами, которые служили убежищем для его жителей, выходцев из племени йоруба (идааша). С 1954 года в Марианском гроте в Аригбо каждый год в августе проводится крупное католическое паломничество, которое собирает толпы людей со всей страны и из-за границы. В городе также находится дворец короля Дассы и множество священных мест на холмах."}, "ar": {"n": "داسا-زومي، مدينة الـ 41 تلة", "d": "المناظر الطبيعية لتلال الجرانيت والمعبد المريمي العظيم في أريجبو.", "h": "داسا محاطة بتلال الجرانيت التي كانت بمثابة ملجأ لسكانها من أصل يوروبا (إيداشا). منذ عام 1954، تستضيف مغارة أريغبو المريمية رحلة حج كاثوليكية كبيرة كل عام في شهر أغسطس، والتي تجمع حشودًا من جميع أنحاء البلاد وخارجها. تعد المدينة أيضًا موطنًا لقصر ملك داسا والعديد من الأماكن المقدسة على التلال."}, "zh": {"n": "达萨-祖梅 (Dassa-Zoumè)，拥有 41 座山丘的城市", "d": "花岗岩山丘和阿里博伟大的玛丽亚圣殿的景观。", "h": "达萨周围环绕着花岗岩山丘，是约鲁巴族（Idaasha）居民的避难所。自1954年以来，阿里博玛丽亚石窟每年8月都会举办大型天主教朝圣活动，云集了来自国内外各地的人群。这座城市也是达萨国王的宫殿和山上许多圣地的所在地。"}, "ja": {"n": "41 の丘がある街、ダッサ・ズメ", "d": "花崗岩の丘とアリグボの偉大なマリアの聖域の風景。", "h": "ダッサは花崗岩の丘に囲まれており、ヨルバ族（イダーシャ）の住民の避難所として機能していました。 1954 年以来、アリグボのマリアの洞窟では毎年 8 月に大規模なカトリック巡礼が開催され、国内外から多くの人々が集まります。この都市にはダッサ王の宮殿や丘の上の多くの聖地もあります。"}}, "savalou": {"fon": {"n": "Savalou, axɔsuxɔsa kpodo yam xwe kpo", "d": "Axɔsuɖuto Mahi tɔn hwexónu tɔn, ee gbakpé ɖó xwè ɖaxó e é nɔ ɖu é wu é.", "h": "Savalou wɛ nyí axɔsuɖuto Mahi tɔn ɖé sín tɛnmɛ bɔ axɔsu tɔn nɔ hɛn tɛnmɛ-nyikɔ Gbaguidi tɔn. Xwewu xwewu, ɖò Avivɔsun mɔ̌ mɛ ɔ, è nɔ ɖu nǔkún-yiya yɔyɔ̌ ɔ sín xwè: nǔwiwa lɛ, weɖuɖu lɛ kpo nǔwiwa lɛ kpo nɔ dɔn mɛ e ɖò xá ɔ mɛ lɛ é wá. È sixu yì ba axɔsu ɔ sín hɔnmɛ kpo sinsɛnxɔ Vodun tɔn lɛ kpo kpɔ́n enyi mɛ nukúnɖeji lɛ yí gbè na ɔ nɛ."}, "yo": {"n": "Savalou, ọba aafin ati iṣu Festival", "d": "Ijọba Mahi atijọ, olokiki fun ajọdun iṣu nla rẹ.", "h": "Savalou ni ijoko ti ijọba Mahi ti ọba rẹ jẹ akọle Gbaguidi. Ni gbogbo ọdun, ni ayika Oṣu Kẹjọ, ayẹyẹ iṣu n ṣe ayẹyẹ ikore tuntun: awọn ayẹyẹ, awọn ijó ati awọn itọpa fa awọn agbegbe lati agbegbe naa. Ile ọba ati awọn convents Vodun ni a le ṣabẹwo pẹlu adehun ti awọn olokiki."}, "ha": {"n": "Savalou, gidan sarauta da bikin doya", "d": "Masarautar Mahi ta da, ta shahara da gagarumin bikin doya.", "h": "Savalou shi ne wurin zama na masarautar Mahi wanda sarkinsa ke da lakabin Gbaguidi. Kowace shekara, a kusan watan Agusta, bikin doya na bikin sabon girbi: bukukuwa, raye-raye da faretin suna jan hankalin mazauna yankin. Za a iya ziyartan gidan sarauta da gidajen ibada na Vodun tare da yarjejeniyar manyan mutane."}, "sw": {"n": "Savalou, jumba la kifalme na tamasha la yam", "d": "Ufalme wa kale wa Mahi, maarufu kwa tamasha lake kuu la yam.", "h": "Savalou ni kiti cha ufalme wa Mahi ambao mfalme wake ana cheo cha Gbaguidi. Kila mwaka, karibu Agosti, tamasha la viazi vikuu husherehekea mavuno mapya: sherehe, dansi na gwaride huvutia wenyeji kutoka eneo hilo. Ikulu ya kifalme na nyumba za watawa za Vodun zinaweza kutembelewa kwa makubaliano ya watu mashuhuri."}, "es": {"n": "Savalou, palacio real y festival del ñame", "d": "Antiguo reino de Mahi, famoso por su gran festival del ñame.", "h": "Savalou es la sede de un reino Mahi cuyo rey lleva el título de Gbaguidi. Cada año, alrededor de agosto, la fiesta del ñame celebra la nueva cosecha: ceremonias, bailes y desfiles atraen a los lugareños de la región. El palacio real y los conventos vudún se pueden visitar con el consentimiento de los notables."}, "pt": {"n": "Savalou, palácio real e festival do inhame", "d": "Antigo reino Mahi, famoso por seu grande festival de inhame.", "h": "Savalou é a sede de um reino Mahi cujo rei leva o título de Gbaguidi. Todos os anos, por volta de agosto, a festa do inhame celebra a nova colheita: cerimônias, danças e desfiles atraem moradores da região. O palácio real e os conventos Vodun podem ser visitados com a concordância de notáveis."}, "de": {"n": "Savalou, Königspalast und Yamswurzelfest", "d": "Altes Mahi-Königreich, berühmt für sein großes Yamswurzelfest.", "h": "Savalou ist der Sitz eines Mahi-Königreichs, dessen König den Titel Gbaguidi trägt. Jedes Jahr etwa im August feiert das Yamswurzelfest die neue Ernte: Zeremonien, Tänze und Paraden locken Einheimische aus der Region an. Der Königspalast und die Vodun-Klöster können mit Zustimmung der Honoratioren besichtigt werden."}, "it": {"n": "Savalou, palazzo reale e festa dell'igname", "d": "Antico regno di Mahi, famoso per il suo grande festival dell'igname.", "h": "Savalou è la sede del regno Mahi il cui re porta il titolo di Gbaguidi. Ogni anno, intorno ad agosto, la festa dell'igname celebra il nuovo raccolto: cerimonie, danze e sfilate attirano la gente del posto dalla regione. Il palazzo reale ed i conventi Vodun possono essere visitati previo accordo con notabili."}, "nl": {"n": "Savalou, koninklijk paleis en yamfestival", "d": "Het oude Mahi-koninkrijk, beroemd om zijn grote yamfestival.", "h": "Savalou is de zetel van een Mahi-koninkrijk waarvan de koning de titel Gbaguidi draagt. Elk jaar, rond augustus, viert het yamfestival de nieuwe oogst: ceremonies, dansen en parades trekken de lokale bevolking uit de regio aan. Het koninklijk paleis en de Vodun-kloosters kunnen worden bezocht met toestemming van notabelen."}, "ru": {"n": "Савалу, королевский дворец и фестиваль ямса", "d": "Древнее королевство Махи, известное своим великим фестивалем ямса.", "h": "Савалу — резиденция королевства Махи, король которого носит титул Гбагиди. Каждый год, примерно в августе, фестиваль батата отмечает новый урожай: церемонии, танцы и парады привлекают местных жителей из региона. Королевский дворец и монастыри Водун можно посетить с согласия знатных людей."}, "ar": {"n": "سافالو والقصر الملكي ومهرجان اليام", "d": "مملكة ماهي القديمة، المشهورة بمهرجان اليام العظيم.", "h": "سافالو هي مقر مملكة ماهي التي يحمل ملكها لقب غباجيدي. في كل عام، في شهر أغسطس تقريبًا، يحتفل مهرجان اليام بالحصاد الجديد: حيث تجتذب الاحتفالات والرقصات والمسيرات السكان المحليين من المنطقة. ويمكن زيارة القصر الملكي وأديرة الفودون بموافقة الأعيان."}, "zh": {"n": "萨瓦卢、皇宫和山药节", "d": "古老的马希王国，以盛大的山药节而闻名。", "h": "萨瓦卢是马希王国的首都，其国王的头衔是巴吉迪。每年八月左右，山药节都会庆祝新的收获：仪式、舞蹈和游行吸引着该地区的当地人。经名人同意，可以参观皇宫和沃顿修道院。"}, "ja": {"n": "サバルー、王宮、ヤムイモ祭り", "d": "盛大なヤムイモ祭りで有名な古代マヒ王国。", "h": "サバルーはマヒ王国の本拠地であり、その王はグバグイディの称号を持っています。毎年 8 月頃には、新収穫を祝うヤムイモ祭りが開催され、儀式、ダンス、パレードが行われ、地元の人々が集まります。王宮とヴォドゥン修道院は、著名人の同意があれば訪問できます。"}}, "aheme": {"fon": {"n": "Tɔsisa Ahémé kpo Possotomé kpo tɔn", "d": "Tɔsisa fífá tɔn, hweviwlitɔ gletoxo lɛ kpodo tɔsisa zozo jɔwamɔ tɔn lɛ kpo.", "h": "Tɔsisa Ahémé tɔn, ee nyí tɔsisa ɖaxó wegɔ ɔ ɖò Bénin é, ɖò hwevíwlítɔ́ Houéda kpo Adja kpo sín dogbó jí. Ðò Possotomé ɔ, tɔsisa e mɛ sin zozo e mɛ è nɔ mɔ nǔ xɔ akwɛ ɖè é ɖé nɔ tɔ́n sín, bɔ égbé ɔ, è nɔ sɔ́ dó go mɛ, bɔ è nɔ yí wǎn na ɖò tò ɔ bǐ mɛ. Mɛ lɛ nɔ wá fí nú tɔjihun kunkun, hwevíwlíwlí xóxó lɛ sín nǔmɔjɛnǔmɛ kpo fífá e ɖò tɔdo ɔ mɛ é kpo."}, "yo": {"n": "Lake Ahémé àti Possotomé", "d": "Adagun alaafia, awọn abule ipeja ati awọn orisun gbigbona adayeba.", "h": "Adágún Ahémé, adágún kejì tó tóbi jù lọ ní orílẹ̀-èdè Benin, jẹ́ ààlà sí àwọn abúlé ìpẹja Houéda àti Adja. Ni Possotomé orisun omi ti omi gbigbona ti o wa ni erupẹ ti ara ti n ṣan soke, loni ti o ni igo ati ti o mọrírì jakejado orilẹ-ede naa. Awọn eniyan wa nibi fun awọn gigun kẹkẹ, iṣawari ti ipeja ibile ati ifọkanbalẹ ti awọn banki."}, "ha": {"n": "Lake Ahémé da Possotomé", "d": "Tafki mai zaman lafiya, ƙauyukan kamun kifi da maɓuɓɓugan ruwan zafi na yanayi.", "h": "Tafkin Ahémé, tafki na biyu mafi girma a Benin, yana da iyaka da ƙauyukan kamun kifi na Houéda da Adja. A Possotomé maɓuɓɓugar ruwan zafi mai ma'adinai ta dabi'a ta samo asali, a yau kwalabe da kuma godiya a duk faɗin ƙasar. Mutane suna zuwa nan don hawan kwale-kwale, da gano kamun kifi na gargajiya da kuma kwantar da hankulan bankuna."}, "sw": {"n": "Ziwa Ahémé na Possotomé", "d": "Ziwa lenye amani, vijiji vya wavuvi na chemchemi za asili za maji moto.", "h": "Ziwa Ahémé, ziwa la pili kwa ukubwa nchini Benin, limepakana na vijiji vya wavuvi vya Houéda na Adja. Huko Possotomé chemchemi ya maji ya moto yenye madini kiasili huchipuka, ambayo leo yametiwa chupa na kuthaminiwa kote nchini. Watu huja hapa kwa ajili ya kupanda mitumbwi, ugunduzi wa uvuvi wa kitamaduni na utulivu wa benki."}, "es": {"n": "Lago Ahémé y Possotomé", "d": "Lago tranquilo, pueblos de pescadores y aguas termales naturales.", "h": "El lago Ahémé, el segundo lago más grande de Benin, está rodeado por los pueblos pesqueros de Houéda y Adja. En Possotomé brota un manantial de agua caliente mineralizada naturalmente, hoy embotellada y apreciada en todo el país. La gente viene aquí para pasear en canoa, descubrir la pesca tradicional y la tranquilidad de las orillas."}, "pt": {"n": "Lago Ahémé e Possotomé", "d": "Lago tranquilo, vilas de pescadores e fontes termais naturais.", "h": "O Lago Ahémé, o segundo maior lago do Benin, faz fronteira com as aldeias piscatórias de Houéda e Adja. Em Possotomé nasce uma nascente de água quente naturalmente mineralizada, hoje engarrafada e apreciada em todo o país. As pessoas vêm aqui para passeios de canoa, para a descoberta da pesca tradicional e para a calma das margens."}, "de": {"n": "Ahémé-See und Possotomé-See", "d": "Ruhiger See, Fischerdörfer und natürliche heiße Quellen.", "h": "Der Ahémé-See, der zweitgrößte See in Benin, wird von den Fischerdörfern Houéda und Adja begrenzt. In Possotomé entspringt eine Quelle mit natürlich mineralisiertem heißem Wasser, das heute in Flaschen abgefüllt wird und im ganzen Land geschätzt wird. Die Menschen kommen hierher, um Kanu zu fahren, die traditionelle Fischerei zu entdecken und die Ruhe an den Ufern zu genießen."}, "it": {"n": "Lago Ahémé e Possotomé", "d": "Lago tranquillo, villaggi di pescatori e sorgenti termali naturali.", "h": "Il lago Ahémé, il secondo lago più grande del Benin, è delimitato dai villaggi di pescatori di Houéda e Adja. A Possotomé sgorga una sorgente di acqua calda naturalmente mineralizzata, oggi imbottigliata e apprezzata in tutto il Paese. La gente viene qui per le passeggiate in canoa, la scoperta della pesca tradizionale e la calma delle rive."}, "nl": {"n": "Meer van Ahémé en Possotomé", "d": "Vreedzaam meer, vissersdorpjes en natuurlijke warmwaterbronnen.", "h": "Het meer van Ahémé, het op een na grootste meer van Benin, wordt begrensd door de vissersdorpjes Houéda en Adja. In Possotomé ontspringt een bron met natuurlijk gemineraliseerd heet water, dat tegenwoordig in flessen wordt gebotteld en door het hele land wordt gewaardeerd. Mensen komen hier voor kanotochten, de ontdekking van de traditionele visserij en de rust van de oevers."}, "ru": {"n": "Озеро Ахеме и Поссотоме", "d": "Тихое озеро, рыбацкие деревни и природные горячие источники.", "h": "Озеро Ахеме, второе по величине озеро в Бенине, граничит с рыбацкими деревнями Уэда и Аджа. В Посотоме бьет источник естественно минерализованной горячей воды, которая сегодня разливается в бутылки и ценится по всей стране. Люди приезжают сюда, чтобы покататься на каноэ, открыть для себя традиционную рыбалку и спокойствие берегов."}, "ar": {"n": "بحيرة Ahémé وPossotomé", "d": "بحيرة هادئة وقرى صيد وينابيع طبيعية ساخنة.", "h": "بحيرة Ahémé، ثاني أكبر بحيرة في بنين، تحدها قريتي الصيد هويدا وأجا. في بوسوتوم ينبع ينبوع من الماء الساخن المعدني بشكل طبيعي، المعبأ اليوم في زجاجات ويحظى بالتقدير في جميع أنحاء البلاد. يأتي الناس إلى هنا لركوب الزوارق واكتشاف الصيد التقليدي وهدوء البنوك."}, "zh": {"n": "阿赫梅湖和波索托梅湖", "d": "宁静的湖泊、渔村和天然温泉。", "h": "阿赫梅湖是贝宁第二大湖，毗邻胡埃达和阿贾渔村。波索托梅涌出天然矿化热水，如今已装瓶并在全国各地受到欢迎。人们来这里是为了划独木舟、探索传统捕鱼和享受河岸的平静。"}, "ja": {"n": "アエメ湖とポッソトメ湖", "d": "静かな湖、漁村、天然温泉。", "h": "ベナンで 2 番目に大きい湖であるアヘメ湖は、ウエダ漁村とアジャ漁村に隣接しています。ポッソトメには、天然に鉱化された温泉が湧き出ており、現在ではボトルに詰められ、国中で高く評価されています。人々はカヌーに乗ったり、伝統的な釣りを体験したり、岸辺の静けさを求めてここにやって来ます。"}}, "boucheroy": {"fon": {"n": "Axɔsu ɔ sín nu .", "d": "Fí e Mono Tɔdo ɔ nɔ kpé xù ɔ ɖè é: mangrove lɛ, xɛvi lɛ kpodo xù xɛví lɛ kpo.", "h": "La Bouche du Roy wɛ nyi tɔsisa Mono tɔn sin nu, ɖo tɔsisa lɛ, mangrove lɛ kpodo tɔsisa zunkan mɛ tɔn lɛ kpo tɛntin. É ɖò Mono Delta sín dogbó e jí è nɔ hɛn nǔɖogbɛ lɛ ɖó é mɛ, bɔ UNESCO yí gbè na ɖò 2017 xá Togo. È nɔ gbɔn tɔjihun mɛ bo nɔ gosin Grand-Popo bo nɔ yì finɛ; sín juillet jɛ février mɛ ɔ, xùzɔ́nmɛví lɛ nɔ wá bɛ́ azin yetɔn lɛ ɖò xùtó e sɛkpɔ finɛ lɛ é jí. Akwɛ e è xlɛ́ é wɛ nyí tomɛyiyi tɔjihun tɔn ɖé tɔn, bɔ è na ɖɔ xó d’eji."}, "yo": {"n": "Ẹnu Ọba", "d": "Ibi ti awọn Mono River pàdé awọn nla: mangroves, eye ati okun ijapa.", "h": "La Bouche du Roy jẹ ẹnu ti odo Mono, laarin awọn adagun, mangroves ati awọn eti okun egan. O jẹ apakan ti Mono Delta cross-aala biosphere Reserve, ti a mọ nipasẹ UNESCO ni ọdun 2017 pẹlu Togo. O ti de nipasẹ canoe lati Grand-Popo; lati Keje si Kínní, awọn ijapa okun wa lati dubulẹ awọn eyin wọn lori awọn eti okun agbegbe. Iye owo ti a tọka si jẹ ti irin-ajo ọkọ oju omi, lati ṣe idunadura."}, "ha": {"n": "Bakin Sarki", "d": "Inda kogin Mono ya hadu da teku: mangroves, tsuntsaye da kunkuru na teku.", "h": "La Bouche du Roy shine bakin kogin Mono, tsakanin lagoons, mangroves da rairayin bakin teku masu. Wani yanki ne na Mono Delta ƙetare iyakokin biosphere, wanda UNESCO ta gane a cikin 2017 tare da Togo. An isa ta kwale-kwale daga Grand-Popo; daga Yuli zuwa Fabrairu, kunkuru na teku suna zuwa don yin ƙwai a kan rairayin bakin teku masu makwabta. Farashin da aka nuna shine na balaguron kwale-kwale, don tattaunawa."}, "sw": {"n": "Kinywa cha Mfalme", "d": "Ambapo Mto Mono hukutana na bahari: mikoko, ndege na kasa wa baharini.", "h": "La Bouche du Roy ni mdomo wa mto Mono, kati ya rasi, mikoko na fukwe pori. Ni sehemu ya hifadhi ya mpakani ya Mono Delta, inayotambuliwa na UNESCO mnamo 2017 na Togo. Inafikiwa kwa mtumbwi kutoka Grand-Popo; kuanzia Julai hadi Februari, kasa wa baharini huja kutaga mayai kwenye fuo za jirani. Bei iliyoonyeshwa ni ile ya safari ya mtumbwi, itakayojadiliwa."}, "es": {"n": "Boca del Rey", "d": "Donde el río Mono se encuentra con el océano: manglares, aves y tortugas marinas.", "h": "La Bouche du Roy es la desembocadura del río Mono, entre lagunas, manglares y playas salvajes. Forma parte de la reserva de biosfera transfronteriza del Delta del Mono, reconocida por la UNESCO en 2017 con Togo. Se llega en canoa desde Grand-Popo; De julio a febrero, las tortugas marinas vienen a desovar en las playas vecinas. El precio indicado es el de una excursión en canoa, a negociar."}, "pt": {"n": "Boca do Rei", "d": "Onde o rio Mono encontra o oceano: manguezais, pássaros e tartarugas marinhas.", "h": "La Bouche du Roy é a foz do rio Mono, entre lagoas, manguezais e praias selvagens. Faz parte da reserva da biosfera transfronteiriça do Mono Delta, reconhecida pela UNESCO em 2017 com o Togo. O acesso é feito de canoa desde Grand-Popo; de julho a fevereiro, as tartarugas marinhas vêm desovar nas praias vizinhas. O preço indicado é o de um passeio de canoa, a negociar."}, "de": {"n": "Mund des Königs", "d": "Wo der Mono River auf das Meer trifft: Mangroven, Vögel und Meeresschildkröten.", "h": "La Bouche du Roy ist die Mündung des Flusses Mono, zwischen Lagunen, Mangroven und wilden Stränden. Es ist Teil des grenzüberschreitenden Biosphärenreservats Monodelta, das 2017 von der UNESCO mit Togo anerkannt wurde. Es ist mit dem Kanu von Grand-Popo aus zu erreichen; Von Juli bis Februar kommen Meeresschildkröten zur Eiablage an die benachbarten Strände. Der angegebene Preis ist der eines Kanuausflugs und muss ausgehandelt werden."}, "it": {"n": "Bocca del Re", "d": "Dove il fiume Mono incontra l'oceano: mangrovie, uccelli e tartarughe marine.", "h": "La Bouche du Roy è la foce del fiume Mono, tra lagune, mangrovie e spiagge selvagge. Fa parte della riserva transfrontaliera della biosfera del Mono Delta, riconosciuta dall'UNESCO nel 2017 con il Togo. Si raggiunge in canoa da Grand-Popo; da luglio a febbraio le tartarughe marine vengono a deporre le uova sulle spiagge vicine. Il prezzo indicato è quello di un'escursione in canoa, da concordare."}, "nl": {"n": "Monding van de koning", "d": "Waar de Mono-rivier de oceaan ontmoet: mangroven, vogels en zeeschildpadden.", "h": "La Bouche du Roy is de monding van de Mono-rivier, tussen lagunes, mangroven en wilde stranden. Het maakt deel uit van het grensoverschrijdende biosfeerreservaat Mono Delta, dat in 2017 samen met Togo door UNESCO werd erkend. Het is bereikbaar per kano vanuit Grand-Popo; van juli tot februari komen zeeschildpadden hun eieren leggen op de naburige stranden. De aangegeven prijs is die van een kanotocht, waarover te onderhandelen is."}, "ru": {"n": "Уста короля", "d": "Там, где река Моно встречается с океаном: мангровые заросли, птицы и морские черепахи.", "h": "Ла-Буш-дю-Руа — это устье реки Моно, окруженное лагунами, мангровыми зарослями и дикими пляжами. Он является частью трансграничного биосферного заповедника «Дельта Моно», признанного ЮНЕСКО в 2017 году совместно с Того. До него можно добраться на каноэ из Гранд-Попо; с июля по февраль морские черепахи приходят откладывать яйца на соседние пляжи. Указанная цена соответствует цене экскурсии на каноэ, подлежит обсуждению."}, "ar": {"n": "فم الملك", "d": "حيث يلتقي نهر مونو بالمحيط: أشجار المانغروف والطيور والسلاحف البحرية.", "h": "يقع La Bouche du Roy عند مصب نهر مونو، بين البحيرات وأشجار المانغروف والشواطئ البرية. وهي جزء من محمية المحيط الحيوي عبر الحدود في دلتا مونو، والتي اعترفت بها اليونسكو في عام 2017 مع توغو. يتم الوصول إليه بواسطة الزورق من Grand-Popo؛ ومن يوليو إلى فبراير، تأتي السلاحف البحرية لتضع بيضها على الشواطئ المجاورة. السعر المشار إليه هو سعر رحلة بالقارب، وسيتم التفاوض بشأنه."}, "zh": {"n": "国王之口", "d": "莫诺河与海洋的交汇处：红树林、鸟类和海龟。", "h": "La Bouche du Roy 是莫诺河的河口，位于泻湖、红树林和野生海滩之间。它是莫诺三角洲跨境生物圈保护区的一部分，于2017年与多哥一起获得联合国教科文组织认可。从 Grand-Popo 乘独木舟即可到达；从七月到二月，海龟会来到附近的海滩产卵。所示价格是独木舟游览的价格，有待协商。"}, "ja": {"n": "王の口", "d": "モノ川が海と出会う場所: マングローブ、鳥、ウミガメ。", "h": "ラ ブーシュ デュ ロワは、ラグーン、マングローブ、野生のビーチの間にあるモノ川の河口です。ここはモノデルタ国境を越えた生物圏保護区の一部であり、2017年にトーゴとともにユネスコによって承認されました。グランポポからはカヌーでアクセスできます。 7 月から 2 月にかけて、ウミガメが近くの海岸に産卵にやって来ます。表示されている料金はカヌーツアーの料金です。ご相談に応じます。"}}, "grandpopo": {"fon": {"n": "Popo sín xùtó", "d": "Xùtó gaga e jí agɔnkɛ́tín lɛ ɖè é, toxo ajɔ̌wiwa tɔn xóxó ɔ.", "h": "Toxo e mɛ è nɔ sà nǔ ɖè ɖ’ayǐ bɔ è nɔ ɖu acɛ dó jí hwenɛnu é ɖé wɛ Grand-Popo nyí fí e è nɔ ɖu vivǐ tɔn ɖè ɖò xùtó é ɖé égbé. Villa Karo sín aca e Finlande-nu lɛ ɖó ayǐ é nɔ bló nǔxlɛ́mɛ lɛ kpo hanjiji lɛ kpo ɖò finɛ. Lee é nɔ nyí gbɔn ɖò fí ɖebǔ ɖò agě ɔ jí é ɔ, tɔlinlin byɔ ɖɔ è ni cɔ́ mɛɖée."}, "yo": {"n": "Grand Popo Beach", "d": "Etikun gigun ti o ni ila pẹlu awọn igi agbon, ilu iṣowo atijọ.", "h": "Ibudo iṣowo iṣaaju lẹhinna ilu amunisin ni apakan gbe nipasẹ ogbara eti okun, Grand-Popo jẹ ibi isinmi eti okun ti o dakẹ loni. Ile-iṣẹ aṣa ti Villa Karo, ti o da nipasẹ awọn Finns, ṣeto awọn ifihan ati awọn ere orin nibẹ. Bii ibi gbogbo ni etikun, odo nilo iṣọra."}, "ha": {"n": "Grand Popo Beach", "d": "Dogon bakin teku mai layi da bishiyoyin kwakwa, tsohon garin ciniki.", "h": "Tsohuwar tashar jiragen ruwa sannan garin da ke mulkin mallaka wani bangare ya cinye shi ta hanyar zaizayar gabar teku, Grand-Popo a yau wurin shakatawa ne na bakin teku. Cibiyar al'adun gargajiya ta Villa Karo, wanda Finnish suka kafa, tana shirya nune-nunen nune-nunen da kide-kide a wurin. Kamar ko'ina a bakin teku, yin iyo yana buƙatar taka tsantsan."}, "sw": {"n": "Pwani ya Grand Popo", "d": "Pwani ndefu iliyo na miti ya nazi, mji wa zamani wa biashara.", "h": "Bandari ya zamani ya biashara kisha mji wa kikoloni uliomezwa kwa kiasi na mmomonyoko wa pwani, Grand-Popo leo ni kituo tulivu cha bahari. Kituo cha kitamaduni cha Villa Karo, kilichoanzishwa na Finns, hupanga maonyesho na matamasha huko. Kama kila mahali kwenye pwani, kuogelea kunahitaji tahadhari."}, "es": {"n": "Playa Grand Popo", "d": "Larga playa bordeada de cocoteros, antigua ciudad comercial.", "h": "Grand-Popo, antiguo puerto comercial y luego ciudad colonial parcialmente absorbida por la erosión costera, es hoy un tranquilo balneario. El centro cultural Villa Karo, fundado por finlandeses, organiza allí exposiciones y conciertos. Como en todas partes de la costa, nadar requiere precaución."}, "pt": {"n": "Praia do Grande Popo", "d": "Longa praia repleta de coqueiros, antiga cidade comercial.", "h": "Antigo porto comercial e depois cidade colonial parcialmente engolida pela erosão costeira, Grand-Popo é hoje uma tranquila estância balnear. O centro cultural Villa Karo, fundado por finlandeses, organiza exposições e concertos no local. Como em todo o litoral, nadar exige cautela."}, "de": {"n": "Grand-Popo-Strand", "d": "Langer, von Kokospalmen gesäumter Strand, alte Handelsstadt.", "h": "Grand-Popo war einst ein Handelshafen und wurde dann teilweise von der Küstenerosion verschluckt. Heute ist es ein ruhiger Badeort. Das von Finnen gegründete Kulturzentrum Villa Karo organisiert dort Ausstellungen und Konzerte. Wie überall an der Küste ist beim Schwimmen Vorsicht geboten."}, "it": {"n": "Spiaggia del Gran Popo", "d": "Lunga spiaggia fiancheggiata da palme da cocco, antica città commerciale.", "h": "Antico porto commerciale e poi città coloniale, in parte inghiottita dall'erosione costiera, Grand-Popo è oggi una tranquilla località balneare. Il centro culturale Villa Karo, fondato dai finlandesi, vi organizza mostre e concerti. Come ovunque sulla costa, la balneazione richiede cautela."}, "nl": {"n": "Grand Popo-strand", "d": "Lang strand omzoomd met kokospalmen, oude handelsstad.", "h": "Grand-Popo, voormalig handelshaven en vervolgens koloniale stad, gedeeltelijk verzwolgen door kusterosie, is tegenwoordig een rustige badplaats. Het door Finnen opgerichte culturele centrum Villa Karo organiseert daar tentoonstellingen en concerten. Zoals overal aan de kust vereist zwemmen voorzichtigheid."}, "ru": {"n": "Гранд-Попо-Бич", "d": "Длинный пляж с кокосовыми пальмами, старый торговый город.", "h": "Бывший торговый порт, затем колониальный город, частично поглощенный береговой эрозией, Гран-Попо сегодня является тихим морским курортом. Культурный центр «Вилла Каро», основанный финнами, организует здесь выставки и концерты. Как и везде на побережье, купание требует осторожности."}, "ar": {"n": "شاطئ جراند بوبو", "d": "شاطئ طويل تصطف على جانبيه أشجار جوز الهند، وهي مدينة تجارية قديمة.", "h": "ميناء تجاري سابق ثم مدينة استعمارية ابتلعتها التآكل الساحلي جزئيًا، أصبحت جراند بوبو اليوم منتجعًا ساحليًا هادئًا. ينظم مركز فيلا كارو الثقافي، الذي أسسه الفنلنديون، المعارض والحفلات الموسيقية هناك. كما هو الحال في كل مكان على الساحل، تتطلب السباحة الحذر."}, "zh": {"n": "大波波海滩", "d": "长长的海滩两旁种满了椰子树，古老的贸易城镇。", "h": "大波波曾是贸易港口，后来成为殖民城镇，部分被海岸侵蚀所吞没，如今已成为一个安静的海滨度假胜地。由芬兰人创办的维拉卡罗文化中心在那里举办展览和音乐会。与海岸上的其他地方一样，游泳也需要小心谨慎。"}, "ja": {"n": "グランド ポポ ビーチ", "d": "ココナッツの木が並ぶ長いビーチ、古い貿易都市。", "h": "かつては貿易港であったが、海岸浸食によって一部が飲み込まれた植民地時代の町、グラン ポポは、現在は静かな海辺のリゾートになっています。フィンランド人によって設立されたヴィラ カロ文化センターでは、展示会やコンサートが開催されています。海岸の他の場所と同様、水泳には注意が必要です。"}}, "pendjari": {"fon": {"n": "Pendjari sín jikpá", "d": "Fí e kinikini e ɖò Totaligbé Aflika tɔn lɛ é nɔ hɔn hwla cí é gudogudo tɔn lɛ ɖokpo. Safari ɖò tò ɔ sín totaligbe.", "h": "È ɖó Pendjari ɔ ayǐ ɖi kanlinnyitɛn ɖé ɖò xwè 1950 lɛ mɛ, bɔ é huzu jikpá tò ɔ tɔn ɖò 1961, bɔ é ɖiga hú kilomɛtlu 4 700 ɖò tɔsisa e ɖó nyikɔ ɖokpo ɔ é kpá. É ɖò W-Arly-Pendjari sín xɔgbigbázɔ́watɛn ɔ mɛ, bɔ è sɔ́ UNESCO dó ɖó nǔɖokan gbɛ̀ ɔ tɔn lɛ (è jlaɖó ɖò 2017). Mǐ nɔ kpɔ́n ajinakú lɛ, xɛví lɛ, xɛví lɛ, xɛví lɛ kpo hweɖelɛnu ɔ, kinikini lɛ kpo xɛví lɛ kpo. Sin 2017 ɔ, ONG African Parks wɛ nɔ kpé nukún dó jikpá ɔ wu. Hwenu e nyɔ́ hugǎn é: akú hwenu, bɛ́sín Woosun jɛ Lidosun mɛ. Kpɔ́n nǔ dó lee è na byɔ mɛ gbɔn é kpo lee è na cyɔn alɔ mɛ jí gbɔn é kpo wu cobo yì."}, "yo": {"n": "Pendjari National Park", "d": "Ọkan ninu awọn ibugbe ti o kẹhin ti awọn kiniun Iwọ-oorun Afirika. Safari ni ariwa ti orilẹ-ede naa.", "h": "Ti a ṣẹda bi ibi ipamọ egan ni awọn ọdun 1950, eyiti o di ọgba-itura ti orilẹ-ede ni ọdun 1961, Pendjari gbooro diẹ sii ju 4,700 km² lẹba odo ti orukọ kanna. O jẹ apakan ti eka W-Arly-Pendjari, ti a ṣe akojọ si bi Aye Ajogunba Aye ti UNESCO (itẹsiwaju 2017). A n ṣakiyesi awọn erin, awọn ẹfọn, awọn erinmi, awọn antelopes ati awọn igba miiran kiniun ati cheetahs. Lati ọdun 2017, o duro si ibikan ti ni iṣakoso pẹlu NGO African Parks. Akoko ti o dara julọ: akoko gbigbẹ, lati Oṣù Kejìlá si May. Wa nipa wiwọle ati awọn ipo aabo ṣaaju ki o to lọ."}, "ha": {"n": "Pendjari National Park", "d": "Ɗaya daga cikin mafaka na ƙarshe na zakunan Afirka ta Yamma. Safari a arewacin kasar.", "h": "An ƙirƙira shi azaman ajiyar namun daji a cikin 1950s, wanda ya zama wurin shakatawa na ƙasa a cikin 1961, Pendjari ya shimfiɗa fiye da 4,700 km² tare da kogin suna iri ɗaya. Yana daga cikin rukunin W-Arly-Pendjari, wanda aka jera a matsayin Cibiyar Tarihin Duniya ta UNESCO (ƙara 2017). Muna lura da giwaye, buffaloes, hippos, antelopes da wasu lokutan zakuna da cheetah. Tun daga 2017, ana gudanar da wurin shakatawa tare da NGO na Afirka Parks. Mafi kyawun lokacin: lokacin rani, daga Disamba zuwa Mayu. Nemo game da samun dama da yanayin tsaro kafin tafiya."}, "sw": {"n": "Hifadhi ya Kitaifa ya Pendjari", "d": "Moja ya kimbilio la mwisho la simba wa Afrika Magharibi. Safari kaskazini mwa nchi.", "h": "Iliundwa kama hifadhi ya wanyamapori katika miaka ya 1950, ambayo ikawa mbuga ya kitaifa mnamo 1961, Pendjari inaenea zaidi ya kilomita 4,700 za mraba kando ya mto wa jina moja. Ni sehemu ya tata ya W-Arly-Pendjari, iliyoorodheshwa kama Tovuti ya Urithi wa Dunia wa UNESCO (ugani wa 2017). Tunachunguza tembo, nyati, viboko, swala na wakati mwingine simba na duma. Tangu 2017, mbuga hiyo imekuwa ikisimamiwa na NGO ya African Parks. Wakati mzuri: msimu wa kavu, kuanzia Desemba hadi Mei. Jua kuhusu hali ya ufikiaji na usalama kabla ya kuondoka."}, "es": {"n": "Parque Nacional Pendjari", "d": "Uno de los últimos refugios de los leones de África occidental. Safari en el norte del país.", "h": "Creado como reserva natural en los años 50 y convertido en parque nacional en 1961, el Pendjari se extiende sobre más de 4.700 km² a lo largo del río del mismo nombre. Forma parte del complejo W-Arly-Pendjari, declarado Patrimonio de la Humanidad por la UNESCO (ampliación de 2017). Observamos elefantes, búfalos, hipopótamos, antílopes y, en ocasiones, leones y guepardos. Desde 2017, el parque se gestiona con la ONG African Parks. Mejor época: estación seca, de diciembre a mayo. Infórmate de las condiciones de acceso y seguridad antes de salir."}, "pt": {"n": "Parque Nacional Pendjari", "d": "Um dos últimos refúgios dos leões da África Ocidental. Safari no norte do país.", "h": "Criado como reserva de vida selvagem na década de 1950, que se tornou parque nacional em 1961, o Pendjari se estende por mais de 4.700 km² ao longo do rio de mesmo nome. Faz parte do complexo W-Arly-Pendjari, listado como Patrimônio Mundial da UNESCO (extensão de 2017). Observamos elefantes, búfalos, hipopótamos, antílopes e às vezes leões e chitas. Desde 2017, o parque é gerido pela ONG African Parks. Melhor época: estação seca, de dezembro a maio. Informe-se sobre as condições de acesso e segurança antes de partir."}, "de": {"n": "Pendjari-Nationalpark", "d": "Einer der letzten Zufluchtsorte westafrikanischer Löwen. Safari im Norden des Landes.", "h": "Der Pendjari wurde in den 1950er Jahren als Wildreservat angelegt und 1961 zum Nationalpark erklärt und erstreckt sich über mehr als 4.700 km² entlang des gleichnamigen Flusses. Es ist Teil des W-Arly-Pendjari-Komplexes, der zum UNESCO-Weltkulturerbe gehört (Erweiterung 2017). Wir beobachten Elefanten, Büffel, Flusspferde, Antilopen und manchmal auch Löwen und Geparden. Seit 2017 wird der Park von der NGO African Parks verwaltet. Beste Zeit: Trockenzeit, von Dezember bis Mai. Informieren Sie sich vor Ihrer Abreise über die Zugangs- und Sicherheitsbedingungen."}, "it": {"n": "Parco Nazionale Pendjari", "d": "Uno degli ultimi rifugi dei leoni dell'Africa occidentale. Safari nel nord del paese.", "h": "Nato come riserva faunistica negli anni '50 e divenuto parco nazionale nel 1961, il Pendjari si estende per oltre 4.700 km² lungo il fiume omonimo. Fa parte del complesso W-Arly-Pendjari, dichiarato patrimonio dell'umanità dall'UNESCO (estensione del 2017). Osserviamo elefanti, bufali, ippopotami, antilopi e talvolta leoni e ghepardi. Dal 2017 il parco è gestito con la ONG African Parks. Periodo migliore: stagione secca, da dicembre a maggio. Informati sulle condizioni di accesso e sicurezza prima di partire."}, "nl": {"n": "Pendjari Nationaal Park", "d": "Een van de laatste toevluchtsoorden van West-Afrikaanse leeuwen. Safari in het noorden van het land.", "h": "De Pendjari, opgericht als natuurreservaat in de jaren vijftig en in 1961 een nationaal park, strekt zich uit over meer dan 4.700 km² langs de gelijknamige rivier. Het maakt deel uit van het W-Arly-Pendjari-complex, dat op de Werelderfgoedlijst van UNESCO staat (uitbreiding 2017). We observeren olifanten, buffels, nijlpaarden, antilopen en soms leeuwen en cheeta’s. Sinds 2017 wordt het park beheerd door de NGO African Parks. Beste tijd: droge seizoen, van december tot mei. Lees meer over de toegang en veiligheidsvoorwaarden voordat u vertrekt."}, "ru": {"n": "Национальный парк Пенджари", "d": "Одно из последних прибежищ западноафриканских львов. Сафари на севере страны.", "h": "Созданный в 1950-х годах как заповедник дикой природы, ставший национальным парком в 1961 году, Пенджари простирается на площади более 4700 км² вдоль одноименной реки. Он является частью комплекса W-Арли-Пенджари, внесенного в список Всемирного наследия ЮНЕСКО (расширение в 2017 году). Мы наблюдаем слонов, буйволов, бегемотов, антилоп, а иногда и львов и гепардов. С 2017 года парком управляет неправительственная организация African Parks. Лучшее время: сухой сезон, с декабря по май. Перед отъездом узнайте об условиях доступа и безопасности."}, "ar": {"n": "حديقة بنجاري الوطنية", "d": "أحد الملاجئ الأخيرة لأسود غرب أفريقيا. سفاري في شمال البلاد.", "h": "تم إنشاء نهر بنجاري كمحمية للحياة البرية في الخمسينيات، ثم أصبح متنزهًا وطنيًا في عام 1961، ويمتد على مساحة تزيد عن 4700 كيلومتر مربع على طول النهر الذي يحمل نفس الاسم. وهو جزء من مجمع W-Arly-Pendjari المدرج ضمن مواقع التراث العالمي لليونسكو (امتداد 2017). نلاحظ الفيلة والجاموس وأفراس النهر والظباء وأحيانًا الأسود والفهود. منذ عام 2017، تتم إدارة الحديقة مع منظمة أفريكان باركس غير الحكومية. أفضل وقت: موسم الجفاف، من ديسمبر إلى مايو. تعرف على شروط الوصول والأمن قبل المغادرة."}, "zh": {"n": "彭贾里国家公园", "d": "西非狮子最后的避难所之一。在该国北部进行野生动物园。", "h": "彭贾里 (Pendjari) 于 20 世纪 50 年代创建为野生动物保护区，并于 1961 年成为国家公园，沿着同名河流绵延超过 4,700 平方公里。它是 W-Arly-Pendjari 建筑群的一部分，被列为联合国教科文组织世界遗产（2017 年扩建）。我们观察大象、水牛、河马、羚羊，有时还观察狮子和猎豹。自 2017 年以来，该公园由非政府组织非洲公园管理。最佳时间：旱季，从十二月到五月。离开前了解有关通行和安全条件的信息。"}, "ja": {"n": "ペンジャリ国立公園", "d": "西アフリカのライオンの最後の避難所の 1 つ。国の北部のサファリ。", "h": "1950 年代に野生動物保護区として創設され、1961 年に国立公園となったペンジャリは、同名の川沿いに 4,700 km² 以上に広がっています。これは、ユネスコの世界遺産（2017 年延長）に登録されている W-Arly-Pendjari 複合施設の一部です。ゾウ、水牛、カバ、カモシカ、時にはライオンやチーターを観察します。 2017 年からこの公園は NGO アフリカン・パークスと協力して管理されています。最適な時期: 乾季、12 月から 5 月。出発前にアクセスとセキュリティ状況を確認してください。"}}, "parcw": {"fon": {"n": "W Parc Akɔta ɔ tɔn", "d": "Jikpá ɖaxó e gbɔn dogbó jí é ɖé wɛ è sun nyǐ ɖó Niger Tɔdo ɔ sín tɔ̀ e ɖò xixo wɛ lɛ é wu.", "h": "Tɔdo Niger tɔn e ɖò xixo wɛ bɔ é cí W ɖɔhun é wɛ zɔ́n bɔ è ɖó nyikɔ jikpá ɔ tɔn. E nɔ má ɖò Benin, Niger kpo Burkina Faso kpo tɛntin, bo ɖò W-Arly-Pendjari sín xɔgbigbázɔ́watɛn e è sɔ́ ɖó wěma mɛ bo nyí nǔɖokan gbɛ̀ ɔ tɔn lɛ é mɛ. É nyí fí ɖaxó ɖé bɔ è nɔ mɔ zunkan ɖaxó ɖaxó lɛ kpo zunkan ɖaxó ɖaxó lɛ kpo ɖè bɔ ajinakú lɛ, xɛví lɛ kpo xɛví lɛ kpo nɔ nɔ finɛ. È ɖó dogbó nú fí e è na yì é: é ɖò taji ɖɔ è ni kpɔ́n alixlɛ́mɛ ayijayǐ tɔn e ɖò ayǐ lɛ é cobo yì tofɔligbé."}, "yo": {"n": "W National Park", "d": "Ogba irekọja nla ti a npè ni lẹhin awọn meanders ti Odò Niger.", "h": "O duro si ibikan gba orukọ rẹ lati W-sókè meanders ti Niger River. Pínpín laarin Benin, Niger ati Burkina Faso, o jẹ apakan ti eka W-Arly-Pendjari ti a ṣe akojọ si bi aaye ohun-ini agbaye. O jẹ agbegbe nla ti savannahs ati awọn igbo ibi-iṣafihan nibiti awọn erin, buffalo ati awọn antelopes n gbe. Iwọle si ni ihamọ: o ṣe pataki lati ṣayẹwo awọn ilana aabo ni agbara ṣaaju ki o to rin irin-ajo lọ si ariwa."}, "ha": {"n": "W National Park", "d": "Katafaren wurin shakatawa na tsallake-tsallake mai suna bayan masu rajin kogin Neja.", "h": "Gidan shakatawa ya samo sunansa daga ma'aikatan kogin Neja masu siffar W. An raba tsakanin Benin, Nijar da Burkina Faso, wani yanki ne na rukunin W-Arly-Pendjari da aka jera a matsayin wurin tarihi na duniya. Yana da faffadan yanki na savannahs da gandun daji inda giwaye, buffalo da tururuwa ke zaune. An iyakance isa ga: yana da mahimmanci don bincika umarnin aminci da ke aiki kafin tafiya zuwa arewa."}, "sw": {"n": "W Hifadhi ya Taifa", "d": "Mbuga kubwa ya kuvuka mpaka iliyopewa jina la miteremko ya Mto Niger.", "h": "Hifadhi hiyo ilichukua jina lake kutoka kwa njia ya umbo la W ya Mto Niger. Imeshirikiwa kati ya Benin, Niger na Burkina Faso, ni sehemu ya majengo ya W-Arly-Pendjari yaliyoorodheshwa kama tovuti ya urithi wa dunia. Ni eneo kubwa la savannah na misitu ya matunzio ambapo tembo, nyati na swala wanaishi. Ufikiaji umezuiwa: ni muhimu kuangalia maagizo ya usalama yanayotumika kabla ya kusafiri kuelekea kaskazini."}, "es": {"n": "Parque Nacional W", "d": "Enorme parque transfronterizo que lleva el nombre de los meandros del río Níger.", "h": "El parque toma su nombre de los meandros en forma de W del río Níger. Compartido entre Benin, Níger y Burkina Faso, forma parte del complejo W-Arly-Pendjari catalogado como patrimonio de la humanidad. Es una vasta zona de sabanas y bosques de galería donde viven elefantes, búfalos y antílopes. El acceso está restringido: es imprescindible consultar las instrucciones de seguridad vigentes antes de viajar hacia el norte."}, "pt": {"n": "Parque Nacional W", "d": "Enorme parque transfronteiriço que leva o nome dos meandros do rio Níger.", "h": "O nome do parque vem dos meandros em forma de W do rio Níger. Compartilhado entre Benin, Níger e Burkina Faso, faz parte do complexo W-Arly-Pendjari listado como patrimônio mundial. É uma vasta área de savanas e matas de galeria onde vivem elefantes, búfalos e antílopes. O acesso é restrito: é imprescindível consultar as instruções de segurança em vigor antes de viajar para o norte."}, "de": {"n": "W-Nationalpark", "d": "Riesiger grenzüberschreitender Park, benannt nach den Mäandern des Niger.", "h": "Der Park hat seinen Namen von den W-förmigen Mäandern des Niger. Es liegt zwischen Benin, Niger und Burkina Faso und ist Teil des W-Arly-Pendjari-Komplexes, der zum Weltkulturerbe gehört. Es ist ein riesiges Gebiet mit Savannen und Galeriewäldern, in dem Elefanten, Büffel und Antilopen leben. Der Zugang ist eingeschränkt: Informieren Sie sich unbedingt über die geltenden Sicherheitsvorschriften, bevor Sie in den Norden reisen."}, "it": {"n": "Parco Nazionale W", "d": "Enorme parco transfrontaliero che prende il nome dai meandri del fiume Niger.", "h": "Il parco prende il nome dai meandri a forma di W del fiume Niger. Condiviso tra Benin, Niger e Burkina Faso, fa parte del complesso W-Arly-Pendjari dichiarato patrimonio dell'umanità. Si tratta di una vasta area di savane e foreste a galleria dove vivono elefanti, bufali e antilopi. L'accesso è limitato: è indispensabile verificare le norme di sicurezza in vigore prima di mettersi in viaggio verso nord."}, "nl": {"n": "W Nationaal Park", "d": "Enorm grensoverschrijdend park vernoemd naar de meanders van de rivier de Niger.", "h": "Het park ontleent zijn naam aan de W-vormige meanders van de rivier de Niger. Het wordt gedeeld tussen Benin, Niger en Burkina Faso en maakt deel uit van het W-Arly-Pendjari-complex dat op de werelderfgoedlijst staat. Het is een uitgestrekt gebied met savannes en galerijbossen waar olifanten, buffels en antilopen leven. De toegang is beperkt: het is essentieel om de geldende veiligheidsinstructies te controleren voordat u naar het noorden reist."}, "ru": {"n": "Национальный парк W", "d": "Огромный трансграничный парк, названный в честь излучин реки Нигер.", "h": "Парк получил свое название от W-образных излучин реки Нигер. Разделенный между Бенином, Нигером и Буркина-Фасо, он является частью комплекса W-Арли-Пенджари, внесенного в список всемирного наследия. Это обширная территория саванн и галерейных лесов, где обитают слоны, буйволы и антилопы. Доступ ограничен: перед поездкой на север необходимо ознакомиться с действующими инструкциями по безопасности."}, "ar": {"n": "حديقة دبليو الوطنية", "d": "متنزه ضخم عابر للحدود يحمل اسم تعرجات نهر النيجر.", "h": "تأخذ الحديقة اسمها من تعرجات نهر النيجر على شكل حرف W. وهي مشتركة بين بنين والنيجر وبوركينا فاسو، وهي جزء من مجمع W-Arly-Pendjari المدرج كموقع للتراث العالمي. وهي مساحة شاسعة من السافانا والغابات المعرضة حيث تعيش الفيلة والجاموس والظباء. الوصول مقيد: من الضروري التحقق من تعليمات السلامة المعمول بها قبل السفر إلى الشمال."}, "zh": {"n": "西国家公园", "d": "巨大的跨境公园，以尼日尔河蜿蜒的河道命名。", "h": "该公园因尼日尔河W形蜿蜒而得名。它由贝宁、尼日尔和布基纳法索共享，是被列为世界遗产的 W-Arly-Pendjari 建筑群的一部分。这是一大片大草原和长廊森林，大象、水牛和羚羊生活在那里。访问受到限制：在前往北方之前，必须检查有效的安全说明。"}, "ja": {"n": "W国立公園", "d": "ニジェール川の蛇行にちなんで名付けられた巨大な国境を越えた公園。", "h": "この公園の名前は、ニジェール川の W 字型の蛇行に由来しています。ベナン、ニジェール、ブルキナファソにまたがるこの遺跡は、世界遺産に登録されている W-Arly-Pendjari 複合施設の一部です。ゾウ、バッファロー、アンテロープが生息するサバンナとギャラリーの森の広大なエリアです。立ち入りは制限されています。北部に旅行する前に、施行されている安全上の指示を確認することが重要です。"}}, "tanougou": {"fon": {"n": "Tanougou sín tɔsisa", "d": "Sin e nɔ sà sín sókan mɛ é kpo tɔsisa jɔwamɔ tɔn e ɖò Atacora sín sókan mɛ lɛ é kpo.", "h": "Ðò Pendjari sín ali ɔ jí ɔ, Tanougou sín tɔsisa ɔ nɔ j’ayǐ sín só Atacora tɔn jí ɖò akpáxwé vovo lɛ mɛ. Tɔsisa e ɖò dò é nɔ zɔ́n bɔ a nɔ fá. Fí e gletoxo ɔ nɔ kpé nukún dó wu é nɔ jiwǔ hugǎn ɖò jǐ hwenu kpo hwenu e jǐ nɔ ja gudo tlolo é kpo (juillet jɛ octobre)."}, "yo": {"n": "Tanougou Falls", "d": "Awọn omi-omi ati awọn adagun omi adayeba ni ẹsẹ ti ibiti Atacora.", "h": "Ni opopona Pendjari, Tanougou Falls ṣubu si isalẹ okuta Atacora ni awọn ipele pupọ. Awọn kekere pool faye gba o lati dara si pa. Aaye naa, ti abule ṣakoso, jẹ iyalẹnu julọ lakoko ati ni kete lẹhin akoko ojo (Keje si Oṣu Kẹwa)."}, "ha": {"n": "Tanougou Falls", "d": "Ruwan ruwa da wuraren tafki na halitta a gindin kewayon Atacora.", "h": "A kan titin Pendjari, Tanougou Falls ya faɗi ƙasan dutsen Atacora a matakai da yawa. Ƙananan tafkin yana ba ku damar kwantar da hankali. Wurin, wanda ƙauyen ke gudanarwa, ya fi ban sha'awa a lokacin da kuma bayan damina (Yuli zuwa Oktoba)."}, "sw": {"n": "Maporomoko ya Tanougou", "d": "Maporomoko ya maji na mabwawa ya asili chini ya safu ya Atacora.", "h": "Katika barabara ya Pendjari, Maporomoko ya Tanougou yanaanguka chini ya mwamba wa Atacora kwa hatua kadhaa. Bwawa la chini hukuruhusu kupoa. Tovuti, inayosimamiwa na kijiji, ni ya kuvutia zaidi wakati na baada ya msimu wa mvua (Julai hadi Oktoba)."}, "es": {"n": "Cataratas Tanougou", "d": "Cascadas y pozas naturales al pie de la sierra de Atacora.", "h": "En la carretera de Pendjari, las cataratas de Tanougou caen por el acantilado de Atacora en varias etapas. La piscina inferior te permite refrescarte. El sitio, administrado por el pueblo, es más espectacular durante y justo después de la temporada de lluvias (de julio a octubre)."}, "pt": {"n": "Cataratas de Tanougou", "d": "Cachoeiras e piscinas naturais aos pés da Serra do Atacora.", "h": "Na estrada de Pendjari, as Cataratas de Tanougou descem pela falésia de Atacora em várias etapas. A piscina inferior permite que você se refresque. O local, administrado pela aldeia, é mais espetacular durante e logo após a estação chuvosa (julho a outubro)."}, "de": {"n": "Tanougou-Wasserfälle", "d": "Wasserfälle und natürliche Becken am Fuße des Atacora-Gebirges.", "h": "Auf der Pendjari-Straße stürzen die Tanougou-Wasserfälle in mehreren Etappen die Atacora-Klippe hinab. Im unteren Becken können Sie sich abkühlen. Der vom Dorf verwaltete Ort ist während und kurz nach der Regenzeit (Juli bis Oktober) am spektakulärsten."}, "it": {"n": "Cascate di Tanougou", "d": "Cascate e piscine naturali ai piedi della catena dell'Atacora.", "h": "Sulla strada Pendjari, le cascate Tanougou precipitano lungo la scogliera di Atacora in più fasi. La piscina inferiore consente di rinfrescarsi. Il sito, gestito dal villaggio, è particolarmente spettacolare durante e subito dopo la stagione delle piogge (da luglio a ottobre)."}, "nl": {"n": "Tanougou-watervallen", "d": "Watervallen en natuurlijke poelen aan de voet van het Atacora-gebergte.", "h": "Op de Pendjari-weg storten de Tanougou-watervallen in verschillende fasen van de Atacora-klif naar beneden. In het lager gelegen zwembad kunt u heerlijk afkoelen. De camping, beheerd door het dorp, is het meest spectaculair tijdens en net na het regenseizoen (juli tot oktober)."}, "ru": {"n": "Водопад Танугу", "d": "Водопады и природные бассейны у подножия хребта Атакора.", "h": "На дороге Пенджари водопад Танугу в несколько этапов падает со скалы Атакора. Нижний бассейн позволяет освежиться. Это место, находящееся под управлением деревни, наиболее впечатляюще выглядит во время и сразу после сезона дождей (с июля по октябрь)."}, "ar": {"n": "شلالات تانوجو", "d": "الشلالات والمسابح الطبيعية عند سفح سلسلة جبال أتاكورا.", "h": "على طريق بنجاري، تنحدر شلالات تانوغو أسفل منحدر أتاكورا على عدة مراحل. يسمح لك المسبح السفلي بالتهدئة. الموقع، الذي تديره القرية، هو الأكثر روعة أثناء وبعد موسم الأمطار مباشرة (يوليو إلى أكتوبر)."}, "zh": {"n": "塔努沟瀑布", "d": "阿塔科拉山脉脚下的瀑布和天然泳池。", "h": "在彭贾里 (Pendjari) 路上，塔努古瀑布 (Tanougou Falls) 分几个阶段从阿塔科拉悬崖上倾泻而下。下层的泳池可以让你清凉一下。该遗址由村庄管理，在雨季（七月至十月）期间和雨季过后最为壮观。"}, "ja": {"n": "タノゴウ滝", "d": "アタコラ山脈の麓にある滝と天然のプール。", "h": "ペンジャリ道路では、タヌグ滝がアタコラの崖を数段階に分けて流れ落ちます。下のプールでは涼むことができます。村が管理するこの場所は、雨季（7 月から 10 月）の間とその直後が最も壮観です。"}}, "kota": {"fon": {"n": "Kota sín tɔsisa", "d": "Cascade dans un cirque rocheux vert, proche de Natitingou.", "h": "Kilomɛtlu wǒ-atɔ́ɔ́n mɔ̌ dó Natitingou ɔ, tɔsisa Kota tɔn nɔ jɛ xɔ e mɛ è nɔ xò sókan mɛ ɖè bɔ atín lɛ nɔ gɔ́ é ɖé mɛ. Ali ɖé nɔ kplá mɛ yì tɔsisa ɔ kɔn. É nyí tomɛyiyi e bɔkun bɔ xwédo lɛ yí wǎn na é ɖé, bo nyɔ́ tawun ɖò jǐ hwenu sín vivɔnu."}, "yo": {"n": "Kota Falls", "d": "Isosile omi ni agbegbe apata alawọ ewe, nitosi Natitingou.", "h": "Nǹkan bí kìlómítà mẹ́ẹ̀ẹ́dógún sí Natitingou, ìsun omi Kota bọ́ sí ibi eré amphitheatre ti àwọn àpáta tí ewéko bo. A ona nyorisi si awọn pool. O jẹ irin-ajo irọrun ti o gbajumọ pẹlu awọn idile, apẹrẹ ni opin akoko ojo."}, "ha": {"n": "Kota Falls", "d": "Ruwa a cikin wani koren dutsen cirque, kusa da Natitingou.", "h": "Kimanin kilomita goma sha biyar daga Natitingou, magudanar ruwa ta Kota ta fada cikin wani gidan wasan kwaikwayo na dutse wanda aka lullube da ciyayi. Hanya tana kaiwa zuwa tafkin. Yawon shakatawa ne mai sauƙi wanda ya shahara tare da iyalai, manufa a ƙarshen lokacin damina."}, "sw": {"n": "Maporomoko ya Kota", "d": "Maporomoko ya maji katika miamba ya kijani kibichi, karibu na Natitingou.", "h": "Takriban kilomita kumi na tano kutoka Natitingou, maporomoko ya maji ya Kota huanguka kwenye ukumbi wa michezo wa miamba iliyofunikwa na mimea. Njia inaongoza kwenye bwawa. Ni safari rahisi inayopendwa na familia, inayofaa mwishoni mwa msimu wa mvua."}, "es": {"n": "Cataratas de Kota", "d": "Cascada en un circo rocoso verde, cerca de Natitingou.", "h": "A unos quince kilómetros de Natitingou, la cascada de Kota cae en un anfiteatro de rocas cubiertas de vegetación. Un camino conduce a la piscina. Es una excursión sencilla popular entre las familias, ideal al final de la temporada de lluvias."}, "pt": {"n": "Cataratas de Kota", "d": "Cachoeira num circo rochoso verde, perto de Natitingou.", "h": "A cerca de quinze quilômetros de Natitingou, a cachoeira Kota cai em um anfiteatro de rochas cobertas de vegetação. Um caminho leva à piscina. É uma excursão fácil e popular entre as famílias, ideal no final da estação chuvosa."}, "de": {"n": "Kota-Wasserfälle", "d": "Wasserfall in einem grünen Felskessel in der Nähe von Natitingou.", "h": "Etwa fünfzehn Kilometer von Natitingou entfernt stürzt der Kota-Wasserfall in ein Amphitheater aus mit Vegetation bedeckten Felsen. Ein Weg führt zum Pool. Es ist ein einfacher Ausflug, der bei Familien beliebt ist und sich ideal am Ende der Regenzeit eignet."}, "it": {"n": "Cascate di Kota", "d": "Cascata in un circo roccioso verde, vicino a Natitingou.", "h": "A una quindicina di chilometri da Natitingou, la cascata Kota cade in un anfiteatro di rocce ricoperte di vegetazione. Un sentiero conduce alla piscina. Si tratta di un'escursione facile, frequentata dalle famiglie, ideale alla fine della stagione delle piogge."}, "nl": {"n": "Kota-watervallen", "d": "Waterval in een groen rotsachtig keteldal, vlakbij Natitingou.", "h": "Ongeveer vijftien kilometer van Natitingou valt de Kota-waterval in een amfitheater van rotsen bedekt met vegetatie. Een pad leidt naar het zwembad. Het is een gemakkelijke excursie die populair is bij gezinnen, ideaal aan het einde van het regenseizoen."}, "ru": {"n": "Кота-Фолс", "d": "Водопад в зеленом скалистом цирке недалеко от Натитингу.", "h": "Примерно в пятнадцати километрах от Натитингу водопад Кота впадает в амфитеатр скал, покрытых растительностью. Дорожка ведет к бассейну. Это легкая экскурсия, популярная среди семей и идеальная в конце сезона дождей."}, "ar": {"n": "شلالات كوتا", "d": "شلال في دائرة صخرية خضراء، بالقرب من ناتيتينغو.", "h": "على بعد حوالي خمسة عشر كيلومترًا من ناتيتنغو، يقع شلال كوتا في مدرج من الصخور المغطاة بالنباتات. طريق يؤدي إلى حمام السباحة. إنها رحلة سهلة تحظى بشعبية لدى العائلات، وهي مثالية في نهاية موسم الأمطار."}, "zh": {"n": "哥打瀑布", "d": "纳蒂廷古附近绿色岩石冰斗中的瀑布。", "h": "科塔瀑布距离纳蒂廷古约 15 公里，落入一个长满植被的岩石圆形剧场。一条小路通向水池。这是一次深受家庭欢迎的轻松旅行，是雨季结束时的理想选择。"}, "ja": {"n": "コタの滝", "d": "ナティティンゴー近くの緑の岩のカールにある滝。", "h": "ナティティンゴーから約 15 キロメートル離れたコタの滝は、植物に覆われた岩の円形競技場に落ちます。小道がプールに続いています。梅雨明けにぴったりの、家族連れに人気の気軽な小旅行です。"}}, "tata": {"fon": {"n": "Tata Somba gosin Otamali to mɛ", "d": "Xwé e è sɔ́ kɔ́ dó bló bɔ ye ɖó xɔta wè lɛ é, ee nyí xɔgbigbázɔ́ ɖagbeɖagbe e è bló ɖò aca mɛ lɛ é.", "h": "Otammari (alǒ Betammaribé) lɛ nɔ gbá tata, xɔ e è sɔ́ kɔ́ dó bló bɔ ye ɖó xɔta wè lɛ é, bɔ è nɔ sɔ́ zunkan dó bló xɔ ɖaxó ɖaxó lɛ na. Kanlin lɛ nɔ nɔ xɔ e ɖò dò é mɛ, bɔ xwédo ɔ kpo xɔta lɛ kpo nɔ nɔ xɔ e ɖò aga é mɛ; xɔgbigbá nɔ xlɛ́ linlin e è ɖó dó gbɛ̀ ɔ wu é kpo kancica e ɖò ye kpo tɔ́gbó lɛ kpo tɛntin é kpo. Ðò dogbó ɔ sín akpá ɖevo xwé ɔ, è sɔ́ Koutammakou Togo tɔn, ee nyí aca ɖokpo ɔ é dó wema mɛ ɖɔ é nyí nǔɖokan gbɛ̀ ɔ tɔn ɖé sín 2004. A sixu yì ba kpɔ́n bo lɛ́ dɔ́ tata ɖé mɛ hweɖelɛnu bo lɛlɛ̌ dó Boukoumbé."}, "yo": {"n": "Tata Somba lati Otammari orilẹ-ede", "d": "Awọn ile olodi alaja meji, awọn iṣẹ-ọnà ti faaji ibile.", "h": "Awọn Otammari (tabi Betammaribé) kọ tata, awọn ile mudcastle ipele meji, pẹlu awọn turrets dofun pẹlu thatch. Ilẹ pakà ile awọn ẹran-ọsin, oke pakà ebi ati awọn oke aja; faaji ṣe afihan ero inu agbaye ati awọn ọna asopọ pẹlu awọn baba. Ni apa keji ti aala, Koutammakou Togo, aṣa kanna, ni a ti ṣe atokọ bi aaye ohun-ini agbaye lati ọdun 2004. O le ṣabẹwo ati nigbakan sun ni tata ni ayika Boukoumbé."}, "ha": {"n": "Tata Somba daga kasar Otammari", "d": "Gidajen katangar ƙasa mai hawa biyu, ƙwararrun gine-ginen gargajiya.", "h": "Otammari (ko Betammaribé) yana gina tata, gidaje na laka mai hawa biyu, tare da tururuwa sama da itace. Gidan da ke ƙasa yana ɗauke da dabbobi, bene na sama na iyali da kuma ɗakuna; Gine-gine yana nuna tunanin duniya da alaƙa da kakanni. A wani gefen iyakar, Koutammakou na Togo, al'ada iri ɗaya, an jera shi a matsayin wurin tarihi na duniya tun daga 2004. Kuna iya ziyarta kuma a wasu lokuta kuna kwana a cikin tata kusa da Boukoumbé."}, "sw": {"n": "Tata Somba kutoka nchi ya Otammari", "d": "Nyumba za ngome za udongo za hadithi mbili, kazi bora za usanifu wa jadi.", "h": "Otammari (au Betammaribé) hujenga tata, nyumba za ngazi mbili za tope, na turrets zilizowekwa nyasi. Ghorofa ya chini huweka mifugo, ghorofa ya juu familia na attics; usanifu huonyesha dhana ya ulimwengu na viungo na mababu. Kwa upande mwingine wa mpaka, Togolese Koutammakou, utamaduni huo huo, umeorodheshwa kama tovuti ya urithi wa dunia tangu 2004. Unaweza kutembelea na wakati mwingine kulala katika tata karibu na Boukoumbé."}, "es": {"n": "Tata Somba del país de Otammari", "d": "Casas fortaleza de barro de dos pisos, obras maestras de la arquitectura tradicional.", "h": "Los Otammari (o Betammaribé) construyen tata, casas de adobe de dos niveles, con torreones rematados con techo de paja. La planta baja alberga el ganado, la superior la familia y las buhardillas; la arquitectura refleja una concepción del mundo y vínculos con los antepasados. Al otro lado de la frontera, el togolés Koutammakou, la misma cultura, está catalogado como patrimonio de la humanidad desde 2004. Se puede visitar y, a veces, dormir en un tata alrededor de Boukoumbé."}, "pt": {"n": "Tata Somba do país Otammari", "d": "Casas-fortalezas de barro de dois andares, obras-primas da arquitetura tradicional.", "h": "Os Otammari (ou Betammaribé) constroem tata, casas de barro de dois níveis, com torres cobertas de palha. O rés-do-chão alberga o gado, o piso superior a família e os sótãos; a arquitetura reflete uma concepção de mundo e se liga aos ancestrais. Do outro lado da fronteira, o togolês Koutammakou, a mesma cultura, está listado como patrimônio mundial desde 2004. Você pode visitar e às vezes dormir em uma tata nos arredores de Boukoumbé."}, "de": {"n": "Tata Somba aus dem Otammari-Land", "d": "Zweistöckige Festungshäuser aus Lehm, Meisterwerke traditioneller Architektur.", "h": "Die Otammari (oder Betammaribé) bauen Tata, zweistöckige Lehmburghäuser mit reetgedeckten Türmchen. Im Erdgeschoss ist das Vieh untergebracht, im Obergeschoss die Familie und die Dachböden; Architektur spiegelt ein Weltbild wider und verbindet sich mit den Vorfahren. Auf der anderen Seite der Grenze steht das togolesische Koutammakou, dessen Kultur seit 2004 zum Weltkulturerbe gehört. Sie können Boukoumbé besuchen und manchmal auch in einem Tata übernachten."}, "it": {"n": "Tata Somba del paese di Otammari", "d": "Case fortezza di terra a due piani, capolavori dell'architettura tradizionale.", "h": "Gli Otammari (o Betammaribé) costruiscono tata, case in castelli di fango a due livelli, con torrette sormontate da paglia. Il piano terra ospita il bestiame, il piano superiore la famiglia e le soffitte; l'architettura riflette una concezione del mondo e legami con gli antenati. Dall'altra parte del confine, il togolese Koutammakou, la stessa cultura, è stato dichiarato patrimonio dell'umanità dal 2004. È possibile visitare e talvolta dormire in un tata nei dintorni di Boukoumbé."}, "nl": {"n": "Tata Somba uit het land Otammari", "d": "Aarden vestinghuizen van twee verdiepingen, meesterwerken van traditionele architectuur.", "h": "De Otammari (of Betammaribé) bouwen tata, lemen huizen van twee verdiepingen, met torentjes bedekt met riet. Op de begane grond bevindt zich het vee, op de bovenverdieping het gezin en de zolders; architectuur weerspiegelt een opvatting van de wereld en banden met voorouders. Aan de andere kant van de grens staat het Togolese Koutammakou, dezelfde cultuur, sinds 2004 op de werelderfgoedlijst. Rondom Boukoumbé kun je een tata bezoeken en soms slapen in een tata."}, "ru": {"n": "Тата Сомба из страны Отаммари", "d": "Двухэтажные земляные дома-крепости, шедевры традиционной архитектуры.", "h": "Отаммари (или Бетаммарибе) строят тата, двухуровневые глинобитные дома с башенками, покрытыми соломой. На первом этаже находится домашний скот, на верхнем — семья и чердаки; архитектура отражает мировоззрение и связь с предками. По другую сторону границы находится тоголезский Кутаммаку, представитель той же культуры, с 2004 года внесен в список объектов всемирного наследия. Вы можете посетить и иногда переночевать в татах вокруг Букумбе."}, "ar": {"n": "تاتا سومبا من بلاد أوتاماري", "d": "منازل حصن ترابية مكونة من طابقين، من روائع الهندسة المعمارية التقليدية.", "h": "يقوم الأوتاماري (أو البيتاماريبي) ببناء منازل من قلاع طينية مكونة من طابقين، مع أبراج تعلوها القش. الطابق الأرضي يضم الماشية والطابق العلوي الأسرة والسندرات. تعكس الهندسة المعمارية تصورًا للعالم وروابط مع الأسلاف. على الجانب الآخر من الحدود، تم إدراج مدينة كوتاماكو التوغولية، ذات الثقافة نفسها، كموقع للتراث العالمي منذ عام 2004. يمكنك الزيارة والنوم أحيانًا في منطقة تاتا حول بوكومبي."}, "zh": {"n": "来自 Otammari 国家的 Tata Somba", "d": "二层土楼碉楼，传统建筑的杰作。", "h": "Otammari（或 Betammaribé）建造塔塔式两层泥堡房屋，塔楼顶部铺有茅草。底层饲养牲畜，上层饲养家人和阁楼。建筑反映了一种世界观以及与祖先的联系。在边境的另一边，多哥的库塔玛库（Koutammakou），同样的文化，自 2004 年起就被列为世界遗产。您可以参观布库姆贝周围的塔塔，有时还可以睡在塔塔里。"}, "ja": {"n": "オタンマリ国のタタ・ソンバ", "d": "伝統建築の傑作、二階建ての土塁住宅。", "h": "オタンマリ (またはベタマリベ) は、茅葺きの塔を備えた 2 階建ての泥城の家、タタを建てます。 1階には家畜が住み、2階には家族と屋根裏部屋があります。建築は世界の概念と祖先とのつながりを反映しています。国境の反対側には、同じ文化を持つトーゴのコウタンマコウが 2004 年に世界遺産に登録されています。ブークンベ周辺を訪れることができ、場合によってはタタで寝ることもできます。"}}, "natitingou": {"fon": {"n": "Natitingou Tokpɔn ɔ sín Nǔxɔsa", "d": "Tata kpɔ́ndéwú lɛ, nǔ lɛ kpo nǔwiwa togun Atacora tɔn lɛ tɔn kpo.", "h": "É ɖò xɔ e è gbá ɖò acɛkpikpa glɔ é ɖé mɛ, bɔ xɔ e mɛ è nɔ hɛn nǔ xóxó lɛ ɖó é xlɛ́ fí e è nɔ nɔ ɖò tofɔligbé-zǎnzǎnhweji é, bo ɖó tata somba sín kpɔ́ndéwú lɛ, gɔ́ nú nǔxixo sín nǔ lɛ, acɔ́nú lɛ kpo nǔwiwa e mɛ e ɖò Atacora lɛ é nɔ bló ɖò bǐbɛ̌mɛ lɛ é kpo. Afɔ e hɛn lè wá é ɖé cobɔ è na yì ba gletoxo lɛ kpɔ́n."}, "yo": {"n": "Natitingou Regional Museum", "d": "Awọn awoṣe Tata, awọn nkan ati awọn ilana ti awọn eniyan Atacora.", "h": "Ti o wa ni ile ti ileto, ile musiọmu n ṣafihan ibugbe ibile ti ariwa iwọ-oorun, pẹlu awọn awoṣe ti tata somba, ati awọn ohun elo, awọn ohun ọṣọ ati awọn ilana ipilẹṣẹ ti awọn eniyan Atacora. Igbesẹ ti o wulo ṣaaju lilọ si awọn abule."}, "ha": {"n": "Natitingou Regional Museum", "d": "Samfuran Tata, abubuwa da al'adun mutanen Atacora.", "h": "Gidan da aka gina a cikin wani gini na mulkin mallaka, gidan kayan gargajiya yana gabatar da al'adun gargajiya na arewa maso yamma, tare da samfurori na tata somba, da kuma kayan aiki, kayan ado da kuma bikin kaddamar da mutanen Atacora. Mataki mai amfani kafin zuwa ziyarci ƙauyuka."}, "sw": {"n": "Makumbusho ya Mkoa wa Natitingou", "d": "Mifano ya Tata, vitu na ibada za watu wa Atacora.", "h": "Imejengwa katika jengo la kikoloni, jumba la kumbukumbu linaonyesha makazi ya jadi ya kaskazini-magharibi, na mifano ya tata somba, pamoja na vyombo, mapambo na ibada za kuanzishwa kwa watu wa Atacora. Hatua muhimu kabla ya kutembelea vijiji."}, "es": {"n": "Museo Regional de Natitingou", "d": "Modelos de tata, objetos y ritos de los pueblos de Atacora.", "h": "Ubicado en un edificio colonial, el museo presenta el hábitat tradicional del noroeste, con modelos de tata somba, así como los instrumentos, ornamentos y ritos iniciáticos de los pueblos de Atacora. Un paso útil antes de ir a visitar los pueblos."}, "pt": {"n": "Museu Regional de Natitingou", "d": "Modelos Tata, objetos e ritos dos povos de Atacora.", "h": "Instalado em um prédio colonial, o museu apresenta o habitat tradicional do noroeste, com maquetes de tata somba, além de instrumentos, ornamentos e ritos de iniciação dos povos atacora. Um passo útil antes de visitar as aldeias."}, "de": {"n": "Regionalmuseum Natitingou", "d": "Tata-Modelle, Objekte und Riten der Völker von Atacora.", "h": "Das in einem Kolonialgebäude untergebrachte Museum präsentiert den traditionellen Lebensraum des Nordwestens mit Modellen der Tata Somba sowie den Instrumenten, Ornamenten und Initiationsriten der Völker von Atacora. Ein nützlicher Schritt, bevor Sie die Dörfer besuchen."}, "it": {"n": "Museo Regionale di Natitingou", "d": "Modelli Tata, oggetti e riti dei popoli di Atacora.", "h": "Ospitato in un edificio coloniale, il museo presenta l'habitat tradizionale del nord-ovest, con modelli di tata somba, oltre a strumenti, ornamenti e riti di iniziazione dei popoli di Atacora. Una tappa utile prima di andare a visitare i borghi."}, "nl": {"n": "Regionaal Museum Natitingou", "d": "Tata-modellen, voorwerpen en rituelen van de volkeren van Atacora.", "h": "Het museum, gehuisvest in een koloniaal gebouw, presenteert de traditionele habitat van het noordwesten, met modellen van tata somba, evenals de instrumenten, ornamenten en initiatierituelen van de volkeren van Atacora. Een nuttige stap voordat u de dorpen gaat bezoeken."}, "ru": {"n": "Региональный музей Натитингу", "d": "Модели тата, предметы и обряды народов Атакоры.", "h": "Размещенный в колониальном здании, музей представляет традиционную среду обитания северо-запада с моделями тата-сомбы, а также инструменты, украшения и обряды инициации народа Атакора. Полезный шаг перед поездкой в ​​деревни."}, "ar": {"n": "متحف ناتيتنغو الإقليمي", "d": "نماذج تاتا وأشياء وطقوس شعوب أتاكورا.", "h": "يقع المتحف في مبنى استعماري، ويعرض الموطن التقليدي للشمال الغربي، مع نماذج من تاتا سومبا، بالإضافة إلى الأدوات والزخارف وطقوس البدء لشعوب أتاكورا. خطوة مفيدة قبل الذهاب لزيارة القرى."}, "zh": {"n": "纳蒂廷古地区博物馆", "d": "塔塔模型、阿塔科拉人民的物品和仪式。", "h": "博物馆坐落在一座殖民时期的建筑内，展示了西北地区的传统栖息地，展示了塔塔松巴的模型以及阿塔科拉人民的乐器、装饰品和入会仪式。在去参观村庄之前这是一个有用的步骤。"}, "ja": {"n": "ナティティンゴー地方博物館", "d": "アタコラの人々のタタの模型、物品、儀式。", "h": "植民地時代の建物内にあるこの博物館には、タタ ソンバの模型のほか、アタコラの人々の楽器、装飾品、入会儀式など、北西部の伝統的な生息地が展示されています。村を訪れる前に便利なステップです。"}}, "taneka": {"fon": {"n": "Taneka Gletoxo lɛ", "d": "Gletoxo e ɖò te bo ɖó xɔ kpɛví kpɛví e è sɔ́ zunkɔ́ dó bló na lɛ é, mɛ e nɔ cɔ́ aca hwexónu tɔn lɛ é.", "h": "Gletoxo Taneka-Koko kpo Taneka-Béri kpo tɔn lɛ tɛ́ dó só ɖé sín akpáxwé e sɛkpɔ Copargo lɛ é wu, bo kpó ɖò xɔ kpɛví kpɛví e è sɔ́ kɔ́ dó bló lɛ é kpo xɔta yetɔn e cí kɔ́ ɖɔhun lɛ é kpo ɖó wɛ. È tuùn ye ɖó vɔsanúxwlémawutɔ́ yetɔn lɛ wu, bo nɔ dó gbɔ̌nyú, bo nɔ lɛ́ tuùn sinsɛn kpo tutoblonunu gbɛ̌ta tɔn kpo e ko lín tawun é ɖé. È nɔ bló mɛbakpɔ́n ɔ kpo alixlɛ́mɛtɔ́ gletoxo ɔ tɔn ɖé kpo, bo nɔ ɖó sísí nú fí mímɛ́ lɛ."}, "yo": {"n": "Awọn abule Taneka", "d": "Awọn abule ti o wa pẹlu awọn ile kekere ti o ni yika, awọn alabojuto ti aṣa atijọ.", "h": "Ni ibamu si awọn ẹgbẹ ti oke kan nitosi Copargo, awọn abule Taneka-Koko ati Taneka-Béri ti ni awọn ile alamọda yika ati awọn orule conical. Wọn jẹ olokiki fun awọn alufaa wọn, ti a wọ ni awọ ewurẹ, ati fun eto ẹsin ati awujọ ti atijọ pupọ. Ibẹwo naa jẹ pẹlu itọsọna abule kan, ti o bọwọ fun awọn ibi mimọ."}, "ha": {"n": "Kauyukan Taneka", "d": "Ƙauyen da ke da ƙauyuka masu zagaye da bukkoki, masu kula da al'adun gargajiya.", "h": "Da yake manne da gefen wani tudu da ke kusa da Copargo, ƙauyukan Taneka-Koko da Taneka-Béri sun ci gaba da riƙe bukkokinsu na ƙasa na ƙasa da kuma rufin rufin. An san su da limaman cocinsu, sanye da fatun akuya, kuma ga wani tsohon tsarin addini da zamantakewa. Ana yin ziyarar ne tare da jagorar ƙauye, girmama wurare masu tsarki."}, "sw": {"n": "Vijiji vya Taneka", "d": "Vijiji vilivyowekwa na vibanda vya nyasi vya pande zote, walezi wa mila za kale.", "h": "Kwa kushikilia kando ya kilima karibu na Copargo, vijiji vya Taneka-Koko na Taneka-Béri vimehifadhi vibanda vyao vya udongo na paa za koni. Wanajulikana kwa makuhani wao, wamevaa ngozi za mbuzi, na kwa mfumo wa kale sana wa kidini na kijamii. Ziara hiyo inafanywa na mwongozo wa kijiji, kuheshimu maeneo matakatifu."}, "es": {"n": "Pueblos Taneka", "d": "Pueblos encaramados con chozas redondas con techo de paja, guardianes de antiguas tradiciones.", "h": "Aferradas a las laderas de una colina cerca de Copargo, las aldeas Taneka-Koko y Taneka-Béri han conservado sus chozas redondas de barro y sus techos cónicos. Son conocidos por sus sacerdotes, vestidos con pieles de cabra, y por un sistema religioso y social muy antiguo. La visita se realiza con un guía del pueblo, respetando los lugares sagrados."}, "pt": {"n": "Aldeias Taneka", "d": "Aldeias empoleiradas com cabanas redondas de colmo, guardiãs de tradições antigas.", "h": "Agarradas às encostas de uma colina perto de Copargo, as aldeias Taneka-Koko e Taneka-Béri mantiveram as suas cabanas redondas de barro e telhados cónicos. São conhecidos pelos seus sacerdotes, vestidos com peles de cabra, e por um sistema religioso e social muito antigo. A visita é feita com guia da aldeia, respeitando os locais sagrados."}, "de": {"n": "Taneka-Dörfer", "d": "Hochgelegene Dörfer mit runden strohgedeckten Hütten, Hüter alter Traditionen.", "h": "Die Dörfer Taneka-Koko und Taneka-Béri liegen an den Hängen eines Hügels in der Nähe von Copargo und haben ihre runden Erdhütten und konischen Dächer bewahrt. Sie sind bekannt für ihre in Ziegenfelle gekleideten Priester und für ein sehr altes religiöses und soziales System. Der Besuch erfolgt mit einem Dorfführer unter Berücksichtigung heiliger Orte."}, "it": {"n": "Villaggi Taneka", "d": "Villaggi arroccati con capanne rotonde dal tetto di paglia, custodi di antiche tradizioni.", "h": "Aggrappati ai fianchi di una collina vicino a Copargo, i villaggi Taneka-Koko e Taneka-Béri hanno conservato le loro capanne rotonde di terra e i tetti conici. Sono conosciuti per i loro sacerdoti, vestiti di pelli di capra, e per un sistema religioso e sociale molto antico. La visita viene effettuata con guida del villaggio, nel rispetto dei luoghi sacri."}, "nl": {"n": "Taneka-dorpen", "d": "Hooggelegen dorpen met ronde rieten hutten, bewakers van eeuwenoude tradities.", "h": "De dorpen Taneka-Koko en Taneka-Béri, die zich vastklampen aan de zijkanten van een heuvel nabij Copargo, hebben hun ronde aarden hutten en kegelvormige daken behouden. Ze staan ​​bekend om hun priesters, gekleed in geitenvellen, en om een ​​heel oud religieus en sociaal systeem. Het bezoek wordt gedaan met een dorpsgids, waarbij heilige plaatsen worden gerespecteerd."}, "ru": {"n": "Деревни Танека", "d": "Высокие деревни с круглыми соломенными хижинами, хранителями древних традиций.", "h": "Деревни Танека-Коко и Танека-Бери, расположенные на склонах холма недалеко от Копарго, сохранили свои круглые земляные хижины и конические крыши. Они известны своими священниками, одетыми в козьи шкуры, и очень древней религиозной и социальной системой. Посещение осуществляется в сопровождении деревенского гида, уважающего священные места."}, "ar": {"n": "قرى تانيكا", "d": "قرى جاثمة ذات أكواخ مستديرة من القش، تحمي التقاليد القديمة.", "h": "احتفظت قريتا تانيكا-كوكو وتانيكا-بيري، المتشبتان بجوانب تل بالقرب من كوبارجو، بأكواخهما الترابية المستديرة وأسقفهما المخروطية. وهم معروفون بكهنتهم الذين يرتدون جلود الماعز، وبنظام ديني واجتماعي قديم جدًا. تتم الزيارة مع مرشد القرية، واحترام الأماكن المقدسة."}, "zh": {"n": "种卡村", "d": "栖息着圆形茅草屋的村庄，是古老传统的守护者。", "h": "塔内卡-科科 (Taneka-Koko) 和塔内卡-贝里 (Taneka-Béri) 村庄紧邻科帕戈 (Copargo) 附近的山坡，保留了圆形土屋和圆锥形屋顶。他们以穿着山羊皮的牧师以及非常古老的宗教和社会制度而闻名。这次参观是在乡村导游的带领下完成的，尊重圣地。"}, "ja": {"n": "タネカの村", "d": "丸い茅葺き小屋のある高台の村は、古代の伝統の守護者です。", "h": "コパルゴ近くの丘の側面にしがみつくタネカ ココ村とタネカ ベリ村は、丸い土の小屋と円錐形の屋根を残しています。彼らはヤギの皮を着た司祭と、非常に古い宗教的および社会的システムで知られています。訪問は神聖な場所を尊重し、村のガイドと一緒に行われます。"}}, "nikki": {"fon": {"n": "Nikki, axɔsuxɔsa kpo Gaani sín xwè kpo", "d": "Baatombu sín toxo ɖaxó hwexónu tɔn, ee gbakpé ɖó sɔ́xátɔ́ Gaani tɔn lɛ wu é.", "h": "Nikki wɛ nyí axɔsuɖuto baatonu (bariba) tɔn sín vǐ, bɔ sɔ́xátɔ́ wasangari tɔn lɛ ɖó ayǐ sɔgbe xá aca. Xwewu xwewu ɔ, xwè Gaani tɔn e sín azǎn nɔ xwedó sunzanwema ɔ é nɔ kplé sɔ́xátɔ́ afatɔ́n mɔkpan e dó nǔwiwa sín awu lɛ é bo nɔ lɛlɛ̌ dó axɔsu ɔ bo nɔ bló nǔwiwa jiwǔ ɖé. È sixu yì ba axɔsu ɔ sín hɔnmɛ kpo nǔ e è nɔ hɛn ɖ’ayǐ ɖò Gaani lɛ é kpo kpɔ́n ɖò xwè ɔ bǐ mɛ."}, "yo": {"n": "Nikki, ọba aafin ati Gaani Festival", "d": "Olu-ilu itan ti Baatombu, olokiki fun awọn ẹlẹṣin Gaani rẹ.", "h": "Nikki ni ijoko ti ijọba baatonu (bariba), ti a da ni ibamu si aṣa nipasẹ awọn ẹlẹṣin wasangari. Lọ́dọọdún, àjọyọ̀ Gaani, ọjọ́ tí ó tẹ̀ lé kàlẹ́ńdà òṣùpá, máa ń kó ẹgbẹẹgbẹ̀rún àwọn ẹlẹ́ṣin jọpọ̀ tí wọ́n wọ aṣọ ayẹyẹ yí ọba ká fún ìtòlẹ́sẹẹsẹ àrà ọ̀tọ̀ kan. Ile ọba ati ile musiọmu Gaani le ṣe abẹwo si gbogbo ọdun yika."}, "ha": {"n": "Nikki, gidan sarauta da bikin Gaani", "d": "Babban birnin tarihi na Baatombu, sanannen mahaya Gaani.", "h": "Nikki shi ne shimfiɗar jariri na masarautar baatonu (bariba), wanda aka kafa bisa al'ada ta maharan wasangari. A duk shekara, bikin Gaani, wanda kwanan watan ya biyo bayan kalandar wata, yakan tattaro dubban mahaya dawakai sanye da kayan shagulgula a kewayen sarki domin yin faretin ban mamaki. Ana iya ziyartar gidan sarauta da gidan tarihi na Gaani duk shekara."}, "sw": {"n": "Nikki, jumba la kifalme na tamasha la Gaani", "d": "Mji mkuu wa kihistoria wa Baatombu, maarufu kwa wapanda farasi wake wa Gaani.", "h": "Nikki ndiye chimbuko la ufalme wa baatonu (bariba), ulioanzishwa kulingana na mapokeo na wapanda farasi wa wasangari. Kila mwaka, tamasha la Gaani, tarehe ambayo inafuata kalenda ya mwezi, huleta pamoja maelfu ya wapanda farasi katika mavazi ya sherehe karibu na mfalme kwa gwaride la kuvutia. Jumba la kifalme na jumba la kumbukumbu la Gaani linaweza kutembelewa mwaka mzima."}, "es": {"n": "Nikki, palacio real y festival Gaani", "d": "Capital histórica de Baatombu, famosa por sus jinetes Gaani.", "h": "Nikki es la cuna del reino baatonu (bariba), fundado según la tradición por jinetes wasangari. Cada año, el festival Gaani, cuya fecha sigue el calendario lunar, reúne a miles de jinetes con trajes ceremoniales alrededor del rey para un desfile espectacular. El palacio real y el museo Gaani se pueden visitar durante todo el año."}, "pt": {"n": "Nikki, palácio real e festival Gaani", "d": "Capital histórica do Baatombu, famosa pelos seus cavaleiros Gaani.", "h": "Nikki é o berço do reino baatonu (bariba), fundado segundo a tradição por cavaleiros wasangari. Todos os anos, o festival Gaani, cuja data segue o calendário lunar, reúne milhares de cavaleiros em trajes cerimoniais em torno do rei para um desfile espetacular. O palácio real e o museu Gaani podem ser visitados durante todo o ano."}, "de": {"n": "Nikki, Königspalast und Gaani-Fest", "d": "Historische Hauptstadt des Baatombu, berühmt für seine Gaani-Reiter.", "h": "Nikki ist die Wiege des Königreichs Baatonu (Bariba), das der Überlieferung nach von Wasangari-Reitern gegründet wurde. Jedes Jahr versammelt das Gaani-Fest, dessen Datum dem Mondkalender folgt, Tausende von Reitern in zeremonieller Kleidung um den König zu einer spektakulären Parade. Der Königspalast und das Gaani-Museum können das ganze Jahr über besichtigt werden."}, "it": {"n": "Nikki, palazzo reale e festival Gaani", "d": "Capitale storica del Baatombu, famosa per i suoi cavalieri Gaani.", "h": "Nikki è la culla del regno baatonu (bariba), fondato secondo la tradizione dai cavalieri wasangari. Ogni anno, il festival Gaani, la cui data segue il calendario lunare, riunisce migliaia di cavalieri in abiti cerimoniali attorno al re per una parata spettacolare. Il palazzo reale e il museo Gaani sono visitabili tutto l'anno."}, "nl": {"n": "Nikki, koninklijk paleis en Gaani-festival", "d": "Historische hoofdstad van de Baatombu, beroemd om zijn Gaani-rijders.", "h": "Nikki is de bakermat van het baatonu (bariba) koninkrijk, volgens de traditie gesticht door wasangari-ruiters. Elk jaar brengt het Gaani-festival, waarvan de datum volgt op de maankalender, duizenden ruiters in ceremoniële kledij rond de koning samen voor een spectaculaire parade. Het koninklijk paleis en het Gaani museum zijn het hele jaar door te bezoeken."}, "ru": {"n": "Никки, королевский дворец и фестиваль Гаани", "d": "Историческая столица Баатомбу, известная своими наездниками Гаани.", "h": "Никки — колыбель королевства баатону (бариба), основанного по традиции всадниками васангари. Ежегодно фестиваль Гаани, дата которого соответствует лунному календарю, собирает тысячи всадников в церемониальных одеждах вокруг короля для зрелищного парада. Королевский дворец и музей Гаани можно посещать круглый год."}, "ar": {"n": "نيكي والقصر الملكي ومهرجان جاني", "d": "العاصمة التاريخية لباتومبو، المشهورة بفرسانها الجاني.", "h": "نيكي هي مهد مملكة باتونو (باريبا)، التي أسسها فرسان الواسانغاري وفقًا للتقاليد. في كل عام، يجمع مهرجان جاني، الذي يتبع تاريخه التقويم القمري، آلاف الفرسان بملابس احتفالية حول الملك في عرض مذهل. يمكن زيارة القصر الملكي ومتحف جاني على مدار السنة."}, "zh": {"n": "Nikki、王宫和 Gaani 节", "d": "巴通布的历史首府，以加尼骑手而闻名。", "h": "尼基是巴托努（巴里巴）王国的摇篮，根据传统，该王国是由瓦桑加里骑兵建立的。每年农历的加尼节都会聚集数千名身着盛装的骑兵围绕在国王周围，举行壮观的游行。皇宫和加尼博物馆全年都可以参观。"}, "ja": {"n": "ニッキ、王宮、ガーニ祭り", "d": "ガーニ ライダーで有名なバートンブの歴史的な首都。", "h": "ニッキは、ワサンガリ騎手によって伝統に従って設立されたバーアトヌ (バリバ) 王国の発祥の地です。毎年、旧暦に基づいて開催されるガーニ祭では、儀式用の衣装を着た数千人の騎手が王の周りに集まり、壮観なパレードが行われます。王宮とガーニ博物館は一年中訪れることができます。"}}};
